window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20130225-9","meetingId":"h25-cm02","date":"2013年2月25日","dateIso":"2013-02-25","committee":"文教委員会","time":"午前１０時００分～午後５時４３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を109件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第１８号議案、品川区女性福祉資金貸付条例の一部を改正する条例","agenda":"の第１８号議案、品川区女性福祉資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今説明いただきましたけれども、この１１の貸付資金というのは、改めてちょっと確認したいのですけど、どういう対象者がこの貸付を受けられるようになるのかということと、そもそも品川区の場合、以前に名称を改正して女性福祉資金というふうになりましたけれども、もともとは母子福祉資金だったかな、全然違いますか、ちょっとその辺の経過も含めて教えていただきたいのと、三つ目は。","respondent":"安井子育て支援課長","answer":"名称が変更になったというのは、婦人という表現があまり好ましくないということで、東京都での改正を受けまして、女性というふうな名称変更がされたということですので、今はあまり婦人というのは使わないような形で名称が変更されたという経緯があります。","voiceIndex":9,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"そうしますと、母子世帯がその対象になるという、そこのところは、改めてちょっと確認したいのですけれども、２５歳以上の女性で、６カ月以上の区民ということですが、その２５歳以上の女性というのは、母子世帯のお母さんということなのか、ちょっとその辺整理ができていないので教えてください。","respondent":"安井子育て支援課長","answer":"ちょっと説明が足りませんでしたが、東京都母子福祉資金というのがございまして、こちらのほうは２０歳までのお子さん、母子家庭につきまして、これと同様な資金を貸し付けておりますが、こちらはいわゆる法定受託事務のような形で、東京都からお金を直接お預かりいたしまして。","voiceIndex":11,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そうしますと、貸し付けしている実績というのが、もう一度どの程度、どういう状況なのかをちょっと聞きたいですけれども、あと利息があったのか、なかったのか、あったとしたら、どの程度のものなのか、それぞれの仕組みごとに教えていただければと思います。","respondent":"安井子育て支援課長","answer":"修学資金につきましては、平成１５年度から一番多い年で９件ほどお貸しをしている。平成２４年度につきましても、これは初めてではなくて、何年か継続する形の方がほとんどですので、今年は５件ほどお貸ししているというようなところが実態です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"ここの品川区が持っている貸付条例が一番最初の相談の窓口になるということですよね。その辺というのは、どうしてそういうふうになっているのですか。","respondent":"安井子育て支援課長","answer":"基本的に社会福祉協議会のほうは、東京都の社会福祉協議会の制度の窓口になっているという形になっておりまして、例えば母子福祉資金の貸付が受けられない場合、あるいは女性福祉資金の貸付が受けられない場合、あるいはこれは例えば学生支援機構の一種、いわゆる無利子のもの。","voiceIndex":15,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"実績がないのであれば、きちんと周知をし、使い勝手のいいものに改善こそせよ、社会福祉協議会のほうがあるということで、そちらに全部送ってしまうというのは、改めてちょっとどういう見解、考え方を持ってそうしたのかというふうに思いますけど、利息をつけない部分も幾つもあるわけで、その辺りというのはどういうことなのか教えてください。","respondent":"安井子育て支援課長","answer":"他区では、うちの区と同様にこの２本だけに貸付を絞るとか、条例自体を廃止するとか、そういった自治体も大分増えてきているという中で、何らか実態、例えば社会福祉協議会のほうの制度自体が、大分この間拡充されてきたり、あるいは事業開始に関しては創業支援の資金であるとか。","voiceIndex":17,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"ちょっと聞いたつもりだったのですけども、答弁がなかったので、自治体の責務というところから見たときに、そういう品川区が今回改正をしようとしていることについて、私はセーフティーネットである制度であれば、そこをさっきも言ったように使い勝手のいいように、あるいは不十分なところを改善する、そういうことこそするべきだというふうに思いますけれども。","respondent":"安井子育て支援課長","answer":"もちろんほかの制度があれば、そちらのほうを有効に活用していただく、全て区がそれをお金としてお貸しするのがいいのかどうかというのは、ちょっと全てそれを担うというのは、なかなかそれは難しいことではないかというふうに考えているところです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"何回か事前に伺ったりもして、本当に社会福祉協議会のほうのそういう利息ゼロの体制が確保されているのであれば、いいのかという判断を一時しましたけれども、やはり自治体の責務というふうに考えたときに、簡単にそういうふうに判断することは誤ってしまっているのではないかとちょっと思い直して、今改めていろいろ伺ったりしておりますけれども、しかも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"確認","question":"何点か確認させてください。事業開始資金から結婚資金までの間、これが廃止になるということでいいのですかというのが１点と、それから、この資金の受け皿は今度どこになりますかということ。あるからこそ変えていくと思うのだけれども、そのことの確認をまず２点お願いします。","respondent":"安井子育て支援課長","answer":"基本的に、事業開始資金から就学支度資金までの１１の資金については、社会福祉協議会のほうは全てあります。","voiceIndex":22,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"そういう合理的な理由があるわけですね。それは繰り返し言いますけども、やはり担当課では、懇切丁寧に説明することをお願いすると同時に、例えばそこでもう一度受け付けることはできるのでしょうか、社会福祉協議会の融資の制度。だから、そういうところについてのお考えをぜひお伺いしたいと思います。","respondent":"安井子育て支援課長","answer":"現実に、私どもは保証人がなかなか見つからないという方につきましては、全て社会福祉協議会のほうの資金についてご説明をさせていただいて、直接その窓口になることは基本的にはできないですけれども、そこら辺についてはご説明を十分しています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"しかも保証人なしで借りられる制度をつくりましたよという判断ですよね。となれば、要は今まで貸付条例で対象にならなかった方にとってはメリットになるわけですから、そういうところについて、やはり効果的な説明をしていかないともったいない気がいたします。なかなか行政側は答弁が下手なところがあるだろうと思いますけれども、最後にメリットへの対処方法についてのお考えをお聞かせください。","respondent":"安井子育て支援課長","answer":"そういったことでも社会福祉協議会の資金のほうは、保証人も要らなくて、緊急の場合もあると思いますので、なるべく早くということを考えますと、むしろうちのそういった資金があることによって借りられないというような、逆に不利益を与えるようなことにもなりますので。","voiceIndex":26,"id":"exchange-010"},{"speaker":"鶴委員","kind":"質問","question":"ここにも、改正理由に書かれてあるとおり、社会福祉協議会のほうに紹介する、先ほどご説明のあった対応があると思いますけれども、こういう改正のときに当たって、やはりある意味では先ほどもありましたけれど、問い合わせも含めて継続的に接続可能であることを考えれば、対応のサービスの拡充、窓口サービスの仕組みが変わりましたとかとわかりやすい内容のチラシを周知と。","respondent":"安井子育て支援課長","answer":"女性福祉資金の対象になる方というのは、限られてはおりますけれども、なるべくそういうふうなものが一覧できるようなものをつくって、窓口に設置するとか、もちろんいろんなお金をお貸しするときには、経済状態とか。","voiceIndex":28,"id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"ぜひお願いいたします。大体それぞれの事業でも、そんなに２０件、３０件という対応件数ではないと思いますので、丁寧な説明をするよう心掛けていただければと思います。以下同じ。）」を加えるとありますが、この部分については、対象範囲が拡大とか、そういう考え方ではなくて、子という家系ですかね、それを明確に用意したという、どういう位置づけで改正するのか教えてください。","respondent":"安井子育て支援課長","answer":"こちらは、明確にするということで実際上行っているところなので、実態に合わせて取組みの中で改正したです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"私から、３点お伺いしたいと思います。一つ目ですけれども、一応考え方を伺っておきたいと思います。見直しのＣ評価ということが続いていたということで、この条例を適用すると、確かに社会福祉協議会よりも使い勝手が悪い。結果的にこういう方法をとられたのはどういうご判断だったのか伺います。","respondent":"安井子育て支援課長","answer":"それをさらに拡充するのが果たして望ましいのか、１％という利子も、こちらのほうはついてしまいますので、それを全部外してしまうのかということになりますと、やはりそちらのほうで。","voiceIndex":32,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"区が直接資金を貸し付けるというのは、あまり複雑でないほうがいいと考えていますので、社会福祉協議会の制度とかぶるところがあるというのであれば、そういうのは精査をして利用しやすい形にするほうがよいと思います。二つ目の質問ですけれども、今借りている人の扱いとして、何年か継続で借りていらっしゃる方もあるかと思いますけれども、そういった方の扱いはどのようになるのですか。","respondent":"安井子育て支援課長","answer":"平成２３年度もございませんでしたし、本年度についても実績がございませんので、こちらについては社会福祉協議会のほうをご利用いただくというご案内をさせていただければ、対応としては可能ではないかというふうに考えているところです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"だけど、社会福祉協議会の制度が今後縮小した場合には、品川区としてはその分というのをまた条例の中につくっていこうという思いというのはあるのでしょうか。要は、プラスして両方使い手がいいというふうになっているときはいいですけれども、社会福祉協議会の動向に合わせて品川区としても随時見直していくという考えがあるのかどうか、現段階ではありますけれども、伺っておきたいと思います。","respondent":"安井子育て支援課長","answer":"そういう状況が来るかどうかは、はっきり今の段階ではわからないですけれども、この条例全体を根っこから完全廃止するわけではありませんので、それぞれそのときの状況に応じて検討させていただいてという形です。","voiceIndex":36,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問・要望","question":"最後に要望になりますけれども、整合性があるといっても、やはり人様の制度ですので、社会福祉協議会の制度というのは。ですので、それを前提にして今回の条例改正する以上は、今後の社会福祉協議会の制度の変化、動向というのは常に注視して、穴があかないようにしていくということを今後にわたって強く求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"廃止をする部分の事業開始資金と事業継続資金というのは、相談に来た場合、どこにつなげようというふうに代替制度としてご紹介していくのですか。","respondent":"安井子育て支援課長","answer":"というのは、一旦資金があれば、事業をやっていくわけなので、ある程度継続的に銀行との関係も当然つくっていかなければいけない世界だと思います。中小企業だけではなくて、個人貸しという制度もできてきておりますので、そこら辺のところ、事業をいかに継続的にやっていくか。","voiceIndex":39,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"要するに中小企業センターのほうに紹介して、そしてそこであげられればいいというふうに思うし、そういう銀行とかいろいろ経営相談を受けられて、そのことは悪いことではない。むしろいいことだと思うので、それはそれとして伺いたいとは思いますけど、私が質問したのは、条例そのものは女性福祉資金貸付条例ですよね。福祉ですよね。そこだけ１点聞きたいと思います。","respondent":"安井子育て支援課長","answer":"もちろん社会福祉協議会のほうでも事業資金の貸付制度はありますので、そういった方についてのフォローはされておりますし、また、ひとり親世帯のほうは、基本的には自立していかなければいけないという観点に立ちますと。","voiceIndex":41,"id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"したがって、先ほどから申し上げているように、態度についても申し上げたいと思いますが、この貸付条例を９事業を廃止して２事業だけは残すということですけども、ほかの事業もこのまま必要性はあると、そういうふうに思いますので、現実的に数は少ないけれども、ご相談にはおいでになっていると、そういうところはやはりしっかりと自治体としてはそういう窓口は開いておくべきだというふうに思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-019"},{"speaker":"南委員","kind":"意見","question":"さっきも言ったように最初はちょっと悩みましたけども、しかし、自治体の責務、福祉の部分を大きくなくしてしまうという点で、この九つの貸付資金についてなくなってしまうという点については、賛成はできかねるということで、この改正には賛成できません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-020"}]},{"id":"topic-02","title":"の議員提出第４号議案、品川区保育の実施等に関する条例の一部を改正する条例","agenda":"の議員提出第４号議案、品川区保育の実施等に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"提案","question":"平成２５年度の予算に積み増しという品川区の基金、去年度、平成２３年度に財政執行して、２９億円余の黒字というか、基金積み増し額が明らかにされておりますので、その中でそれぞれの基金に振り分けるわけですが、とりわけこれの使い道が決められているものではない、財政調整基金、ここのところに２９億円のうちの６億３,１００万円を積み増すということになっておりますので、こういう部分を見ても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"提案","question":"それで、いろいろ調べましたけれども、地方自治法第２２２条の解釈においては、予算を伴う条例案の議員提案にあたっては、執行機関と連絡の上、財源の見通しを得る必要があるとされているところ。これに対して岐阜県の多治見市が、議員の条例提案権に対する首長の関与を排斥し、その運用の実質を担保するとともに、予算の不可分一体性の維持のための制度的な保証を求める。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-022"},{"speaker":"南委員","kind":"提案","question":"区長に条例提案しますということと、内容についての説明は、２月６日に、すみません、日付は定かではありません、申しわけないですが、させていただきました。そして、そのことは提案説明の中には入れませんでしたし、今もまたそのことについての紹介はいたしませんでしたけれども、区長とも懇談はさせていただき、そこに副区長と企画部長も同席をしていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"提案","question":"懇談はなさったと思いますけれども、このことについての具体的な区長としての対応については、おそらく聞いていらっしゃらないと思うのですよ。この予算の提案について区長がどう思ったということについて。だから、私たち区議会議員として思うのは、執行されるかどうかわからないような条例をどうぞ出しましょうということには賛同できないですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-024"},{"speaker":"南委員","kind":"提案","question":"しかし、その中でやる手順というのはきちんとやっていくということは、それはやらなければいけない部分ですから、やるべきでありますけども、考え方としては、議会側の見解、議会側の総意でもって区長のほうにお願いをしていくということは、これに限らず今までもやってきていることだというふうに思いますので、今のご意見には、私はそういうふうには思わないということは申し上げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"意見","question":"４月１日からの新しい保育料の条例に関しては、ここで相当議論しましたし、それから本会議でも賛成討論もされたわけです。だから、そういうことを前提として考えていくと、非常にこの時期にもとに戻す条例については、私ども議会がはいわかりましたということは言えないということが現実です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-026"},{"speaker":"阿部委員","kind":"意見","question":"私ども改正による保育料の金額については、いろいろ出そうかどうかという声もありますけれども、ただ、私ども昨年からずっと言っていますように、保育料を決定する際には、やはりきちんとそれなりの組織を立ち上げ、審議会等あるいはそれに準じるような形で立ち上げて、十分な審議のもとで保育料というものを考えていくと。そういったことを主張しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-027"},{"speaker":"南委員","kind":"提案","question":"提案者と一人なのでダブっておりますけれども、自民党から主にご質疑いただきまして、ご意見をいただきましたけれども、皆さん、大方賛同はしていただけないということになっているのかという感じですが、甚だ残念です。しかし、態度表明するときは、ぜひこういう理由で賛成できないということは伺いたかったというふうに思っておりますので、今回は表明がなかったので甚だ残念です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"ただいまご説明がありました荏原第四中学校のところですけど、青陵学園高等部へ貸し付けるのはいつまでですか。","respondent":"齋藤庶務課長","answer":"所管が違うので、お答えするのは適当ではありませんが、おおよそ１年半ぐらいはお貸しできると思います。","voiceIndex":72,"id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"失礼しました。ちょっとそのあたりの確認と、それから本来４月以降子どもが小学校と中学校の児童・生徒がどのくらいの数になるのか、正確な数がわかった時点で、先ほどの平米数に応じての面積というのが一定程度の計算式で出ますよね。それで、出したときに、どの程度の広さになるのか、私の試算では１万２,７５０m2ですけれども、それでいいのかどうか、ちょっとその辺を確認したいと思います。","respondent":"齋藤庶務課長","answer":"いただいた試算ですけども、これは３５人学級ということで大体１万２,０００m2ということになりますけれども、生徒実数、今のところの想定の人数で差し込みますと、１万４,０００m2ぐらいになります。","voiceIndex":74,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"その答弁に基づいて質問するしかないので、その数を受けとめていきたいと思いますけれども、アッパーで１万４,０００m2ということですよね。先ほども教育上支障がないというふうに説明されましたけれども、教育上支障がないというのは、どういうことから導き出してこういう表現になっているのか、まずそれについて伺いたいと思います。","respondent":"齋藤庶務課長","answer":"豊葉の杜学園５,８３０m2、それから平塚学園は４,８７２m2、伊藤学園は３,９００m2、日野学園４,４００m2、品川学園１万２,６２１m2、八潮学園４,７００m2、児童・生徒１人当たりにしましても、約１m2ぐらいほかの学校よりも大きいし。","voiceIndex":78,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどの説明では、１人当たり２５.５m2、校地面積というふうなことでしたよね。これ、間違いでしたら訂正しておきたいと考えていますけど、その当たりを確認したいのですが、校庭ではなくて、学校全体の敷地で２５.５m2というふうに説明されましたけども、１人当たりの面積にすると、ちょっと改めてそこのところとこの校地面積との違いというのを教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"先ほどお出しした数字は、東京都における小中学校の一つの現状といった内容です。ここにグラウンドの面積という考えはございません、校地の面積です。校地イコール学校のゆとり、グラウンドの面積はニアイコールと考えましたのでご紹介させていただきました。","voiceIndex":80,"id":"exchange-032"},{"speaker":"南委員","kind":"確認","question":"それで、この間の質疑をもう一回振り返って請願を読んでみましたけれども、１人当たりのグラウンドの面積、ここで言うと豊葉の杜学園は４.８m2、日野学園、伊藤学園は豊葉の杜学園より若干狭いですけれども、伊藤学園はとりわけ運動会のときは保護者の方の観覧は、校庭の同じレベルで見られなくて、校舎の中に入ってデッキから見ていると、そういうふうなことを何回か聞いた記憶がありますけれども。","respondent":"太田指導課長","answer":"豊葉の杜学園はどっちもできるというようなことを考えると、運動会の観覧という意味においては恵まれているほうではないかというふうに考えております。","voiceIndex":82,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"人が質問をしているときに、途中からそんなことを言わないでください。失礼ですよ。先ほどから２回目です、今日、これで。やめていただきたいと思います。そういうのがとれるのかどうかというのを図面だけですから何とも言えないですけれども、今日は見られなかったので、それで質問しているわけですけれども、その辺はどういうふうに区としては考えているのか、そこを聞いたのです。","respondent":"齋藤庶務課長","answer":"観覧場所で言うと、校庭の前のこの部分、あるいは左側にある砂場の脇にオープンスペースがあります。デッキもありますし、十分観覧することはできると考えております。いろいろやりようはありますので、トラックの使い方は。","voiceIndex":86,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"やめますので、どうぞやってください。後で質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-035"},{"speaker":"伊藤委員","kind":"確認","question":"こういう請願を見ると、当然日本中を探せば、特に大都市では基準未満の学校もたくさんあるはずです、校庭が。むしろそれぞれの学校が狭い中でも工夫をして、子どもたちにさまざまな場所を確保しているわけであって、ことさら豊葉の杜学園、確かに基準はそうかもしれないけども、このところだけが教育に支障があると私は判断できないけれども、それでよろしいですか、まずその１点、確認します。","respondent":"齋藤庶務課長","answer":"委員ご指摘のとおりです。","voiceIndex":90,"id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だけれども、近隣のオーナーが売らないということですから、それはないものねだりですよ。どんなに品川区が頑張ってこの隣地を買おうとしても、この方が売らないという以上は買えないわけですから。それは先ほどの説明によれば、しながわ中央公園の運動場を優先的に利用できると伺いましたけども、それは確認するのだけど、そうなのでしょうか。","respondent":"齋藤庶務課長","answer":"しながわ中央公園につきましては、教育施設は６カ月前から優先的に予約ができることになっておりまして、それで青陵学園と品川区のほうでしながわ中央公園をお借りしている。６カ月間は学校工事の期間だけ青陵学園が使用し、平成２５年度は品川区です。","voiceIndex":92,"id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうやって考えていくと、この請願の言っていることはわかりますよ、基準値を求めていきたい、それはそのとおり。それであと、私たちができることは、将来できるだろう５,５００m2の校庭の中で、十分工夫をしていただいて、この豊葉の杜学園から子どもたちの教育上支障が絶対出ないように、それは学校に工夫をしていただきたいのだけども、そのことはやはり確認の上、お願いします。","respondent":"齋藤庶務課長","answer":"小中一貫校につきましては、これまでも５校あります。体育館を含め、さまざまな工夫をしながらカリキュラムを組んで、小学校・中学校の先生が一生懸命取り組んでおります。豊葉の杜学園でも運動・教育上支障がないように学校は運営してまいります。","voiceIndex":94,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめますけど、おっしゃっていることはわかりますよ、その基準の広さを求めていく。それは全ての学校が求めているわけで、やっていくが必要がある。校庭の拡大については。それからあと、しながわ中央公園の運動場が優先的に利用できるというのであれば、それを最大限活用していただいて、子どもたちの教育環境に影響が出ないような対応をぜひご努力いただいて、態度を言っていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今日中にお出しいただいて、不採択ということを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-040"},{"speaker":"鶴委員","kind":"質問・要望","question":"ちょっと参考までに、不勉強で事前に確認できなかったので教えていただきたいのですが、この請願に添付されている資料の学校教育法第３条の省令第１４、それから第１５、今議案に合わせるとここに示されている数字だよというのがありますけれど、このいわゆる基準ですよね。何のためにその数字になっているのかという、その部分というのはあるのか、もしわかれば参考までに教えてください。","respondent":"田村教育次長","answer":"教室と特別教室と体育館が基準を満たすと補助金の基準の一つの目安という考え方で、ただ、全国の一律の規律なので、都市部についてはなかなかその基準どおりといっても、先ほどの荏原第六中学校もそうですけど、敷地面積そのものが小さいですから。","voiceIndex":99,"id":"exchange-041"},{"speaker":"鶴委員","kind":"確認","question":"そうすると、どちらかというと、これは事前に法律を読めていればよかったのですけど、児童・生徒の、例えば保育の基準みたいに何か両手を広げてぶつからないよとか、そういう基準ではなくて、今教育次長からご答弁いただいた、どちらかというと金銭的というか、そういう資金的な部分の色合いのほうが強い省令という位置づけでよろしいか、その辺を確認したい。","respondent":"田村教育次長","answer":"それは先ほど南委員が言っている要素はもちろんあります。とは言いながら、これが設置基準で、これが建てられないという基準だと、品川区内、先ほど、品川学園を除いて全部がいわゆる既存不適格となってしまいますから、そういうことはありません。一つがそれです。","voiceIndex":101,"id":"exchange-042"},{"speaker":"鶴委員","kind":"意見","question":"もっと都心というか、ビジネス街というか、そういうところの中にある学校を私もいろんな形で見た記憶があって、非常に猫の額よりも狭いのではないかと思われるような、何かでも工夫をして授業等を行っている学校を幾つも見た経験があるので、そうした中でこういうぎりぎりのところで確保している、なおかついろんな検証の結果の中で教育上支障がないというご見解だと、私は今の現状の中で理解をしましたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-043"},{"speaker":"阿部委員","kind":"質問","question":"改めて請願項目に沿って幾つかお伺いしたいと思います。今、しながわ中央公園を１年間のみの優先利用ということで、今のところ決まっていると思いますけれども、今後どこかの土地を一定借りるなり何なりして、教育活動の中で利用していくというような考え方というのは、工事が終わった後について、教育委員会は全くないのでしょうか。","respondent":"齋藤庶務課長","answer":"近隣の土地でまとまったところを活用するかということは、今のところ考えはございません。","voiceIndex":104,"id":"exchange-044"},{"speaker":"阿部委員","kind":"質問・要望","question":"今ご答弁をいただいた直後なので違う答弁が出てくるかどうかわからないですけれども、今お考えがないのであれば、今後ぜひ検討していただきたい。いろいろな形で子どもが活動する場をつくっていくという、賃貸地でもつくっていくというような、あるいは一時借りでもつくっていくというようなことでも、物を考えていってもいいのではないかと思いますが、教育委員会としてのお考えを伺いたいのですけれど。","respondent":"齋藤庶務課長","answer":"例えば、品川学園、日曜日は広く開放、それはサッカー、野球といった活動に参加して使える。そういった形で幾つか学校だけではなくて、子どもが地域の中で、地域資源を活かしてということでは、さまざまな例があると思いますので、この点については少し考えていきたいと思います。","voiceIndex":106,"id":"exchange-045"},{"speaker":"阿部委員","kind":"質問・要望","question":"学校活動以外でということもありました。やはり思春期、特に中学生ぐらいの子どもたちというのは、身体的に、肉体的に活動する場というのはどうしても発達の上で必要だと私は思っております。今回、子どもの発達ということ、あるいは心身両面での成長ということを考えていただいて、ぜひこれについては今後も深く研究をしていただければと思います。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-046"},{"speaker":"高橋委員","kind":"確認","question":"それからあと、大きな問題になるのは体育の授業だと思いますけど、小規模のクラスの学校と一貫校での体育の授業で、制限なくアリーナなどを利用しながら、全部で３３クラスですか、マックスだと、体育の授業が教育活動に影響がないような、カリキュラムに応じて時間割を組んでいけているのかどうか、これが可能ならば、豊葉の杜学園でもやっていけるのではないかと思うのですね。","respondent":"齋藤庶務課長","answer":"ついては、子どもの安全についても当然高まるもの、それは学校建物、誘導、あとは避難階段も教室から２０ｍのところに避難具が必ずありますので、避難訓練は施設ができてから学校のほうも十分行いますので、その辺の対応はできていると思います。","voiceIndex":109,"id":"exchange-047"},{"speaker":"渡部副委員長","kind":"質問","question":"二つお伺いしたい点がありまして、この請願に直接関係ないかもしれないですが、請願に関するところは伊藤委員のほうから言ったとおりです。直線走路が１００ｍとれるというのはすごいと僕は思っておりますが、品川区内で直線走路１００ｍをとれている学校というのは幾つありますか。","respondent":"齋藤庶務課長","answer":"人工芝の予定はありません。１００ｍ直線走路は、品川学園、荏原平塚学園、豊葉の杜学園の３校です。","voiceIndex":111,"id":"exchange-048"},{"speaker":"渡部副委員長","kind":"質問","question":"先ほどほかの委員のほうからの発言で、基準値云々というのはわかりました。であるから、この１００ｍ直線走路というのがとれるという意味では、非常に教育の幅に広がりが出るのかと。それで、地元の方からの請願ですのであれですが、この学校というのは、今１３町会の避難所になっているのですか。〔「所管ではない」と呼ぶ者あり〕はい、すみません。直線走路の件について結構です、すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"項目１の新たに確保してくださいというのは、先ほどの説明の中で難しいというのは承知しているところですけれども、しかし、新しく学校を開設するに当たって、できるだけいい環境を整えるということは言うまでもないことでありますので、しかも同じような請願というのは、過去にも何だったでしょうか、出ているというところで、一定の努力はするべきだというふうに思うし、民有地の購入が難しいことであれば。","respondent":"齋藤庶務課長","answer":"都内で学校を建て替える場合、大変難しいです。例えば、今グラウンドがあったところは、昔は校舎でした。建て替える場合、グラウンドがなくて、体育館だけしかないという学校も数多くあります。","voiceIndex":114,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"それから二つ目に、所管が違うので、違うと一刀両断にされてしまうかもしれませんけれども、あえて伺いますが、ＪＴ跡地を買いますよね、他の目的で。そこには、区の今までの説明では、建物は建てないというふうになっているので、一定の校庭として代替できる、どこまでできるかどうかは別としても、そこをある程度借りるということは考えられないのでしょうか。その辺りをちょっと伺いたい。","respondent":"田村教育次長","answer":"全部が、４校が母体校で、全部豊葉の杜学園に入ってくるのではなく、今の既存の大間窪小学校や杜松小学校がどれだけ避難所として活用できるのかということを算定して、残りは当然豊葉の杜学園に入るということで防災課と協議していますので。","voiceIndex":116,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"でも、１,０００人ぐらいの子どもたちが集まってきて、それで果たしていいのかどうかと、そういう点を問題にしているのであって、だから、ほかに確保してほしいという要求が出てくるわけで、私はその子どもの人数を学校の規模に合わせてしっかりと確保するという、そういう覚悟の上で品川区は一貫校にしても、ほかの学校の改築にしても当たっていただきたいというふうに思っておりますけども。","respondent":"齋藤庶務課長","answer":"繰り返しになります。繰り返しになりますが、品川区は先ほど申し上げたとおり、取得に向けて努力をしております。そして、学校の敷地面積、一貫校を含めて、豊葉の杜学園は遜色ありません。他の一貫校でも教育活動上問題はございません。豊葉の杜学園でも当然問題はありません。","voiceIndex":118,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"そのことで１人当たりの平米面積がぐっと広がったという状況もあり、それは９割の補助がつくということで決断をされたわけですよね。そういうことがなくて、努力はしているとおっしゃったけれども、そこまでどうだというような打診をしていただきたいし、確保する努力をこれからも引き続き行っていただきたい、そのことをあえて強くお願いしておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今日、結論を出すということでお願いします。それから、しながわ中央公園の運動場の利活用も、それは１年しかできないのかもしれないけれども、できればさまざまな代替施設をつくってくださることをお願いしておきます。それからあと説明、何回もここで言いますけれども、こういうことについて説明するというのは、本当に適切にやっていただきたい。これこれこういうことだということについては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-054"},{"speaker":"鶴委員","kind":"質問・要望","question":"結論を出すで、不採択。この理由は、先ほど示させていただきました。それとあと、別の委員からもありました、今後校庭になる場所は今プレハブ仮校舎が建っています。ここで当然避難訓練等が行われる。それに当たってのシミュレーションですとか、それを早目に行って、そうしたところもきちっと安全を確保されるということも含めてきちっとやっていただきたい、これはお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-055"},{"speaker":"高橋委員","kind":"質問・要望","question":"結論を出すということで、不採択。先ほどお話したような形で、支障のないようにさまざまな方策を講じていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-056"},{"speaker":"阿部委員","kind":"質問・要望","question":"結論を出すということでお願いしたいと思います。２番目のほう、これは具体的にこの場所でなくても、あるいは豊葉の杜学園に限らなくても、やはり考えていただきたいと思っています。後半のほうは要望にもなりますけれども、今回の請願項目については、私たちは同意できませんけれども、ただ、今のような方法というのはぜひ教育委員会として確認をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-057"},{"speaker":"南委員","kind":"確認","question":"皆さん、今日結論を出すか出さないかのところで態度まで言ってますので私も言いますけれども、２番については実際やっているという、努力はしていただいているということがわかりましたし、運動場確保についても、今回はなかなか無理だけど、そういう立場で努力はしてきたというふうなことで、十分不十分はありますけれども、そういう姿勢はあったというところは確認できたかというふうに思っておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-058"},{"speaker":"阿部委員","kind":"質問・要望","question":"ちょっとそこを確認させていただきたいのと、一応子どもプールだったと思いますが、近隣のお子さんが多く通っているのが現状ではないかと思うのですね。そういった方々というのは、豊葉の杜学園に移るときに、ある程度、優先してというのも何ですけれども、今子どものプール教室というのは結構倍率が高かったと思いますけれども、入りにくくなってしまうものなのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、先ほど申したように、平日の児童水泳教室は非常に倍率が高く、人気があり、そういうことができないというような回答でした。土曜日は今申し上げました未就学のお子さんは、継続的に優先して行うというようなお話でした。","voiceIndex":136,"id":"exchange-059"},{"speaker":"阿部委員","kind":"質問","question":"私もすぐそばに日野学園があるものですから、すまいるスクールに行って、プールが終わってからすまいるスクールに戻って迎いに行けると、そういうことができるのは、この学校だよねと言って選んでいらっしゃる親御さんもたくさんいらっしゃいましたし、また目当てだった水泳教室に抽選で外れて非常にショックを受けていらっしゃる親御さんもいたり、あるいは今年は大丈夫だからとか。","respondent":"和氣学務課長","answer":"ですから、水泳が１０時間しっかり確保できるということになると、それは学校の教育課程の編成上の問題ですので、時期が変わるだけの問題であって、あえてそんなに強く説明する必要はないというふうに思っていた節はあると私は理解しています。","voiceIndex":138,"id":"exchange-060"},{"speaker":"阿部委員","kind":"質問","question":"要するに、この部分が本当にボタンのかけ違いのスタートラインであるかと思います。教育委員会としては、今後スケジュールの見直しなどの考えはありませんか、その理由についても教えてください。","respondent":"和氣学務課長","answer":"説明が不足しましたが、先ほどもご報告したように、２月２日に行いました新１年生と新７年生の説明会の場でもこのプールの説明を行い「やりません」という内容でお話をさせていただきましたが、１件もご意見がない、質疑もないということでした。","voiceIndex":140,"id":"exchange-061"},{"speaker":"阿部委員","kind":"質問","question":"この陳情を見て非常に悩ましいと思うのは、一方では、ほとんどご意見はないのだと。この陳情を見ると、陳情の署名者が参考も含めると３,０００人を超えている。一体民意の中心はどこにあるだろうというのが非常につかみにくいと思っているのですが、ちょっと一旦ここで私も質問を区切ります。もう少し整理してから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-062"},{"speaker":"伊藤委員","kind":"確認","question":"ガラスの天井にしたというところから始まって、設計のところでね。２３度まで下がる。そうなれば、この運用はできたのかもしれない。確認したいのは、議会も同意しましたけれども、そういうことを考えずに設計したのか、ガラス天井というのは。もともとなぜあそこにガラス天井をつくってしまったのかというところから始まっていかないと、この問題はすごく解決が難しいですけども、いかがですか。","respondent":"和氣学務課長","answer":"聞き及んでおりますのは、先ほどご説明しましたように、最初の基本設計をする段階で、温水にするかどうかという検討があったときに、温水にしなくても屋上ドームにすることによって、例えば荏原平塚学園もそうですけれども、荏原平塚学園と同様な形にすれば。","voiceIndex":143,"id":"exchange-063"},{"speaker":"伊藤委員","kind":"意見","question":"それでも、なかなか環境改善がされなくて、先ほどのお話だと全面床暖房を入れたり、ヒーターを入れたりして、結果としてコストが上がっていったことにつながっていくけれども、導入部分で設計の段階で、行政の段階でもう少し知恵を働かせて、そういう将来的なことを予想できなかったのかという質疑をどうしてもしたいのだけど、答弁ありますか。","respondent":"和氣学務課長","answer":"詳細まではちょっと私が答えるべき立場ではないと思いますけれども、その際に、もし、やり直しをすると基本設計からやり直さなければならないので、さらに１年かかり、基本設計のその分の経費も億単位でかかるということ。","voiceIndex":145,"id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問・要望","question":"でき上がってしまっているものですから、いまさら言っても始まらないのかもしれないけど、だけど、先ほどの説明を聞くところでは、そういう設計自体に問題があったのではないかということは指摘しなくてはいけないかと思います。特にこういうことに関して。そのときに、議会がきちんと説明を求めていきます。だから、その気持ちにどう応えていくのですかということはぜひお伺いしたい。","respondent":"和氣学務課長","answer":"それで、私どももそういう声を聞ける、聞けると言いますと失礼ですけれども、変更ができるものであれば、そういう対応をしたいとは思います。しかし、行政責任として、やるべきことはやらないといけない。","voiceIndex":147,"id":"exchange-065"},{"speaker":"伊藤委員","kind":"質問","question":"それはわかるけど、なかなかそうではないという意見を聞いていますので、改めて指摘をします。やはり、これだけ情報社会の中ですから、なぜ今の時点で伊藤学園プールを止めることを品川区が考えたのかということを、理論的に、客観的に説明していかないと、多くの皆さん方は理解できないと思うのです。そのことは指摘をしておきます。このことについて何か答弁はありますか。","respondent":"和氣学務課長","answer":"利用料については、利用料の設定自体が採算を取るような利用料にはなってございませんので、例えば倍にしたからといって採算が取れるかというと、そこは全然、設定の仕方が違いますので、そこらの説得力はないかというふうに思ってあります。","voiceIndex":149,"id":"exchange-066"},{"speaker":"鶴委員","kind":"質問・要望","question":"幾つか確認したいのですが、ちょっとベーシックなところで、前回の９月２５日のときにも、文教委員会のやりとりの中で、南委員の質問に対する学務課長の答弁の中で、そもそも温水と加温の違いですね。もう一回ちょっと整理の意味で、この場で教えていただきたい。","respondent":"和氣学務課長","answer":"５月とか１０月のちょっと寒いときに少し温めることができるレベルの装置を持っているのが加温です。それを温水にするために熱交換機の容量を上げたりとかして、冬場でも温度を上げられるようにするのが温水です。ですから、通年ずっと使ってもやれるようなのが温水です。","voiceIndex":151,"id":"exchange-067"},{"speaker":"鶴委員","kind":"質問・要望","question":"ちょっと細かく聞いていくことになると思いますけど、ちょっとご答弁いただきたいのですけど、それで、そうすると、いわゆる水とか、もともとお湯を沸かして、それをプールの中に注入する、水が入っているところを温めていく、そういう違いが技術的にあるのだろうと私は理解しましたけど、それだけでは当然部屋中に蒸気が充満するというような感覚であると、先ほど言ったように。","respondent":"和氣学務課長","answer":"そうです。ですから、今日ご覧いただきました豊葉の杜学園では半地下にプールがあって、温度が逃げないようにして、そこの中で処理できるようにしています。ところが、ドームですとどんどん温度が逃げていく、どんどん逃げていくという構図になってしまう。","voiceIndex":153,"id":"exchange-068"},{"speaker":"鶴委員","kind":"質問","question":"それで、あと、私もちょっといろいろ個人的にこの陳情が出てから調べてみたのですけど、ちょっと明確な違いが出ていなかったのですけど、要は中身がそういう加温式というものであるものに対して、設備に対して、温水プールという表向きの名称、これをうたっていいものかどうか、要するに罰則とかそういうことではなくて、その程度のレベルの範疇のものなのかどうかということをちょっと教えてください。","respondent":"和氣学務課長","answer":"基本設計段階で加温でしたら、先ほどご説明させていただいたところですが、実施設計段階でその出力を上げて温水として運用できるように、ですから、もっと冬場のときも温水が上がるような熱交換機に交換をしていく。ですから、出力を上げています、当初よりですね。","voiceIndex":155,"id":"exchange-069"},{"speaker":"鶴委員","kind":"意見","question":"要するに水の部分というか、プールの中身だけをそういうふうに一生懸命やっても、周りの設備、それが今日見させていただいた豊葉の杜学園のように熱を逃がすだとか温度を調整する、その設備が整って完結して温水プールと、そういう位置づけなのだろうか、そこだけちょっと。","respondent":"和氣学務課長","answer":"実は、それも先ほど言ったように２０台のヒーターと床暖房で温まると考えた節があります。","voiceIndex":157,"id":"exchange-070"},{"speaker":"鶴委員","kind":"質問・要望","question":"幾つかちょっと加えて質問したいのですけど、そうすると、前回のときも私の質問の中で、当然そういう技術屋というか、メーカーのほうからそういうつくりにしたら、冬寒くて夏暑いよというような事態が想定されるという話はあったというのは確認できているので、その中でのこの数年は努力を重ねて運用してきたと、これはわかります。ちょっと記述としてはここまでの記述しかないです。","respondent":"和氣学務課長","answer":"ざっと公表されていいと思います。いろんな説明の中で、今度資料をお渡ししますけども、この基本設計から実施設計に至る過程の問題は若干混乱されていると思います。それから、温水プールでなければ運用できないという話はそもそもありませんので、そこは違う話だと思います。","voiceIndex":159,"id":"exchange-071"},{"speaker":"鶴委員","kind":"確認","question":"私も今回この陳情の方々、その他の方、私自身も今年の２月１６日に行われた説明会にも出席をした中で、出席者等のやりとりをお聞きする中で、９月２５日に伊藤委員のほうから議事録で確認する中でも、本当に丁寧な説明を、私もそういうふうに申し上げた。当然一貫校ですから、約９年間、陳情の中にも９カ年という部分がありますけれど、それなりの決意をされて、ここの区域内に引っ越しをされてきた。","respondent":"和氣学務課長","answer":"ただ、そういう中で、学校教育活動の場ですので、トータルとして、保護者の方に満足いくような教育を水泳指導も含めまして、これは５月から１０月という長い期間水泳指導ができますので、しっかりそういう水泳指導、また今度、夏は専用できますから。","voiceIndex":161,"id":"exchange-072"},{"speaker":"南委員","kind":"確認","question":"その失言、発言で、このことの問題点を全部において終息するというのは正しくないというふうに思います。そのような経過があったのかどうかというのをまず確認したいと思います。その点についてはどうでしょうか。そんなことはなかったということですか。","respondent":"和氣学務課長","answer":"そのために温水プールにして何とかしてくれという話は聞いていません。技術上の問題については、その当時の技術者たちが一生懸命やって、それで何とかなるというふうに考えていた節はあります。","voiceIndex":163,"id":"exchange-073"},{"speaker":"南委員","kind":"確認","question":"どうなったのかとちょっとさっき疑問に思ったので、改めて確認しましたけども、やはり技術上の問題がないというふうに専門家から言われれば、それ以上の疑問というのはなかなかないかもしれないけれども、しかし、費用がかかるわけですよね、新たに設置するわけですから。しかし、そういうことが積み重なって今日のような状況になっているという、そこのところの認識というのはいかがですか。","respondent":"和氣学務課長","answer":"確かにその過程の中で、なかなか私たちの理解が十分でなかった部分はあるかもしれませんが、それは何とか運用したいと、何とか期待に応えたいということで努力を重ねてきたということでご理解をいただきたいというふうに思います。","voiceIndex":165,"id":"exchange-074"},{"speaker":"南委員","kind":"質問","question":"私は住民の方に説明するときに、まずそこをしっかりと姿勢を示すことが大事だというふうに思うのですよね。当時は皆さんの思いもあって受け入れたけれども、結果的にこうこうこういう状況が重なって今日に至ってしまったと。その辺についてはどうですか。","respondent":"和氣学務課長","answer":"そういうふうになかなか聞き取れなかったのかもしれませんけども、私どもとしては、本当に地域の皆さんに使っていただけるように、先ほど申しましたように様々に検討して、何とかできないものかというふうに考えて、しかし、あの震災以降に節電とか。","voiceIndex":167,"id":"exchange-075"},{"speaker":"南委員","kind":"質問・要望","question":"そのことはしっかり言っておきたいと思います。しかし、区民のそういう要望に対して、区はどのように思っているのか、教育委員会だけでなくて、文化スポーツ振興課長も来ておられますけれども、ここでは一貫校のプールなので、教育委員会と、それからできたら文化スポーツ振興課長のほうからもご答弁いただければと思いますけど、見解をちょっと表明していただきたいと思います。","respondent":"和氣学務課長、安藤文化スポーツ振興課長","answer":"数の問題、これについては文化スポーツ振興課長のほうからお答えします。そんな中で、プールについては順次このように開放させていただいて、倍になった温水プール数に対して３万人の増、これをどう見るかということですけども、区民の皆さんにも水泳だけにとどまらないで、水中ウォーキングだとか。","voiceIndex":169,"id":"exchange-076"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、箇所は６カ所に倍加したけども、利用者数は３万人しか増えていない。そういうことを言いたいのかとちょっと聞きたいですけども、やはりそういう現状はあるかもしれないけれども、プールに対する区民の期待、要望はどうなのかと、そこのことについて聞いたのですけども、その点、ちょっと改めて確認したいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"そんな形で従来の水泳、泳力向上よりも、水泳を通して健康づくりをしていく方々が非常に多くなった統計です。各温水プールにつきましても、それなりの水中ウォーキングコースだとか、そういうものを設置させていただきまして、十分応えているところです。","voiceIndex":172,"id":"exchange-077"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことだというふうに思うのですよね。水泳だけでなくて、夫婦でのさまざまなウォーキングだとか、エクササイズをいろいろやることによって健康保持できると、したがって、そういう機会、場をたくさん提供することが区民の要望であり、それに応えて６カ所建設してきたというふうに私は思っておりますので、やはり必要な事業だというふうに思います。その辺についてはどうなのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"この夏の節電でいろんなところで節電をしてまいりましたが、夏について伊藤学園プールの水質の冷却装置をちょっととめたところ、非常に高くなって苦情が来たりだとか、伊藤学園自体が水泳のよい環境の中で泳ぐことができないような状況がずっと続いていました。","voiceIndex":174,"id":"exchange-078"},{"speaker":"南委員","kind":"質問・要望","question":"なぜ、ここにこだわるかというと、そういう考え方でずっといけば、今までプールをあちこちでやっていたけども、現実的にですよ、やれというつもりは全然ないですから誤解しないでいただきたいですが、例えば八潮の一貫校では、利用数が非常に少ないと言われています。そういうことからすると、今回のこの閉鎖してしまうという、このことは逆行ではないですか。","respondent":"和氣学務課長","answer":"これは伊藤学園のケースでございまして、先ほどから文化スポーツ振興課長が申しているように、快適な環境を提供できない、節電が問題ではなくて、快適な環境を提供できない、このことが構造的にわかった。これも大きな理由です。","voiceIndex":176,"id":"exchange-079"},{"speaker":"南委員","kind":"質問","question":"確かに温度差の開きがあるというところは、それは事実だから、それについてはどうしようもないと私もどういうふうにしたらいいかという工夫や考え方は持ち合わせていません。しかし、例えば設定する環境をもう少し専門家に知恵をかりて、こうすればいいのではないかとか、こういうふうにやればいいのではないかとかと、そういう方向で検討したのでしょうか。","respondent":"和氣学務課長","answer":"先ほどから繰り返し申し述べているように、プール運用してから苦情がたくさん来ていますので、そういう技術者の方にはいろんなアイデアをいただきながら、ですから、私どももわざわざフィルムを見に行ったり、実験をしたところを見たりして、フィルムを張ると割れてしまうとか。","voiceIndex":178,"id":"exchange-080"},{"speaker":"南委員","kind":"質問・要望","question":"私はこの７７４万円余が、他の施設と比較する材料をちょっと持ち合わせていなかったので、今全然検討しないままの数字で来てますけども、確かに７７４万円余はかかっているけれども、そして、これからいろんな設備をするとしたら、それ以上にかかるかもしれないけれども、しかし、業務委託料の３分の１の部分と６８％を掛けるわけですから、全体的に見れば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-081"},{"speaker":"高橋委員","kind":"確認","question":"一つだけ。先ほど説明会のことのお話があったのですが、理事者の方のご答弁だと、そういった説明不足というか、理解していただかない点があったとすれば、区のほうに責任があるという、責任という言葉はお使いにならなかったかもしれませんけど、その点についてもう一回確認したい。","respondent":"和氣学務課長","answer":"チラシや２回の説明会等で説明させていただいて、しかしながら十分理解していただけないとすれば、やはり一つ説明の仕方が問題であると、丁寧さに欠けるとは思ってありますが、先ほども申しましたように、全体として。","voiceIndex":181,"id":"exchange-082"},{"speaker":"大西委員","kind":"質問","question":"それと、子どもたちのそういう水泳教室とか、そういった面でもデメリットはあるかと思いますけども、端的にこの件に関しては、例えば高齢者であれば、他の施設的なものを設けて筋力の弱体化を抑えるための代替案があるとか、そういう子どもたちへの救済方法というのでしょうか、そういったものを先ほど他の委員がおっしゃっていましたけど、区長のおっしゃる健康増進のための環境整備。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、荏原文化センターには指導の方が水泳教室をやっていたりだとか、また総合体育館、日野学園でも水泳連盟の方たちが必死にやっていますけれども、やはりまず環境を第一義的に考えるということで。","voiceIndex":183,"id":"exchange-083"},{"speaker":"大西委員","kind":"質問","question":"それとお子さんが通うという距離感、そういったもの等々を考えて、行政の知恵ということで、例えば、思いつきということで大変恐縮ですけども、「ちぃばす」というのですかね、港区でも小さなバスを走らせているようですけど、そういうシャトルバス系のようなものでずっと何カ所かあるスイミングの場所を回らせるとか、定期的な時間に、子どもにとって、それから高齢者の方々にとって。","respondent":"安藤文化スポーツ振興課長","answer":"健康行政になりますので、まずお話をいただきましたものについては、その部にお話を申し上げたいと思っています。","voiceIndex":185,"id":"exchange-084"},{"speaker":"阿部委員","kind":"質問・要望","question":"これまで質問しましたが、幾つか確認させていただきたいと思います。１点、一応確認ですが、教育委員会がおっしゃっている電気量の問題というのは、電気料金ではなくて、使用する電力、電力量の問題であり、行政あるいは公的機関としての電気使用量を削減する社会的責任という意味での電気削減ですよね、正確に言うと。","respondent":"和氣学務課長","answer":"当初の説明は、電気使用量、料金ではなくて、量の問題を説明させていただきましたが、途中、質問の中で経費はどうなのかと聞かれましたので答えたわけで、経費が削減できるからという形での説明をしたつもりはないですが、そういうふうにとられたとしたら、非常に残念です。","voiceIndex":187,"id":"exchange-085"},{"speaker":"阿部委員","kind":"質問","question":"わかりました。学校という大きなものを改築するときに、基本設計が決まってからではなくて、できるだけ最初の段階から地域の声を聞いていくというスタートラインの問題であろうかと思いますが、このときには基本設計が終わってから地域の声を聞いたという順番でいいのでしょうか。そして、今はどうなっているのでしょうか。","respondent":"和氣学務課長","answer":"基本設計の段階で、地域の代表の方は入っています。検討委員会に地域の代表の方も入って検討して、必要ないのではないかと言われたのですが、実施設計に当たって説明会等をやるとか、だんだん広まってくるに従って、そういうお声が上がったです。","voiceIndex":189,"id":"exchange-086"},{"speaker":"阿部委員","kind":"質問","question":"次、夏も冷却しないと泳げないというのは、素朴な疑問ですけど、加温プールとしても、ちょっと形状、欠陥とは言いませんけれども、どうでしょうね。夏はまともに泳げないと加温プールとしても問題があるのではないでしょうか。","respondent":"和氣学務課長","answer":"ですから、室温がどんどん高くなってしまう。そういう構造もあるです。","voiceIndex":191,"id":"exchange-087"},{"speaker":"阿部委員","kind":"質問・要望","question":"一貫校では窓があけられなくて、子どもの学習環境がかなりひどい状態になっていますので、その辺のバランスというのはぜひ学校や教育委員会はよく考えていただきたいと思います。それから、これは安藤課長にお伺いいたしますけれども、品川区内の温水プールの適正数あるいは配置というのは何か考えていらっしゃいますでしょうか。結果的に何カ所になりましたという話なのか、どうなのですかね。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、人口に対して幾つ、あるいは標準的なことは今手元に資料がありません。","voiceIndex":193,"id":"exchange-088"},{"speaker":"阿部委員","kind":"質問・要望","question":"２３区で手元に資料がないとおっしゃっていましたが、大体人口１０万人に１カ所ぐらいの感じですよね。〔「何カ所」と呼ぶ者あり〕１０万人に１カ所程度。最後にちょっと要望ですけれども、児童の水泳教室、非常に要望が高いと聞いております。ハード面だけでなくて、ソフト面でもプールの要望に応える体制をぜひつくっていただきたいと思います。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-089"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、そういう合理的な理由づけを含めた上で、それから数字等も含めた上で、より具体的な説明をしていただきたいという思いが強くあるのですけれども、つまり、陳情を見る限りでは、そういう説明はなかったということになっているわけだから、今この委員会で初めてそういうことが出てきたのであったのなら。","respondent":"和氣学務課長","answer":"陳情にはこう書いてありますけど、この内容はほとんど説明しています。説明会で今回説明させていただいた内容の多くは話をさせていただきましたし、数字もお出ししております。資料としてはお配りしていませんけども。ここはちょっと私としては理解ができないです。","voiceIndex":196,"id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何回も言って申しわけないですが、説明するという度合いの、何て言うかな、どう説明したらいいだろうな、私たち区議会議員ですから、皆さんもそうですが、区民に接しているでしょうけれども、物事を説明して理解を求めようとするならば、行政が難しい言葉を使ってやるというよりも、すごくその人のところまで話をわかりやすく懇切丁寧にやっていかないと説明はできないと私は思うのですよ。","respondent":"和氣学務課長","answer":"そのだろうをやめて、必ず確認をするという形で実際に説明したかどうかも含めて確認するようなシステムをつくって、漏れがないように、意思統一のずれがないようにしていきたいと考えております。","voiceIndex":198,"id":"exchange-091"},{"speaker":"鶴委員","kind":"質問・要望","question":"先ほどの、もう一回確認をさせていただきたいのですけど、これは学校の選択に当たっての説明会だったと思うのですよね。今の品川区の学校に入る中では、その地域に住まないといけないという説明もある。そういう個別の対応、先ほどはプールの確保で何とか対応したいという答弁をいただきましたけれど、それ以外のところで、それができることがほかにあるかどうか、ここをもう一度確認したいと思います。","respondent":"和氣学務課長","answer":"確かに伊藤学園は大変人気がありましたので、問われれば、どうすれば確実に入れますかと言われれば、学区内に住むことが確実ですというふうにしか私どもとしてはお答えできません。これ以上でも、これ以下でもございません。","voiceIndex":200,"id":"exchange-092"},{"speaker":"鶴委員","kind":"質問・要望","question":"お恥ずかしい。すばらしい、すばらしいと思っているところの中で。そういった意味でも、そこはきちっと、本当にこれ以上具体的なところは申し上げませんが、本当にできる限り、最大限のそうした誠意を検討いただきたい、このように思いますので、どうかそこは本当にお願いしたい。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-093"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"１点だけです。僕らの会派でも話をしましたし、例えば、そのタイミングで、実は地域に知っている人がいたりして、何かのやりとりを私たちが議員としてしたときに、いやいや私たちは議会の報告ですから、議事録が出ますし、公表される話であって、そこで、いや、そんなことはないよと言っても、校長先生、そう言っていたよと。大きな問題の一つが今回はここにあったと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問・要望","question":"取扱いについて確認させていただきたい。こちらの質問ではなくて、扱いですけど、６号で一緒ですよね。一緒にやるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-095"},{"speaker":"伊藤委員","kind":"質問・要望","question":"請願第６号は、今日結論を出すということでお願いしたいと思います。それから、まとめて意見を言いますけども、今回、教育委員会にぜひお願いしておきたいのは、さまざまな施設の設計段階での問題、それは場所であり、位置であり、トータルのランニングコスト等々の条件をまず十分に確認していただきたいというのがまず１点。それから、経年劣化に対する施設改修の対象ですね、その計画。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-096"},{"speaker":"鶴委員","kind":"質問・要望","question":"本当に事前の議論の中で、この委員会の中で納得できる説明がまたあって、要望も含め、きちっと受けとめるかどうかというところも含めて継続かどうかということも、本当に最後の最後まで議論しながら、またこの委員会に臨みながらそれも考えましたけれども、最後、先ほど申し上げた個別の対応も含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-097"},{"speaker":"高橋委員","kind":"意見","question":"今日結論を出すということで、各委員の方々がお話したことはもう繰り返さないですが、先ほどお話があったように、説明会での説明や区民に対する説明については齟齬というか、不十分であったというお話があったので、その点に関して今後きちっとご理解いただけるような丁寧な説明を、９月にもお話しましたけど、そこをお願いして、先ほどもあったように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":209,"id":"exchange-098"},{"speaker":"阿部委員","kind":"意見","question":"私はこの請願については継続ができないかと考えております。少なくとも要するに内容というよりも、安全という理由以外にかなり教育委員会の説明と請願者の間にかなり齟齬があるように感じました。ぜひ、さらなるご説明を尽くして、調査がもう少しわかり合った形で物事が進んでいくのがいいと思いますので、もう少しここで時間が欲しいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":210,"id":"exchange-099"},{"speaker":"南委員","kind":"意見","question":"あと節電について、区は今年度、平成２５年度も１５％のマイナス目標を掲げており、これが品川区内の本庁を含めて最近全ての事業所にこういう目標を持たせておいて、平成２２年度と比較して１５％だと、こういうところが学校側の４割の電力使用量があるという現実を気持ち的にクローズアップさせてしまったことになっているのではないかというふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-100"},{"speaker":"伊藤委員","kind":"提案","question":"特にこの陳情については説明を求めることが相当ありますので、先ほど言ったように構造的な問題があるとか、それからこれ以上、技術的な対応が困難であるとか、そういうより具体的な説明をぜひやっていただきたいということは何回もお願いしておきます。ただ、繰り返しますが、全体の部分については、きちんと教育委員会に対処を求めることをお願いしておきます。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":215,"id":"exchange-101"},{"speaker":"鶴委員","kind":"質問・要望","question":"ですから、そもそも学校の立場としては、常温のプールで、一般開放のほうは想定をしていない、そういう前提に立つのかもしれませんけれども、結果そういうふうに一般開放等をやったほうが幅広い形で区民の皆様にサービスを提供できる。そういうふうに私は危惧をしている部分がありますので、その上で説明をしっかりと尽くしていただきたいということをお願い申し上げた上で、本陳情については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問・要望","question":"ただ、掻い摘んでお話しさせていただいて、一つは、署名の数字、４,０００人近くの方のこういった陳情というのは大変多いものであるということで、理事者の方々にご答弁いただいて、せんだっての説明会等の話については、９月のご答弁の中で、区全体で意思決定したというふうなご答弁がありましたので、当然文教委員会の中で、全面に出るのは教育委員会になるかと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-103"},{"speaker":"阿部委員","kind":"質問・要望","question":"今回の陳情を大きく二つの内容があります。一つは説明不足、もう一つは一般開放について。ただ、その意思決定の手続ですとか、終始一貫、説明のあり方、そういったことでは皆さん指摘されているようにさまざまな課題があると考えています。いま一度説明を尽くしていただきたいという意味で、それは先ほどの請願と同じ発想ですけれども、継続ができないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-104"},{"speaker":"南委員","kind":"質問・要望","question":"私はこの陳情の１点目が、納得のいく説明を求めるということですよね。ですから、質疑の中でも納得のいく状況にはなかったということが改めてわかりましたので、それは本当にこのとおりだと、陳情のとおりだというふうに思っています。","respondent":"金野委員長","answer":"ご意見いただきました。本日のところは、この陳情に関して結論を出す、あるいは継続にするというご意見がありましたので、この点を挙手により採決を行いたいと思います。この本陳情を継続することに賛成の方は挙手を願います。","voiceIndex":219,"id":"exchange-105"}]},{"id":"topic-03","title":"報告第３号、専決処分の報告","agenda":"報告第３号、専決処分の報告","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"教えてください。このサッカーゴールからボルトが突き出ていたということですけど、それは簡易式だから、構造上そういうものが出ているものということですか、それとも普通に使っていると、それは出ていないけれども、管理の問題でそれが出ていたということですか。","respondent":"齋藤庶務課長","answer":"施設の問題もありますので、ご答弁申し上げます。簡易型のボルト、型枠、ボルトにナットが出ています。この部分はゴムのラバーがついていた。ほかの部分はついておりましたけど、たまたま事情はわかりませんけど、ゴムが外れていて、児童が当たって、切れてしまったです。","voiceIndex":226,"id":"exchange-106"},{"speaker":"高橋委員","kind":"質問","question":"今、校長先生が後から指導されたということですが、７月２６日だと夏期休業中ですけど、クラブ活動で児童が負傷したということで、クラブ活動中の事故なので、学校のほうがということですか。","respondent":"太田指導課長","answer":"クラブ活動中の事故です。おっしゃるとおりです。なお、児童と申しますのは、児童福祉法上で記載しておりますので、実際は中学生です。","voiceIndex":228,"id":"exchange-107"}]},{"id":"topic-04","title":"の５、その他","agenda":"の５、その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それとの関係があるのか、それとの関係でちょっと気になったのですけども、日野学園ですから、そこの耐震ではなくて、点検する学校ではないわけですよね、新耐震ですから。だから、そこで起こってしまったということなので、きちんと耐震性のある学校でも、もう一度点検するということが大事かと思ったので、その点について十分やっていただきたいというふうに思っております。","respondent":"齋藤庶務課長","answer":"日常、安全に管理されてあります。今回、カビが表面でわかりましたので、その時点で、例えば、このエリアは入らないだとか、一定の対応をすべきだったというふうに考えております。","voiceIndex":233,"id":"exchange-108"},{"speaker":"阿部委員","kind":"質問・要望","question":"不具合を見つけてから施行までの期間というのは、できるだけ短ければ短いほうがいいわけで、そこはぜひ短く工夫をしていただきたい。これは要望しておきます。それからもう１点、この事故があった後、その後にプール教室が中止になっていますけれども、その連絡についても、いろいろと短い期間に不満の声が入っています。それについてはまた調査をして、改善を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-109"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4784#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":81870,"voices":236}},{"id":"h25-20130225-5","meetingId":"h25-cm02","date":"2013年2月25日","dateIso":"2013-02-25","committee":"総務委員会","time":"午前１０時００分～午後０時０３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"進め方ですが、会議の運営上、予定表の順番を変更し、(4)と(5)の議案から先に審査を行いますので、あらかじめご了承願います。 では、初めに","agenda":"進め方ですが、会議の運営上、予定表の順番を変更し、(4)と(5)の議案から先に審査を行いますので、あらかじめご了承願います。 では、初めに","exchanges":[{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点目、この新型インフルエンザ等という「等」は、基本的に新型インフルエンザの対策本部条例だと思うんですが、これは国から多分こういうふうに「等」がついた状態で来ているんだとは思うんですが、その「等」の意味合いが何なのかというのを１点お知らせいただきたいのと、１ページの第２条、組織の部分で、本部長、副本部長までは、その次の３ページの部分である程度理解ができるんですが。","respondent":"武内危機管理室長","answer":"そんな中で、国のほうでは施行後、現在、国の新型インフルエンザ対策行動計画というのがあるんですけれども、それを二、三カ月後には、全面改訂ということが予定されているんです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ちょっとその２点目の部長部分がよくわからなかったのですけれども、これは第２条のところで、本部には本部長と副本部長と本部員、要は区長、副区長、教育長と、本部員が各事業部長が任命されるであろうというのがある。その下にある部の中での部長という、この部長と書いてあるのは、事業部長の部長という意味なんですか。２点お願いします。","respondent":"武内危機管理室長","answer":"それと、今までとの違いは、いわゆる国のほうがこの新型インフルエンザ等対策本部条例を制定するというのは、今まで法的根拠のしっかりしたものがなかったという、そこが一番のポイントになりまして、従来からこの対応というのはやっているんですけれども、実際のところ、今回。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"では最後にしますが、そうすると組織の部分の部長というのは、イメージ的には本部員が区の職員のうち部長級の方がなられると想定した場合に、ここで書かれている部長というのは、課長級の方がなられるという理解なんですか。それとも事業部長が本部員を兼ねての部長をやられるのか、そこだけ再確認させていただきたい。これは要望で終わります。ちょっと部長のところだけ、改めて最後、お知らせください。","respondent":"武内危機管理室長","answer":"すみません。なかなか要領を得ない説明で申しわけないです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"第４条のところなんですけれども、重要な事項を審議するという項目が入っているんですが、まだこれからというところもあると思うんですが、どういった中身をイメージしたらいいのか、ちょっとその辺と、第５条のところに、必要な事項は規則でと、これも規則が見えてこないので、この辺もどういった中身をイメージしたらいいのかということを教えてください。","respondent":"武内危機管理室長","answer":"それで感染予防及び蔓延防止に関する措置に関すること、また医療の提供の確保に関すること、また予防接種の実施に関すること、またさまざまな物資が必要になりますので、物資の確保、それと関係機関との連絡調整等。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"かなり大変な中身が盛り込まれてくると思うんですけれども、国の法律を見たら８条からなっているんですよね。そういう心配もいっぱい具体的には出てくるんですけれども、それでちょっと重要事項のところを伺ったんですけれども、そういった細かい事項というのは、今後のこの品川区新型インフルエンザ対策行動計画のところで具体化されていくという捉え方でいいのか、そこが１点です。","respondent":"武内危機管理室長","answer":"それで、催し物等を強制的に中止にするだとかいう部分の議論があるというのは私も聞いておりますけれども、やはり世界的規模のこの新型インフルエンザが発生して、過去の大きな死亡につながるようなことになれば、その辺は事業者のほうに委ねるということがいいのか。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"確認","question":"今、短時間で決められた云々で、パブリックコメントが行われているということなんですけれども、これは、今、例えば品川区民から意見を出せるような状況にあるのかどうか、ちょっとその辺を、多分公聴会とかいろいろ開いて広く意見を聞いてやってほしいという部分の反映かなと思って、今、伺ったんですが、その点を一つと、あと今までも計画にのっとってやっていたという部分では。","respondent":"武内危機管理室長","answer":"ワクチンというか、品川区では備品類については、平成２１年に発生した教訓を交えてマスクを５０万枚用意してあるとか、手洗いの消毒液を保管しているだとかいう対応は今現在もしております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"最後に１点だけ。この本部の体制というのは品川区の内部のことであるので、医師会とか医療機関とか、そういうところの関係というのはこの中には全く含まれないという認識でよろしいでしょうか。","respondent":"武内危機管理室長","answer":"この品川区新型インフルエンザ等対策本部条例の中に、きちんと当然関係機関との会議に出席していただくとかいうのでは関連が出てきますけれども、具体的にこういう拘束するような部分ということではありません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"阿久津委員","kind":"質問・要望","question":"先ほど石田（慎）委員の質問の中のところで一つ確認させていただきたいんですけれども、このインフルエンザ「等」というところのご説明があったと思うんですが、コロナウイルスとかそういったものも考えてというようなこともあったんですけれども、これは目的のところの背景を見ると新型インフルエンザに対応してという、それで国のほうで法律が決まったといったことなんですけれども。","respondent":"武内危機管理室長","answer":"言われたとおり、従来からその辺に対応をする法はあるんですけれども、その辺が明確化されていないという部分がありますので、今回この新型インフルエンザ等対策特別措置法ができたということです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"阿久津委員","kind":"質問・要望","question":"今、新型インフルエンザ以外の爆発的な感染症等が発生した場合に、品川区も対応していただけるという認識で私も理解をいたしました。細かいところは、これから品川区新型インフルエンザ等対策本部条例施行規則とか品川区新型インフルエンザ対策行動計画で対応されていくということなので、またお医者さんの判断というのが重要になると思いますので、医師会等との連携をしっかりしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"２ページ目に行くと、これは区も行政区、特別区とかいろいろと意味合いがあると思うけれども、この下のところにおいては、図表の中の一番右のところの「市町村対策本部」ということで、上の丸のあるところの一番下のところにも「区域に入っていない市町村も」ということで、このところの表記というのは、これは別の意味合いなので区が入っていないのか。","respondent":"武内危機管理室長","answer":"それと、私どものつくった資料とこの３ページにあるこの資料につきましては、事前に説明しなくてはいけなかったんですが、この資料につきましては国のほうで新型インフルエンザ等対策特別措置法の説明をするための資料をそのまま引っ張ってきて。","voiceIndex":22,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"２点目は、国の資料とこちらのほうは区でということでわかりましたけれども、さっきの危機管理室のことで、前回インフルエンザが発生したときに危機管理室を設置して、危機管理室長が、先頭に立ってやられたということで、副本部長のところに先ほど教育長、副区長ということでお話を伺いましたけれども、やはり先頭を切ってやられる担当であれば、やはり横一列の本部員という形ではなくて。","respondent":"武内危機管理室長","answer":"従来から品川区の場合については、危機管理対策本部要綱の中でそういう危機管理的な対応はしてきて、危機管理室長が中心というか、そういう事務局的なところで全庁的な調整をしているわけですけれども、今後、このインフルエンザの部分の内容については。","voiceIndex":24,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"何が言いたいかといいますと、これは防災のときでもそうですけれども、やはり命令系統、命令と言ったらちょっと表現がいいのかどうかわかりませんけれども、意外とこの伝達事項が曖昧なゆえに、迅速な対応ができないという部分があるやに私は思うので、そこらのところの弊害をなくすように、やはり組織づくりをするのが大切なのかなと思いまして、今、質問させていただいたので、検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"どんどん国からいろいろおりてきますよね。じゃあ、伝染病が発生した。どうなんだ。新型ウイルスが発生したらどうするのだというときに、本当に動けるんですか。というような、区の中だけでも相当の業務を区民のために仕事をしているわけなので、その辺、大丈夫なんですかというか、逆に危機管理に関して大丈夫なんですかという疑問を抱いていたんですが、その辺どうなんですか。","respondent":"武内危機管理室長","answer":"委員が言われるとおり、災害等の防災対策などでも、その辺、防災対策本部条例というのがある中で、今回、新型インフルエンザに対してもそれなりの明確化していこうということで、全庁的な取り組みにしていこうということになっておりますので、委員が言われたとおり。","voiceIndex":27,"id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"この間も、ダニからウイルスが感染して死亡したという話も、これも何も品川区も例外ではないなんていう感じになっています。セアカゴケグモというようなものもあるし、やはり何か専科でひとつやっていかないと、相当の危機管理がこの国内で叫ばれていますので、その辺、対応等よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-014"}]},{"id":"topic-02","title":"の第３３号議案、勝島運河雨水貯留施設建設工事請負契約","agenda":"の第３３号議案、勝島運河雨水貯留施設建設工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この工事の基本的なことを一つお伺いしたいのが、勝島運河の水質の改善ということなんですが、いつごろから検討されて、ちょっと決定までの経過でわかる範囲を一つ基本的なところを教えていただきたいのと、初期雨水を貯留するということですけれども、どのくらいの量がここが完成すると貯留されるのか、量的なところを教えてください。","respondent":"武藤河川下水道課長","answer":"２件のご質問に、私のほうからお答えいたします。１点目の検討の経緯ですけれども、具体的な本工事の検討につきましては、平成２４年度設計を行いまして、具体的な施設の形状だとか内容を決めたものです。","voiceIndex":42,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"今年度設計に入るということなんですが、お伺いしたのはそれ以前のことで、どういった地域の状況を把握してこういう工事の決定になったか。都の委託ということですけれども、その辺の前のほうの経緯をお伺いしたかったのが１点と、４,７５０トンの雨水というすごい量だと思うんですけれども、完成して、これでどのくらいの改善というか効果があるのかというあたりも聞かせてください。","respondent":"武藤河川下水道課長","answer":"この工事は、いわゆる合流式下水道と言われる東京の区部の下水道のシステムが、一部こういった汚水がどうしても大雨のときに流れ出てしまうものを改善するという、いわゆる合流式下水道の改善事業と言われるもので、これにつきましては、東京都下水道局は。","voiceIndex":44,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"この契約の中身をお伺いしたいと思いますが、１点目は指名競争入札になっているのはなぜかという率直な疑問で、今までの契約を見て、かなりの金額、９億円以上の金額のところ、なぜ制限付き一般競争入札とかそういう形にならなくて、これが指名競争入札になっているのかという率直な疑問が１点です。入札の予定価格の表示がないんですが、それはどうしてなのかなというのが１点。","respondent":"平澤経理課長","answer":"３点にわたるお尋ねです。１点目、指名競争入札を導入した理由です。こちらにつきましては、制限付き一般競争入札を２回にわたり実施したところです。","voiceIndex":46,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その後のことなので、その辺をちょっと教えていただきたいのと、９億円台、１０億円台のところが何者もあって妥当だというところなんですけれども、この辺というのは、積算の中身というのは多分企業の秘密だからわからないと言われると思うんですけれども、この辺で公共事業の技術とか品質というのはどういうところで担保できるというのか、低価格、一番安いところで決めてしまうというあたりで。","respondent":"平澤経理課長","answer":"この落札者につきましては、現在２１件の同じようなシールド工事を実施しているということで、信頼のおける業者ということで、こちらに決定させていただいたところです。","voiceIndex":48,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"２回の制限付き一般競争入札のときの予定価格の表示が幾らだったか、教えてください。","respondent":"平澤経理課長","answer":"失礼しました。申しわけございません。こちらにつきましては１７億６,０００万円ほどになります。","voiceIndex":50,"id":"exchange-019"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、予定価格が１７億６,０００万余円ということで伺いました。最初にちょっとお伺いしたいのは、この予定価格が１７億６,０００万余円と、この落札した９億３,０００万円という数字の対比の中で、この都の落札率というのは大体どれくらいの落札率なのか、まず教えていただきたいと思います。都というか、２３区の平均の落札率というのはどのぐらいなんでしょうかということです。","respondent":"平澤経理課長","answer":"申しわけございません。２３区平均でというのは、私どものほうではちょっと数字がございません。土木の落札率ということでお答えしますと、大体９割ちょっとぐらいというふうになってあります。","voiceIndex":52,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"土木ということで、今、お話を伺ったんですけれども、９割ということ、ちょっとこの予定価格１７億６,０００万円、それと落札したこの９億３,０００万円という数字になると、今、お伺いした割合よりもかなりの率、下がってくるという、その相差についてどのようにお考えになっていらっしゃるか教えてください。","respondent":"平澤経理課長","answer":"繰り返しの答弁で恐縮です。こちらの落札者、清水建設に関しましては、現在２１件のシールド工事を実施しているということで、例えばなんですけれども、東京都発注工事で全長１,２４６メートル、内径が２,６００ミリメートルという工事をやってあります。","voiceIndex":54,"id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"なぜ６億円というような、確かに各社いろいろな積算方法の違いがあるということなんですけれども、この６億円という相差を見た場合に、これが大きな数字なのか、それとも小さい数字なのか、その相差についてどのように分析をされているのか、教えてください。","respondent":"平澤経理課長","answer":"６億円ということは大きな金額であるとは考えてあります。その大きな金額であることからこそ、逆に建設会社につきまして、どうしてこういう価格で落札できたのか、これまでの経験はどういうことがあるのかということを調査というか、ヒアリングさせていただいたです。","voiceIndex":56,"id":"exchange-022"},{"speaker":"大沢委員","kind":"質問・要望","question":"もとに戻ります。２３区の土木に関する契約の落札率が９割ということでお話をいただきました。今回の品川区のこの部分に関しては五十数％だと思いますけれども、かなり差があるんですけれども、そこのところの数字を加味しながら、今の６億円の相差の部分についての説明をもう一回いただきたいと思います。","respondent":"平澤経理課長","answer":"繰り返しで本当に申しわけございません。こちらの落札者が現在２１個のシールド工事を実施しているです。そういったところで、かなり部材や、また集中発注ということで、金額について努力することができたということを聞いてあります。","voiceIndex":58,"id":"exchange-023"},{"speaker":"大沢委員","kind":"意見","question":"ノウハウというか工事実績があるということですけれども、今、ここに１番から１５番までということで会社が並んでいますけれども、それはそれなりにやはりノウハウ、技術というのは持っているところで、私はこの６億円という相差については、その、今、課長がおっしゃった特殊な技術、特別なノウハウという部分と、この相差についての工事のやり方、省き方。","respondent":"平澤経理課長","answer":"入札状況調書のところです。先ほどご説明いたしましたが、９億円台が２者、１０億円台が２者、１１億円台が４者あります。ちょっと離れまして１２億円台、１５億円台ということになってあります。","voiceIndex":60,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、平均値ということで、そこの中でとった平均値がということなんですが、もう一回伺います。先ほどの五十数％のこの予定価格に対する入札価格、これは低くないですか。それともどうなんですか。これは妥当な数字なのか、ちょっとそこのところのお考えをお示ししていただきたいと思うんですが。","respondent":"平澤経理課長","answer":"こちらにつきましては予定価格ではなくて、この場合は見積価格になっているです。従前の制限付き一般競争入札での予定価格が参考ということでお話しさせていただいたところです。","voiceIndex":62,"id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"確かに行政が発注する仕事ですから、安ければ安いに越したことはないんですけれども、安かろう悪かろうでは、ごめんなさい、表現に語弊があったら申しわけないんですけれども、しっかりとした、安くてもなおかつ質の確保が担保できるような入札方法といいますか、そこら辺をやっていただきたいと思いますので、それをお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"２点お伺いします。１点、これは晴天時に、本来この貯留したものを水再生センターへ送って水を再生する。これは４ページの断面図で貯留管はわかったんですが、この貯留管がここにあって、水再生センターまでどのように送り込んでいくのかというのがもしわかったら、ちょっと細かくなってすみませんけれども、教えていただきたい。その辺、なぜだったのかというのを教えてください。","respondent":"武藤河川下水道課長、平澤経理課長","answer":"ためた水をどのように水再生センターへ送るのかというご質問です。このエリアにつきましては森ケ崎水再生センターという大田区にある水再生センターに送る予定ですが、これは既存の下水道管のシステムを使いまして送ります。今回の指名競争入札のほうでも、辞退が５者出てあります。この５者の内訳なんですけれども、ほとんどの部分、３者が専任の技術者が準備できないということでございました。","voiceIndex":65,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"清水建設は大手で、間違いなく工事をやってくれるのは大丈夫だと思うんですけれども、例えばこういう契約をしたときに、施工するのは全く清水建設がやるのか、それとも、今、品川区内の業者というお話がありましたけれども、区として区内の業者に下請け部分をある程度任せるように依頼をするのか、そこら辺はどういうふうに考えているんでしょうか。","respondent":"平澤経理課長","answer":"そういったところで対応していただくというところを期待しています。","voiceIndex":68,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そこで、逆に区内業者が依頼を受けてやるということ、それは向こうの経営判断でしょうけれども、これだけの単価でいくと厳しいんじゃないかなという気がするので、そこら辺を区としてどう評価するのかという、そこだけもう一回質問させてください。","respondent":"平澤経理課長","answer":"金額の中で、それぞれの協力会社を受注者が使っていくということになるわけですが、私どもといたしましては、区内企業の育成ということは大事な役割ですので、そういったところにつきまして特段のご配慮をお願いするです。","voiceIndex":70,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"賛成します。一言だけ。先ほど品質管理の話がありましたけれども、安全性のところも十分配慮して、先日事故が起こりました。一次、二次の下請けのところの方々の安全性のところも十分配慮して、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-030"}]},{"id":"topic-03","title":"の第１１号議案、品川区職員定数条例の一部を改正する条例","agenda":"の第１１号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"阿久津委員","kind":"質問・要望","question":"ちょっと一般区民の感覚で、３ページの特に生活福祉課に関してなんですけれども、国でも、今、非常にあり方について議論がされていて、区のいろいろなお話を聞くと、１人のケースワーカーが非常に平均よりも多くの方を担当されていて、１００名を超える方を担当されているというお話をよく伺うんですが、そもそもこの定数削減、増やすということの増減については。","respondent":"堀越人事課長","answer":"その他、その保護世帯の増に対する受け持ちの件数とかいうお話かと思いますけれども、私どものほうでいろいろな就労支援の関係の非常勤職員の活用ですとか、そういった部分も含めまして対応していますので、また今回の定数増によりまして。","voiceIndex":84,"id":"exchange-031"},{"speaker":"阿久津委員","kind":"質問・要望","question":"今、適正な配置だとおっしゃっていましたけれども、要望があったからといって、そのまま受け入れるということはなかなか難しいとは思うんですけれども、この件に関しては、やはり受給日の様子とか拝見するに、よく目に見えるところでもあるものですから、どこの部署でも大変だと思いますけれども、これに関してはいろいろご配慮をまた来年度以降もしていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的にもう一回、２ページ、３ページのところの増減の中身をもうちょっと詳しくお伺いしたいのが、特に執行機関の変更というあたり、委託という言葉もちょっとあったんですけれども、特に旗の台文化センター、児童センター、図書館、ここのところをもうちょっと詳しく、特に学校の用務のところもどういう執行体制の変更があったか教えてください。","respondent":"堀越人事課長","answer":"基準に対して、保護世帯数の基準等がめやすという形でございまして、所管との確認の中ではいろいろな非常勤職員の活用、そういった観点につきまして、私どもとしては適切な対応をされていると、所管とも共通の認識を持っているところです。","voiceIndex":87,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"生活福祉課のところは、話し合いで１名と。要求が何名出ていたのかとお伺いしたので、ちょっとその辺と、非常勤職員の活用などで適切にされているということですけれども、１人の担当の方の受け持ち人数が現在何人なのか、わかったら教えてください。平成２４年からですね。じゃあ、何館、全てのところで委託が入っているのか、ちょっとそこを確認させていただきたい。児童センターは、今、２５館ありますね。","respondent":"堀越人事課長","answer":"それから学校用務ですが、すみません、改めてご説明します。大間窪小学校と、それから杜松小学校の統合によりまして、その分で用務を１名減いたしたのがまず一つです。","voiceIndex":89,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それ以外もいるのかどうか。これは当たり前だと思うんですけれども、守られていると思うんですけれども、この部分がかなりいるということですか。私はちょっと時間があったら、それぞれどのくらいで、だから定数外がいるんだなと納得をしたいと思っているんですが、ちょっとこの付則のところ定数外の中身、人数説明のところをもうちょっと詳しく教えていただきたいと思います。","respondent":"堀越人事課長","answer":"今回、この付則の７０名といいますのは、それとはまた別の形でございまして、最近の待機児の対策によりまして保育士の採用数も増やしておりますので、そういった部分において、定数として本体として持つよりも、柔軟に対応させていただいて。","voiceIndex":91,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"今、最後のところがいまひとつちょっと飲み込めないんですけれども、第２条の第２項と第３項にかかわる定数外の人は何人いらっしゃるのか、ちょっとそこをお伺いしたいのと、付則は違うと、特に保育園のところを強調していらっしゃいましたけれども、保育園のところで定数外の人員が平成２５年度何人になるのか。財調人員というのが、今、明らかになっているのかどうか、そこの点も教えてください。","respondent":"堀越人事課長","answer":"付則という形であらわしますが、保育士も正規の職員として配置させていただいているです。今年度につきましては、今、約５０名ほどの採用を予定しています。","voiceIndex":93,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと定数外と付則の関係がいま一つ理解できないんですが、第２項と第３項を合わせると、この定数外とすることのできるこの第２項と第３項の合計が何人かというのをちょっとお伺いしたいのと、それとこの付則の７０名とは別個であるという考え方でいいんですか。","respondent":"堀越人事課長","answer":"今、お話をさせていただいた付則の部分ですけれども、派遣ですとか、それから休職ですとか育児休業の場合には、要は組織が事業執行のために実際の人員として活用できない、ちょっと言い方があれですけれども、その人員に対して定数外というのがまず一つ。","voiceIndex":95,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"反対です。意見をちょっと述べさせていただきたいと思います。人員増の部分は仕事が増えたり新しく拡大をされている部分なので、当然の増と考えていますが、一方減のところは、今、お伺いしたところでは委託とか、非正規雇用に置きかえられている部分がほとんどであるといった意味では、今、働く人の賃金の賃上げが求められているのに、不安定雇用、反対に賃金が下がっていってしまう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-038"}]},{"id":"topic-04","title":"の第１２号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"の第１２号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"１点だけ、１ページ目の現行の部分で、ここで７００円と３００円という枠があって、ご説明だと非常に似ているような部分もあるとなっているようですが、これは下の部分の３００円のみを廃止されるということで、この下段の部分だけの対象の方というのはいるんですか。そこだけ確認させてください。","respondent":"堀越人事課長","answer":"清掃事務所の技能系の職員がごみの処理を直接、それから密接に関連する業務に従事しておりますので、技能系の職員の中でこの３００円だけを現在支給を受けているという職員はおりません。","voiceIndex":109,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この清掃業務手当ができた経過というか、古いと思うんですが、わかる範囲で経過を教えていただきたいのと、この加算分３００円がついた理由、これがなくなる理由、両方ちょっとよくわからないので、そこを教えていただきたい。そこをお伺いします。","respondent":"堀越人事課長","answer":"３００円の部分ですけれども、これは要するに東京都で清掃事業をやっていた時代から３００円の部分がございました。","voiceIndex":111,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"加算は東京都の段階から７００円も３００円もついていたと。私は反対に交通事情なども含めると、以前よりもより危険度が増しているのではないかという捉え方もしているんですけれども、その辺の状況に変化があるのかどうか、それをお伺いします。","respondent":"堀越人事課長","answer":"加算することの合理性という部分に鑑みますと、この理由が２つ同じような理由ということですので、そういった意味から廃止をするというものです。","voiceIndex":115,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"加算の合理性ということで、今、土木・技能系の方が移ってきてこの３００円がついたという受けとめ方をしたんですけれども、それがなくなっていくと、その辺の部分の方が減ってしまうということになるのかどうかと、あと、当事者間の労使の合意のところがちょっとどうなっているか、改めてお伺いをいたしたいと思います。","respondent":"堀越人事課長","answer":"労使交渉の部分につきましては、清掃労組につきましては１月１７日、区職労につきましても２月１１日に妥結をしているというものです。","voiceIndex":117,"id":"exchange-042"},{"speaker":"阿久津委員","kind":"確認","question":"２点だけ確認させてください。","respondent":"堀越人事課長","answer":"何人かというところで、今現在３００円加算されている支給につきましては、約１８０名ですので、この人数について支給がなくなるという形になります。それから、実際に業務についたとき、従事したときとなっていますので、従事した実績がなければ支給されないです。","voiceIndex":119,"id":"exchange-043"},{"speaker":"阿久津委員","kind":"質問","question":"わかりました。技能系の方で、先ほど例として述べられたような者以外の勤務というか、いわゆる事務作業的な者にはつかないということでよろしいんでしょうか。","respondent":"堀越人事課長","answer":"技能系の職員につきましては、ごみの収集運搬ですとか排出指導ですとか、そういった直接運搬以外の清掃に密接に関連した業務についておりますので、事務にはついておりません。もちろん清掃事務所の事務系の職員には、この清掃業務手当は支給していないという形になります。","voiceIndex":121,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"賛成しますが、一言だけいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-045"}]},{"id":"topic-05","title":"の第１３号議案、職員の旅費に関する条例の一部を改正する条例","agenda":"の第１３号議案、職員の旅費に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"１点だけ確認なんですが、一つが市町村合併によって、平成２３年の１０月ですよね。それで、平成２４年の１０月になって、今度は白岡市に市制が施行されます。これはほかの町とかも書いてあるんですが、これというのは合併箇所を毎回修正していくんですか。合併のところを毎回やっているのもどうなのかなと思うので、ちょっとその点、お知らせください。","respondent":"堀越人事課長","answer":"今、委員がご指摘のように、今回こういう形で一定まとめての改正ということでご提案をさせていただいているということです。過去も、平成１８年の市町村合併がございまして、そのときも一つめどがついた時点でまとめて改正をさせていただいた経緯があります。","voiceIndex":135,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"この質問を１つだけ。この除かれた船員法というのは、これはいつできた法律か、ちょっと見てこなかったんですが、なぜここに入っていたのかというあたりをもう一度、そういう事例が必要だったんだと思うんですが、その辺のことを１点だけお伺いします。","respondent":"堀越人事課長","answer":"実際に東京都ですといろいろな海洋技術の職員だとか、その他船員がおりますので、そういった経緯があったということです。改めて今回規定の部分につきまして見直しをして、整理という形で今回ご提案させていただいたという部分です。","voiceIndex":137,"id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1938#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":38434,"voices":150}},{"id":"h25-20130226-6","meetingId":"h25-cm02","date":"2013年2月26日","dateIso":"2013-02-26","committee":"区民委員会","time":"午前１０時００分～午後０時０１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"のスクエア荏原の開設","agenda":"のスクエア荏原の開設","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それだけでもいいから欲しいとか、あと、黄色にして欲しいとか、弱視の方なんかはあるんですけれども、こういったところはこれからということにはならないんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"そうしますと、東京都のマニュアルがあります。それに基づいて点字ブロックだとか、そういうものを敷きつめてあると。ですから、入ってから受付までを導線としては必ず必要ですよと。そこから後は受付の係員とか、そういう者がご案内するというような話でございました。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今でもずっと、きゅりあんなんかでも、館内の点字ブロックだったりが、もうちょっと充実してほしいということも要望されていますので、新しくできた、本当に広々として、日当たりもよくてというところなので、思ったんですけれども、やはり障害を持たれた方も少しでも使いやすくできたらなと思うので、受付の対応だけではなくて、ちょっとそういったことも考慮していただけたらなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"井上副委員長","kind":"質問","question":"駐輪場のところで、今日、視察でいただいた資料のところで、駐車場から入ったところの駐輪場の説明はいただいたんですが、１階平面図、よくわからないんですけれども、１枚目の駐輪場のところというのは、施設の中にあるということなんですか。ちょっと説明をお願いいたします。","respondent":"安藤文化スポーツ振興課長","answer":"駐輪場ですが、お手元のほうのＡ４の資料にあります、今日、バスが入ったところの脇については、利用者の方々の駐輪場、駐車場、またバイクをとめるところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"井上副委員長","kind":"質問","question":"とても立派な施設だなと思いましたけれども、視察のときにもちょっとお話があったように、全面ガラス張りで、最初はすごく見栄えもよくきれいなのかなと思うけれども、あれを維持していくときに、メンテナンスというものも相当、別の意味でこれから維持していかなきゃいけないということで、運営費のようなものはどのぐらいの、利用者数に換算してどのくらいとか、割合、どのぐらいかけようと思っているのか。","respondent":"安藤文化スポーツ振興課長","answer":"維持管理についても、今、できる前に、これから新しい年度に入って利用されていくわけですけれども、利用の数等を含めて、そういうものを考えながら１年間、見ていきながら、また精査はしていきたいと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"井上副委員長","kind":"質問","question":"大体のところで、運営費に総額かかる部分の維持管理費というのは、こういう建物で行政としては何割ぐらい、何％ぐらいを維持管理費として見積もっていくという考え方があるのか、その考え方を教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"この建物について何％とか、そういう部分については考えてございませんで、ファシリティーの業者に、この建物全体を維持していく上でどのようなコストが出るかというものもはじき出していただきながら、平成２５年度予算につきましては計上させていただいたところです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"井上副委員長","kind":"提案","question":"部長にお伺いしたいんですけれども、計画段階から区も入ってやっている中で、設計について、ガラス張り、ああいうものを提案されたときに、そういう先の維持管理コストというものは行政として精査していかなきゃいけないと思うんですけれども、その辺で何か、最初とちょっと違うとか、その辺は、これは十分に維持管理経費として品川区が見積もっていたところでできるものなのか、その辺の、今日。","respondent":"中川原地域振興事業部長","answer":"ただし、ガラスの部分につきましては私のほうで聞いたところ、ああいった狭い敷地なので広く見せる、広場を持った建物というのがありませんので、広場との一体感を持って、中から子供たちは今日、遊んでいる姿も見えながら、ああいう中でお客様に喜んでもらう趣向として。","voiceIndex":16,"id":"exchange-006"},{"speaker":"武内委員","kind":"質問・要望","question":"何点かあるんですけれども、料金表のところで、平日の場合と、全部はちょっと、時間の関係もありますので、先ほど、ひらつかホールとイベントホールと、それから、４番の会議室とかどれでもいいんですけれども、参考に午前、午後、夜間と分かれていますでしょうか、そのあたりどのくらいになるかというのを教えていただきたいのが一つと、あと。","respondent":"安藤文化スポーツ振興課長","answer":"ここは、午前が７００円、午後が１,０００円、夜間が１,４００円。会議室は若干の違いはありますがそんなところです。それから、２点目の幼保との一体の話ですが、中は完全に壁で仕切られています。ですから、中に入っては行き来は絶対できないという形になっております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"武内委員","kind":"確認","question":"わかりました。それから、駐車場のところは、そうすると基本はもちろん常駐という形ではないんだけれども、そうすると、催し物によって、基本は主催者側に交通整理というか、車でいっぱい来るようなことが考えられるんですが、そういう依頼を主催者側にするんですか。いわゆる文化振興事業団が指定管理なので、その中から対応するというよりは、主催者側に委ねちゃうということなんですか。それが確認です。","respondent":"安藤文化スポーツ振興課長","answer":"話し合いによって柔軟な対応をしていきたいと考えています。","voiceIndex":20,"id":"exchange-008"},{"speaker":"武内委員","kind":"質問・要望","question":"それはまた、検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"山内委員","kind":"質問","question":"１点だけ。昨日、きゅりあんの条例が一部改正されて、その一つに延長の話がありましたけれども、こちらでは今どういう考えなんですかね。","respondent":"安藤文化スポーツ振興課長","answer":"昨日のきゅりあんの条例の３０分の延長の問題ですけれども、ここも全く一緒の考え方で進めていきたいと思っています。","voiceIndex":23,"id":"exchange-010"},{"speaker":"井上副委員長","kind":"質問","question":"この施設の喫煙環境というのは、どういうふうにセッティッグされているんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"まだ、これからの、ＪＴと詰めている段階ですけれども、ちょっとした工事を行いまして、そこを喫煙所に指定する予定です。","voiceIndex":28,"id":"exchange-011"}]},{"id":"topic-02","title":"の活動拠点室（こみゅにてぃぷらざ八潮）の使用団体募集","agenda":"の活動拠点室（こみゅにてぃぷらざ八潮）の使用団体募集","exchanges":[{"speaker":"井上副委員長","kind":"意見","question":"当初の倍率、人気度というか、その辺がどうなのかということと、退室を申し出された団体については、ほかのところで独立をするとかいうことなのか、使い勝手がというような問題なのか、そこら辺、わかる範囲で結構です、どういう状況なのかということをお願いします。","respondent":"今井協働・国際担当課長","answer":"２点目の活動拠点室の返還の届出をされた団体の理由ですが、その団体は事務所を八潮を含めて２カ所持っていたと聞いてあります。その２カ所の事務所を統合して、新たに大きめの事務所に移転させるということで伺っております。","voiceIndex":35,"id":"exchange-012"},{"speaker":"井上副委員長","kind":"質問","question":"先ほど、選定基準をお話しいただいたんですが、前回のときに６団体で６室というようなところで、適さないと判断をされたのはどういうことか。今回も１カ所の選定があるわけですが、そういったところを、前回の例で結構です、ちょっと違うなと判断された項目というのはどんなことだったんでしょうか。","respondent":"今井協働・国際担当課長","answer":"これまでの審査におきましては、最初のときだったんですけれども、例えば旬とは言わないんですけれども、公益活動ですので、不特定多数の方にやっている団体ではなくて、どちらかというと自分の会員向けだけのサービスをやっているような団体が申し込まれた事例ですとか、また。","voiceIndex":37,"id":"exchange-013"},{"speaker":"井上副委員長","kind":"質問","question":"関連して施設のことなんですけれども、保育室、当初、使われる団体にしか開放されていなかったところを少し、大変いいスペースがあったので、そこをぜひ公開してほしいということで、中で運用されていたように思うんですけれども、せっかくある施設、八潮はお子さん、高齢化率が高いといっても、近くにもお子さんがいたりして、募れば利用したい人たちもたくさんいたんじゃないかと思うんですが。","respondent":"今井協働・国際担当課長","answer":"そういった中で、ただ単に、協働推進室で一つのイベントをやるときにも、保育が必要なときにはそういう団体に呼びかけて保育をやってもらうなどの活動が広がっておりますので、利用していく中でさらに皆さんの利用が広がるんじゃないかと考えています。","voiceIndex":39,"id":"exchange-014"},{"speaker":"井上副委員長","kind":"質問","question":"そうすると、イベントのときにそこを使うということなんだけれども、使っていないときに地域に開放するとか、そういう形で活用、そこからこみゅにてぃぷらざというところの利用率が上がるという相乗効果もあると思うんですが、今は一般開放はしていないというふうに思うんですが、そこはどうなんですか、されているんでしょうか。情報不足ですみません。","respondent":"今井協働・国際担当課長","answer":"あそこの施設は、隣に交流ラウンジというのもございまして、たしか、保育室の前に、使えますのでご利用のときはお声かけくださいみたいな形で、自由に使えるようになっていたというふうに考えてあります。","voiceIndex":41,"id":"exchange-015"},{"speaker":"武内委員","kind":"質問","question":"それで、一般の賃貸契約だと、よく契約書に何カ月前までに言ってくださいみたいな、そういう決まりみたいなのはあるのかどうかということと、それから、使用期間は３年以内で、更新による最長５年となっていますけれども、その３年の、早いところで平成２６年２月に、来年の２月に更新になるのかなと思うんですけれども、そのときにはどういう基準で更新する、しないとか、そういう判断基準があるのか。","respondent":"今井協働・国際担当課長","answer":"そのときの選定基準は、やはり３年間入居されたときに、最初に入ったときの基準の中で、協働推進室と一緒に活動が広まったかですとか、そういうところが同じような基準で更新の処理をしていくというふうに考えております。","voiceIndex":43,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2660#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":11601,"voices":55}},{"id":"h25-20130226-7","meetingId":"h25-cm02","date":"2013年2月26日","dateIso":"2013-02-26","committee":"厚生委員会","time":"午前１０時００分～午後２時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平塚橋会館跡特養ホーム等複合施設整備計画（案）に対するパブリックコメントの結果","agenda":"平塚橋会館跡特養ホーム等複合施設整備計画（案）に対するパブリックコメントの結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"お聞きしたいんですけれども、これは応募人数が７人で応募件数が１９件と書いてあるのは、７人の方が１９件のご意見を提出されたということなのでしょうか。","respondent":"原高齢者福祉課長","answer":"お一人の方で項目に基いて三、四件意見をいただいた方もいらっしゃれば、１人で１件の方もいらっしゃる。それをトータルしますと１９件です。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これを今見ると、近隣住民への説明会が少ないといういつものパターンのご意見があるみたいなんですけれども、例えば対象の近隣住民に全部、簡単な計画を郵送するとか、こういうことですとかいって資料を送れば、事前説明会が少ないとかいう意見はかなり抑えられるような気もするんですけれども、そういう検討というのはいかがでしょうか。","respondent":"原高齢者福祉課長","answer":"今後につきましても、計画ができ上がった段階で法に基づいた説明会、それから工事に入る前の工事説明会等々を繰り返して実施していきたいと考えているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その位置づけと、位置づけた理由といいますか、それと当日、そこで挙がったご意見でどういったものがあったのか、ご紹介いただきたいと思います。それだけこういう福祉施設は今後も長い間、地域の方々の協力も得ながら進めていく視点も大事なだけに、地域や地元住民への説明は丁寧であってしかるべきなのかなと思いますけれども、その点についてどのようにお考えなのか伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"２月１８日の意見ですけれども、この説明会は、計画の案ができましたので、とりわけ近隣地域の方には今まで５階のものが９階建てということもございまして、その施設の近隣の方にご案内をさせていただいたです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"パブコメについてですけれども、こういうデッサンまで寄せてくれて、すごく熱心なご意見はうれしいなと思うんですが、やはりそうは言っても７名ということですから、多くの方が意見を言いやすい、また、そういう工夫は必要なのかなと思うんですけれども、７名だというところをどんなふうに評価されていらっしゃるのか。","respondent":"原高齢者福祉課長","answer":"今回のこういったご意見は、パブコメの段階だけでのご意見ではなく、例えばシルバーセンター平塚橋会館の利用者については個別に説明会も実施してきてあります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ教えてください。１番から２番、４番と建築基準法に基づきと区の考え方が書いてあるんだけれども、１つ考え方を教えていただきたいのですが、こういう法令に基づくのはもちろんなんだけれども、建設可能な限り、要は容積率、建ぺい率、すべてを使える、使った建物を建てるというのは、すべてのものにおいて大前提と考えられているのかなという再確認をしたい。","respondent":"原高齢者福祉課長","answer":"今回は複合施設ということになりますと、一定容積率等々を最大限使うというのは、ここの場所に限ってはそういう考え方で進めさせていただきたいです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"それが非常に微妙なんだよな。要は、これは１００戸入ったと。４８戸ももともと守れた。シルバーセンターも入れ込んだ。それはそれでいいんだけれども、こういうふうに建て替えるといったときに、マックス使うとなると、じゃあ、複合施設化でこういうのも入れていこう、１００のものを１２０にするのか、５０を１００にするのかとか、そういう使い方があるではないですか。その基本はどこにあるの。","respondent":"原高齢者福祉課長","answer":"説明の仕方が不十分だっただろうと思いますけれども、１つだけの要素でなかなか建て替えるわけにはいかないので、政策的な位置づけと、それからそこの土地の容積率の中でどのくらい建つか、そういったもののバランスを考える中でどこまで。","voiceIndex":18,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは政策判断しましたとなると、その２０についてはなぜとなってしまうわけなので、そこら辺のところが、もし全体の判断の中で、今のお話の中でやっていくのであれば、やっぱりそういうときは早目に議会にもしっかり報告していただかないと、必ずその部分は私はもめる部分の１つになるのではないかなと思うので、そこら辺は今いろいろな要素を見るって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"若林委員","kind":"提案","question":"１点だけ。１６番がどういう意味合いなのか、ご意見・ご提案を大分要約した表現だと思うのですが、従事者増加に伴う治安対策で、区の考え方が、町内会等と協力し、地域の治安維持に努めます、これはどういう意味に捉えればいいでしょうか。","respondent":"原高齢者福祉課長","answer":"こういったところがご意見です。ここは、例えば特養が夜間も当然２４時間の施設になりますから、こういったご意見も説明会の中でいただきました。夜中に自転車のスタッフが来て、あるいは終わった人が帰るときに、夜何時ぐらいまでそういったスタッフの出入りがあるんですかと。","voiceIndex":22,"id":"exchange-008"},{"speaker":"若林委員","kind":"提案","question":"この３つをしっかり手だてしていくということの確認をします。最後に、ご意見・ご提案、区の考え方、この文字、文章そのものが載りますか。オープンになるんですか。具体的に言ったほうがいいですか。例えば１番のご意見・ご提案で４行、「区営住宅が４８戸しかなく、特定の方だけで、より多くの方が享受」、日本語としてこれはどこかでちゃんと句点をつけないと、どこで切ったらいいのという文章になる。","respondent":"原高齢者福祉課長","answer":"町会等という「等」ですけれども、１つは町会という組織がありますので、そこと連携するとともに、町会に入っていない方、あるいはここの施設は多くの方に利用していただきたいということも考えてありますので、さまざまな団体等が使うことも想定しておりますので、地域の中で。","voiceIndex":24,"id":"exchange-009"}]},{"id":"topic-02","title":"(2)品川区第二期国保基本健康診査等実施計画について","agenda":"(2)品川区第二期国保基本健康診査等実施計画について","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"実施計画を読ませていただきました。基本的な考え方を１点伺いたいんですけれども、要するに医療給付費の伸びと国民の負担の均衡を確保するという考え方なんだという説明ですが、私は権利としての社会保障、医療制度をつくることこそ必要だと思うのです。なので、この対比はどうも納得いかないんですけれども、改めて伺いたいと思います。やはり国保ですからサラリーマンということではないわけですよね。","respondent":"榎本高齢者医療担当課長","answer":"伸び率はいいけれども受診率が低いですねというお話でございました。こちらですけれども、先ほどはご説明しなかったんですけれども、今年度の新たな取り組みということで幾つかキャンペーンやプロジェクトなどを行いました。","voiceIndex":30,"id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"もちろん働き盛りで最も忙しいところだと言えばそうだと思いますけれども、国保ですから、いわゆるサラリーマンといいますか、自営の方々も業界健保といいますか、業界団体があったりだとか、やっぱりここの４０代、５０代の国保加入者がどういう職業だったり、生活状況であったり、特徴があるのか、そこはつかんでこそ、いろいろ啓発にもつながっていくのかなと思うんですけれども、その点については改めて。","respondent":"榎本高齢者医療担当課長","answer":"４０～５０代の方の職業の実態のことですが、国保では職業について特にこちらで把握している状況ではございませんので、未受診調査等を今まで行ってきておりますので、そういった調査をする段階、機会等が今後ございましたら。","voiceIndex":32,"id":"exchange-011"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"確かに区境に住んで、私は西大井ですからわかるんですけれども、隣の大田区の病院のほうが坂を登るよりも近かったり、そういう関係もあってそこを使っているわけですけれども、少ないからというのはちょっとひどいなと思って、やっぱり健康診断を受けやすい環境を整えていくという支援、視点が私は大事だと思いますので、改めて区境の方々の健康診断を受ける環境を整えていく。","respondent":"間部国保医療年金課長、榎本高齢者医療担当課長","answer":"この制度の趣旨としてはどういうことかというと、４０歳から７４歳の方、当然その上は７５歳以上になるわけですけれども、保険制度で見ると、要は国保、社保、協会健保等々に入っているわけですが。医師会のご協力のもと行っている事業でありますので、医師会の医療機関を中心として、今後も継続してまいりたいと考えています。","voiceIndex":34,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"２点、よくわからないというか、もうちょっと詳しい説明をいただきたいのですけれども、目的のところでＱＯＬの向上という言葉が、多分これはＱｕａｌｉｔｙ Ｏｆ Ｌｉｆｅというのでしょうか、キーワード的に使われているんですけれども、ちょっと抽象的というか、もう少しこのＱｕａｌｉｔｙ Ｏｆ Ｌｉｆｅの向上を理事者としてどう認識されているかという説明をしていただきたいのと、あと。","respondent":"榎本高齢者医療担当課長","answer":"区としてどのように認識しているのかという点ですが、今回の３つ目の柱であります重症化予防の点につきまして、実施計画の中でも説明している部分がありますが、透析の患者が増えているという部分で、透析になってしまいますと、かなりの時間が制約されて。","voiceIndex":38,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"特に糖尿病の減少というか、糖尿病患者を減らすんだというところで、それは特に高齢者にそのリスクが多い、実際に発症されている方も多いということで、やっぱり、計画策定における基本的考えのところでの個別性と継続性の重視が非常に大事かなと思うところがありまして、１つは私なんかもよく思うんですけれども、特定健診の結果が返ってきますと、ある数値と難しいアルファベットの並びがあって。","respondent":"榎本高齢者医療担当課長","answer":"医師会の先生方とも検討を進めておりまして、健診結果のときにお渡しするパンフレットがあるんですけれども、そちらをなるべく医師会の先生も使いやすくて、ご本人も何をすればいいかわかる形でのパンフレットを一緒に考えてつくっている段階です。","voiceIndex":40,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、第一期の実施計画の、例えば受診率の目標とか実施率の目標。今度、第二期もありますよね。これは、私の不勉強かもしれないんだけれども、国が決めた目標をそのまま書いていると理解していいんですか。","respondent":"榎本高齢者医療担当課長","answer":"国からも、健保によって目標値が違うんですけれども、市町村国保は何％という形で目標値が決まっておりまして、それを最終年度に当てるようにということで目標値の設定の仕方が示されておりますので、平成２９年度に６０％ということで。","voiceIndex":42,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"まさに今のところで、乖離し過ぎていて、例えばこういうのはひとり歩きするではないですか。もともとの目標が変ですからできませんでしたというのでは、あまりにひどいと思うんだけれども、そこら辺、もう１行つけるべきだと思うのですが、そこら辺の考え方を教えていただきたい。","respondent":"榎本高齢者医療担当課長","answer":"それから保健指導の実施率についてなんですが、２０％ということで来年度目標を挙げてありますが、今、ほかの区等で事業者によっては３０％近くの実施率を上げているところもありますので、やり方、工夫によってその点についてはある程度改善できる点があるとも考えておりまして。","voiceIndex":44,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"意見","question":"私が思っているのは、日本人は健診に対する考え方が非常に希薄というか、健診率も非常に低いとよく言われる民族というのかな、日本人はそういうところが多いとよく言われるんだけれども、これはあくまでも自己責任の問題もあるのですが、やっぱりこの部分をしっかりもっと上げていくという、これはお隣に先生がいらっしゃるからあれだけれども、アメリカなんかは８０％を超える、そのかわり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それとあともう１つは、喫煙のことが何も触れられていないんですけれども、生活習慣病は喫煙が非常に増幅因子になっているので、これは大切なことだからやっぱりこれに関しては何かの形で触れるとか、あるいはその項目も考えるとか、その辺のご検討はしたほうがいいのではないかなと思ったんですけれども、いかがでしょうか。","respondent":"榎本高齢者医療担当課長","answer":"今年度５月のときもご説明させていただきましたけれども、新しくロゴマークをつくりまして、そのマークでポスター、チラシも、医療機関だけでなく薬剤師会、それから歯科医院でも配っていただきましたし、柔道整復師、それから銭湯とか。","voiceIndex":47,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"端的に、区のキャンペーンのことでも区長から何かあったらしいですけれども、墨田区が４８％の健診率、２２ページだと杉並区も同率なんですが、何でこんなに高いんですか。","respondent":"榎本高齢者医療担当課長","answer":"２２ページの上のグラフにあります墨田区から何区かは、４５％以上ということで半分ぐらいの方が受けていらっしゃるというかなり高い理由なんですけれども、こちらの分析では、健診を受けるという意識の土壌の違いというか、１０年。","voiceIndex":50,"id":"exchange-019"},{"speaker":"若林委員","kind":"意見","question":"区民の意識の土壌が違うんですね。という区の１つの大きな分析があって、一方、例えば２８ページの図表３３のメタボのところでは、高い健診率の墨田区がいわゆる該当者予備軍でいうとトップ３に入っていますよね。一方、杉並区は下位２番目ですよね。これはどういうことなんでしょう。何でこんなになってしまう。","respondent":"榎本高齢者医療担当課長","answer":"特別区におきましては、確かに受診率とメタボの割合の関係がはっきりと健診の効果としてあらわれていないというのが現状だなとこちらも認識しております。","voiceIndex":52,"id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"全国平均のお話がありましたけれども、２３区でいうとこれだけ極端に。その見解を聞きます。これを１年でやるのではなくて、１年の中で定期的に随時やっていくことが本当のＰＤＣＡだと私は教わったんですけれども、その目標の立て方のＰｌａｎの問題と、年度途中でＣｈｅｃｋをどう改善してまた現場に戻していくという、そのサイクルの中心者というか、コントロールする人はどういう方なんですか。","respondent":"榎本高齢者医療担当課長","answer":"来年度の目標値につきましては、品川区といたしましては、実態のないというよりは限りなくその目標値に近づけていきたいという気持ちで立てているものでありますので、その後につきましては、先ほども申し上げましたが。","voiceIndex":54,"id":"exchange-021"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"最後に、住みなれた地域で安心して住み続けられるようにサービスを普及していきたいと。そこで伺いたいんですけれども、利用する方の自己負担は幾らになるのか。それともう１点、これからの方向性ですけれども、５保険者から１３保険者に広がったということですけれども、今後、どういう方向を持っているのか、そこの考え方も一緒に伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"それから今後の関係ですけれども、２３区でいきますと５保険者、それが昨年１２月末で１３保険者ということで、国の考え方としましたら、こういった地域包括ケアサービス、２４時間対応の定期巡回を普及させたいという考え方でおりまして、現在。","voiceIndex":61,"id":"exchange-022"},{"speaker":"中塚副委員長","kind":"質問","question":"国民年金の方が実際多いですから、先ほどですと要介護度３ですと２万円、要介護度５ですと３万円、訪問看護がつくとそれプラス月額３,０００円から４,０００円になると、単純に年金の半分が消えてしまうという事実上、この負担では必要であってもなかなか使えないという状況が生まれてしまうと思うんですが、そういう生活保護を受けていないけれども国民年金の方など。","respondent":"原高齢者福祉課長","answer":"これは定期巡回の対応サービスだけが特別に所得の低い方に対応しているというところではございませんで、介護保険全体の仕組みの中で１割の負担をいただくという形が基本となっています。そういう仕組みとなっていますので、ご理解をいただければと思っているところです。","voiceIndex":63,"id":"exchange-023"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"やはり誰もが住みなれた地域で暮らしていくには、どうしても年金など、また収入によってサービスを使いたいけれども使えない、必要だけれども利用できないという状況をしっかりと改善していって、どなたでも利用ができるような、ましてや介護保険でやっているわけですから、そういう仕組みをつくっていく必要が私はあると思うんですけれども、高いと使えない、これでよいのかと思うのですが、そこについて。","respondent":"原高齢者福祉課長","answer":"そういった意味で、このサービスだけが提供主体ということではございませんし、その方々の状況に合わせたプランに合わせ、相談をしながら対応していくというところかと理解しております。","voiceIndex":65,"id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"やっぱり、必要とする人に必要なサービスをしていただきたいと冒頭にご説明があったわけですけれども、この利用料金を理由にこれを使おうと思っても使えない、こうした方々に負担の軽減策をしっかりと設けるべきではないかと思いますので、ほかのサービスがあるからではなくて、これを使いたい人が使えない、ここをどうするのかと伺っているんです。この実態をどう考えるのか、最後に伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった場合には、先ほど来、お話ししていますように、その方が負担がどのくらいできるかというところと、ケアの中で困っているところを相談する中で、このサービスも含めほかのサービスと合わせながら。","voiceIndex":67,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問","question":"幾つか教えてください。どういう聞き方をしたらいいのかな。今、１３名になってきた。今後、どれぐらいまで増えていくと思っていらっしゃるのか。そういうものと、あと、事業者が採算ベースに乗るには何人というのも必ずこれはお持ちだと思うので、どれぐらい、何人の方を訪問すればどういう採算ベースにやっと乗るだろうという、そうすればお金が出ていく部分が減るわけですから、そこら辺のところの考え方。","respondent":"原高齢者福祉課長","answer":"ただ、このサービスはどういった方が使うのがご利用者にとってみてもいいかということをきちんと積み重ねていく、そのために、先ほど課題あるいは今まで我々がやってきた月に１回の検討会をもって、どんな方々がこのサービスを使ったらいいかというのを。","voiceIndex":70,"id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"私はこれは非常にいいサービスなんだけれども、大変なものに足を突っ込んでいる気がしてならなくて、そこら辺の兼ね合いを、だから行政側が、今、課長がしゃべったように非常に把握をされているのだけれども、じゃあ、今後ずっとその体制で行こうとされているとしたら、非常に不安を感じるんだけれども、そこら辺の感覚を教えてほしい。","respondent":"原高齢者福祉課長","answer":"ですから、最後の最後まで区がどんどんかかわっていくというよりは、仕組みづくりのところは丁寧に仕組みづくりをし、それから事業者に任せられるところはその上で任せていく、このような切り分けをしながら進めていきたいと考えているところです。","voiceIndex":72,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１点お伺いします。それはうまく乗れないと、要は行政側がずっとかかわることになってしまうから、そこが乗れてこないと、だからそういう視点で聞いているので、そういうのはどう捉えたらいいんですか。","respondent":"原高齢者福祉課長","answer":"そういった独立している事業者が品川方式というか、そういったところと上手に連携をしながら、施政方針でも載っていたように人口は減っても高齢者だけはまだまだ増えていくという事情がありますので、そういった意味では行政がやるべきところ、それから事業者がやるべきところ。","voiceIndex":74,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"区内のどこかに、もとの人と仲たがいして独立しているわけでなければ、その人に頼って、こういうことがあったらお願いしますよ、輪を広げてくださいなんていうことになるんだろうけれども、ここら辺の品川方式が、別に私はそれでいいと思っているのですけれども、だから行政があまり携わらないように、これから増えていくときに、どう仕組みをつくって減らしていくかという部分を考えているわけで。","respondent":"原高齢者福祉課長","answer":"そこにそのほかの事業者ということで、それぞれが独立しているわけではなくて連携をしていく、その中で件数が増えてきたときに、どのように役割を担いながら増えてくる高齢者の方々に必要なサービスを提供できる、そういった品川区の状況をつくり上げていくかという中で、今。","voiceIndex":76,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"じゃあ、国にそのお金を求めていくのかという部分、負担を多くしてくれと言っていくかといったら、保険でやっているわけだからなかなかそうも行かないということになってくるとなると、これはメニューが増えるのはいいんだけれども、お金がかかるのも増えるよということになってくるではないですか。介護保険の中ではというのも含めて、ぜひやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"定期巡回・随時対応型訪問介護看護サービスの背景と目的がさくっと載っていますが、ここにもう少し背景の、現状までのサービスの中での課題が全国的にあって、その課題に対応してこういうサービスが出てきたということですので、そこら辺のサービスを創設した背景をまずお聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"介護保険の考え方は、平成１２年に創設され、措置から契約にということで、社会全体で高齢者を支えていく仕組みづくりということで、４０歳以上の方から保険料を頂戴し、介護が必要になったときに、社会の支える仕組みの中で。","voiceIndex":80,"id":"exchange-031"},{"speaker":"若林委員","kind":"質問・要望","question":"同じく、訪問介護、連携している介護事業者の同じような数字、そこら辺が今、事業所従事者側と提供を受ける側でどうなっているかというのを現状で確認させていただきたいのと、そもそもなんですが、長くて言いづらいんだけれども、定期巡回事業所とサービス利用者が契約をする、本来その１カ所だけでサービスが完結するはずの設計だと思ったんですが、これは品川区だけなんでしょうか。","respondent":"原高齢者福祉課長","answer":"コールを３０回していただいた方については２３回の随時訪問ということで、これは今年１月の実績ですけれども、そういった対応をしています。ほかは１３回、１１回、９回、４回、５回という形でコール端末が押されているという状況です。","voiceIndex":82,"id":"exchange-032"},{"speaker":"若林委員","kind":"確認","question":"こういう中で、この定期巡回の中では、家族同居の方が３人いらっしゃって、生活援助も提供しているということになっているんですが、ここら辺の実態といいますか、ここには長期滞在型の生活援助を効率的、効果的という言い方に変換しているんですけれども、要するに利用する方が身体介護とともに自立した生活を営むための生活援助の考え方を、特に同居家族の方の例から考え方が何か変わったのかどうか、また。","respondent":"原高齢者福祉課長","answer":"そういう意味では、要介護度１だから使えないということではなく、その人の状況の中でこのサービスが合う方であれば、そういったことも含めて家族、ご本人と相談し、何が目的でこのサービスを目指していくのかというケアプラン作成の中で対応していくと捉えているところです。","voiceIndex":84,"id":"exchange-033"},{"speaker":"若林委員","kind":"質問・要望","question":"最後に、最初にあったように地域包括ケアシステムの中核、実質的には第１弾といいますか、すごく大きなインパクトを持っているんですが、来年度、また第六期に向けての計画も出されていますけれども、このサービスが今後どのように、今、１事業所という考え方で、複数の連携の各介護看護事業者の考え方の幅の広げ方と、もう１つ、やっぱり地域包括ケアなので、いわゆる福祉、あとは医療、ここら辺の連携。","respondent":"原高齢者福祉課長","answer":"福祉と医療の連携は、このサービスの中での連携の仕方と、もう１つは区全体の中で福祉と医療との連携という大きな二通りの考え方で区のほうは進めてあります。","voiceIndex":86,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3348#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":41308,"voices":92}},{"id":"h25-20130226-8","meetingId":"h25-cm02","date":"2013年2月26日","dateIso":"2013-02-26","committee":"建設委員会","time":"午前１０時００分～午後２時１６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を行います。 初めに、(1)平塚橋会館跡特養ホーム等複合施設整備計画（案）に対するパブリックコメントの結果","agenda":"を行います。 初めに、(1)平塚橋会館跡特養ホーム等複合施設整備計画（案）に対するパブリックコメントの結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、入居者の方の説明会が２月８日ですか、あったとお聞きしたんですけれども、今、区営住宅に入られている何人かの方から不安の声を伺っているんですが、引っ越し先が２月末までに決まるという説明を受けたんですけれども、まだ何もないけどどうなるんだろうかということが１点と、それから引っ越しにどれぐらいお金がかかるのかというのがすごく不安だというのが出たので。","respondent":"大串住宅担当課長","answer":"今のところ、秋に解体を予定しております。１０月から１１月ぐらいには解体を予定しておりますので、先ほどあった説明会については、その都度その都度で開催していきたいと考えております。具体的な日程については、また決まり次第お知らせをしていきたいと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もちろん、その部屋は自分の分譲のマンションではないわけですから、個人個人の意見を聞き入れて、その人にとって使い勝手のいい部屋にしてほしいというのは、居住者の方もそこまでを望んでいるわけではないと思うんですけれども、ただ、できる限り収納スペースをとっていただきたいとか、共通の要望で使い勝手がよくなるのではないかというところに対しては。","respondent":"大串住宅担当課長","answer":"そういったことを望まれない方もいらっしゃいます。実は１１月の面談、あるいはそれに先立って９月に自治会の方を対象とした説明会をやらせていただいたときに、あらあらのことはご説明させていただきました。その中でも、やはりいろいろな意見が出たのは事実です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"もちろんそういうことで、いろいろあると思うんですけれども、部屋を狭くして収納スペースを多くするとかということではなくて、工夫の中で、例えば収納スペースがより多くとれるんじゃないかとか、そういう提案もあるんじゃないかということもお聞きしていますので、そういうことも含めて、使い勝手のよい部屋にというところでは、できる限り、ぜひ工夫をしていただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"そういう方については、多分ご子息ですとかご親戚の方とかがこの居住者説明会に出られるような手を打たれたのか、また実際に出てこられた方がいるのかについて教えていただければと思います。","respondent":"大串住宅担当課長","answer":"今後、最大の焦点であります仮移転ということになりますけれども、この仮移転につきましても、ご本人がなかなかご対応できないということであれば、ご親族の方、ご家族の方にご相談させていただきながら、この計画は進めていきたいと考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"次に聞こうとしていたことまでご答弁いただいたので、こちらとしては安心して、区で手を貸していただける、また親族の方に任せられるという形で進められるということですので、私どもは丁寧に進めていただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"最近ではこのＰＭ２.５、中国のほうからの飛来ということで、誰もが関心をもっていて、健康被害が想定される中で、お隣の港区が特に都内３カ所で計測できるようなことをして、それをホームページで発表するというふうに出ていたんですけれども、すぐ隣ですので、その値を参考にするということもできるかと思いますが、品川区でこのＰＭ２.５、直接は関係なくなってしまいますけれども。","respondent":"野呂瀬環境課長","answer":"そのような対応をしています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"年度を合わせるということを言わせていただきましたけれども、今回は、第二次までは年度はいろいろな理由があるというのは私も知っていますので、仕方なく１年ずらした排出係数が前の年のということで、ずっと続けてこられたということで、それはそれでよろしいかなと理解はしているところですが、これが最終的には平成２４年度分までこの第二次の中に含まれるということですので。","respondent":"野呂瀬環境課長","answer":"それをこの第三次実行計画の中に盛り込むのは誤解を招くということで、それは委員ご指摘のとおりですので、一番下の段、平成１８年度の排出係数０.３６８に固定してとなっておりますけれども、注記として、実際の平成１８年度排出係数は０.３３９なんですけれども。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、このパブリックコメントの最後にも、その他のところに、パブリックコメントを募集される際にはまちづくりマスタープランで行われたような説明会をしていただくと、よりよい意見提出ができると思いますというご意見もあったんですけれども、この環境計画の中身を、２３、２４ページで環境学習の場の整備状況に対して、やはり満足をしていない、どちらともいえないというところがすごく多くて。","respondent":"野呂瀬環境課長","answer":"逆に言えば、その３名の方からしか来なかったけれども、実際には計画に沿って進めていって、これは２点目の質問につながるかもしれませんけれども、もっと環境学習についても力を入れて取り組んでいく。","voiceIndex":22,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つは、このパブリックコメントで、２枚目の第４章の基本目標の一番上のところで、施策の方向性、低炭素のまちをつくるということで、八潮地域での風力発電の検討をというご意見に対して、風力発電の推進も検討しましたがと書かれてありまして、区としてもこういう風力発電の検討もしているんだなと思ったんですけれども、それ以外の再生可能エネルギーのところで。","respondent":"野呂瀬環境課長","answer":"一概に区役所の中ですぐ採用と、それは別問題ですけれども、いろいろこれからの動向を見ながら検討していますので、今のところは太陽光発電の区民への普及というのがメーンなのかなと考えています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その太陽光に続けてなんですけれども、地球温暖化防止実行計画の第三次の中での資料編の９０ページに、品川区の施設で太陽光発電がどれだけついているかという一覧表があるんですが、この中で、随分差があるなと思ったんですけれども、例えば荏原第五中学校では２０kWがつくのに、小中一貫校で４kWしかつかないとか、あと、ついているものそのものも、もしかしたら一番初めは教育的というところで。","respondent":"野呂瀬環境課長","answer":"その施設整備の中で、設計の中でやっていただくということになっておりますので、いずれにしましても、区の考え方としては、区の施設に対しましても啓発という意味も含めまして、これまでどおり、これからも。","voiceIndex":26,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、これは質問なんですけれども、第三次実行計画の中の６ページで、一番下のグラフの内訳のところで、業務部門がかなり増えて、ほかのところは横ばいが多い中で、業務部門のところだけがすごく飛び抜けて増えているんですけれども、ここの理由を教えていただきたいのと、あとＣＯ２の排出量の状況というところで、京都議定書の基準年である１９９０年と比較すると。","respondent":"野呂瀬環境課長","answer":"ですから、当時は品川区は２５％を目標に、地域推進計画も推進してきましたけれども、方針がまだ固まっていない段階で、この第三次実行計画を区として計画するということで、それに対しましては先ほどご承知のとおり。","voiceIndex":28,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すいません、私がお聞きしたのは、５ページでは東京都は１９９０年の約１.５％減となっているのに比べて、６ページでは品川区は２５％増加しているというところになっているのが、なぜ品川区は東京都の平均と比べてこんなに増加しているかという、原因が何かあるのかなと思ったので、そこのところをお聞きしたのと、それから６ページの一番下で、業務部門というところが５２３から９２１に。","respondent":"野呂瀬環境課長","answer":"すいません、その理由については、確固たる理由は今この場ではちょっとあれですけれども、先ほど申し上げたとおり、業務部門とＣＯ２については多少の計算期間、計算期間というのは、ＣＯ２がどれぐらいというのは、はっきり言って２年ぐらい集計がかかりますので。","voiceIndex":30,"id":"exchange-012"},{"speaker":"原副委員長","kind":"質問・要望","question":"初めに、全体的なところでいくと、第二次品川区環境計画、仕事ですからあれなんですけれども、ただ、よくできているなと全体的には感じました。意外と東京都に頼っている。お聞きしたいのは、この策定懇談会のメンバーの流れ、全体で結構なんですけれども、どんな形であったのか。一、二点でも、何かその会の中でのものがあれば教えていただきたい。","respondent":"野呂瀬環境課長","answer":"環境コミュニケーションというのは、協働で地域同士が助け合ってやっていくということなんですけれども、それが一番基本になることかなということで、これからの取り組みとして、まだ温度差がいろいろあって、まだ認知度がとか。","voiceIndex":32,"id":"exchange-013"},{"speaker":"原副委員長","kind":"質問・要望","question":"そんな中で品川区、なぜこういう話をさせてもらうかというと、今これは第二次ですけれども、また第三次のときに、実際には今までは、環境は大事だよとわかるんですけれども、しっかり品川区の中のビジネスとして、要するに区、自治体の環境ビジネスという表現をしていいのかどうかわからないけれども、今度、予算特別委員会がありますけれども。","respondent":"野呂瀬環境課長","answer":"これからの方向性として、その視点というのは大事なことだと思いますので、すぐ一朝一夕にどうこうというのはなかなか難しいですけれども、いろいろな方面から情報等を仕入れながら、そういう形でいきたい。例えば屋根貸しだとか、ＢＥＭＳ、ＨＥＭＳ、いろいろ出ております。","voiceIndex":34,"id":"exchange-014"},{"speaker":"須藤委員","kind":"質問・要望","question":"この間、２月１６日に環境講演会があって、勉強させてもらって、そのときに環境大賞とか、みどりの賞とか、いろいろ顕彰されていたんだけれども、そういうものがこの中に、３３ページをずっと見て、全体から見ると、推進、推進とかと書いてあるけれども、顕彰ということは一言もそういう言葉がないので、何かああいう一生懸命やって、それなりに顕彰しているよということは、今の話があって。","respondent":"野呂瀬環境課長","answer":"ですから、今やっている個別の施策は当然これからも、今委員がおっしゃったとおり継続して、拡充して推進していくということで、今やっている方はそれぞれもっと取り組みを進めていくために、ああいう顕彰制度はこれからも必要だと思いますので、力を入れていくということで。","voiceIndex":36,"id":"exchange-015"}]},{"id":"topic-02","title":"品川区一般廃棄物処理基本計画（第３次）（案）","agenda":"品川区一般廃棄物処理基本計画（第３次）（案）","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"一般家庭のごみ有料化についてなんですけれども、パブリックコメントにも入っておりますが、今後の課題ということですけれども、ほかの自治体でやっていらっしゃるところはもう少し詳しいことを研究なさっていると思うので、お知らせいただきたいです。","respondent":"太田品川区清掃事務所長","answer":"東京都内については、区部については２３区の中では導入しているところはございません。東京都の市部においては、ちょっと資料が古いんですけれども、平成２３年の４月現在で、１９の市で導入されている状況になっているところです。","voiceIndex":42,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"今後どのような方向性をお考えなのかをお聞きしたいです。","respondent":"太田品川区清掃事務所長","answer":"そうしたことを含めまして、私どもとしては今後の検討課題のところにも記載しますけれども、ごみ減量施策の有効な一つであるということで十分認識していますので、今後検討していく必要があるのではないかと考えています。","voiceIndex":44,"id":"exchange-017"},{"speaker":"浅野委員","kind":"確認","question":"１０年間の計画で、５年後に見直すということで、小型家電リサイクルの点なんですけれども、確かにデータを確認したら、たしか今年の１０月ぐらいからを目標として進められるとは聞いて、たしか１６品目とかいう答弁があったと思うんですけれども、後半に２つか３つぐらい、名前だけはとったんですけれども、具体的にどうかというのは、この中にないんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"小型家電リサイクルについては平成２５年度の予算として、政策予算という形で計上させていただいています。審議がこれからということもありますので、ただ小型家電については議会の議決を得られた、見込みが立った時点で、この報告書の中に追加する予定で考えているところです。","voiceIndex":46,"id":"exchange-018"},{"speaker":"浅野委員","kind":"質問・要望","question":"３月に発行ということになっていますので。どういう形で進めるかということについては、どこで回収するのか、またどこで分別するのか、全部事業者にとか、そういうさまざまな方法があると思いますけれども、今ここでは多分答えられないと思いますので、予算の審議の中でもまたいろいろとお伺いするかもしれませんけれども、非常に重要な施策だと思いますので続けていただきたいと思いますが、ご決意のほどを。","respondent":"太田品川区清掃事務所長","answer":"ただ、いかんせん今の時点で、昨年の８月に法が公布されているんですけれども、施行がこの４月１日という形になってありますので、認定事業者がまだ４月１日以降ということもありますが、いずれにしても１０月から鋭意検討を重ねて実施していきたいと思っています。","voiceIndex":48,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところから、生ごみの量を減らすという取り組みができないものかなという思いがしているんですけれども、いかがでしょうか。","respondent":"太田品川区清掃事務所長","answer":"私どもも、今後１０年間の計画ですから、当然、ごみの有料化についても検討する必要があるということで、今後の検討課題に入れする。仮に有料化を実施したからといって、有料化だけで全て解決するかというと、そうではないんです。","voiceIndex":50,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それは、お金を取ればそれで解決するか、そういう意識が高まるかというと、そういうことではないと思いますので、やはり区民の意識啓発という形でのごみ減量をぜひやっていただきたいと思いますし、生ごみについては、都市部でやることが本当に大変なことなんだろうなという認識はしておりますけれども、都内でも２３区ではなかなか難しいと、やっているところはないのかなと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"須藤委員","kind":"質問","question":"今、まち場の人から言われているごみ屋敷という問題があって、それは出す人じゃなくて周りから、どうするんだという話をされてきて、我々もお話をするんだけれども、その家の人は、これはごみじゃないと言うんだけれども、地区によっては条例をつくってそれに対処するという、区部でもできてきているんだけれども、区民の皆さんからそういう声があったときに、条例をつくったりと対処をすることは。","respondent":"太田品川区清掃事務所長","answer":"この間、私どもでも、今後、ごみ屋敷と言われるものについては、基本的には庁内で関係する部署をもって対策会議をつくって対応していくということで考えてありますけれども、どういう解決方法が一番いいかということについては、ご指摘の条例化も含めて。","voiceIndex":53,"id":"exchange-022"},{"speaker":"須藤委員","kind":"質問・要望","question":"まだ出しているうちはいいと思うんだけれども、その中で懸念しているのは、老夫婦２人で１人亡くなると、その人の品物がいっぱいあるよとか。そのあたりは少し、どうしたらいいかということを考えておいてもらって、区民の啓発で分別して削減して、これだって一つの方法だけれども、片方でそういう社会がだんだん近づいてきているので、そのあたりも頭に入れておいていただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-023"}]},{"id":"topic-03","title":"通学路における緊急合同点検結果","agenda":"通学路における緊急合同点検結果","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"お伺いしたいんですけれども、これは夏休み中に、７月２４日から８月３１日は夏休み中ではないかなと思うんですが、教育委員会と土木管理課、道路課、各警察署ということで、学校で児童が自分たちで通学路に関して危険な箇所とか、市民科みたいな何か、そこはちょっとわからないんですけれども、勉強の中に、自分たちで危険な場所を見つけようみたいな授業がたしかあったと思うんですが。","respondent":"稲田道路課長","answer":"今回の点検の内容的なところなんですけれども、学校ではＰＴＡの方たちと話し合い、それからＰＴＡの方々が抽出してきた箇所、もちろんＰＴＡの方からすれば内容を見ると、子どもが道路脇から外れておもしろいほうに入っていっちゃうとか、そういう内容もありまして。","voiceIndex":60,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、大人の目線だけでなく、今のＰＴＡの方のお話もありましたけれども、お子さんのそういう授業で挙げてきたところとか、予測不能の動きを、動く児童の方も、お子さんもいらっしゃると思うんですよね。そういうところも加味していただいて、これから重視していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"この点はどう考えても朝の時間帯、午前８時前後１時間ぐらいを見るべきではなかったかなと思うんですけれども、まずこれを１点お伺いしたいのと、合同点検実施箇所数の１７２カ所はどうやって抽出されたのかなということについて、ちょっと教えてください。","respondent":"稲田道路課長","answer":"当初１９３カ所ほど挙げてきたんですけれども、民地の中の話であったり、防犯上の話であったり、そういう意見も入っていましたので、その辺を除いて１７２カ所を合同で点検していったという内容です。","voiceIndex":63,"id":"exchange-026"},{"speaker":"浅野委員","kind":"質問","question":"実際私も、子どもが通学する時間帯で七、八校、実は見ました。たまたま見ていたら、子どもたちがその道路を通って、右に曲がって門に向かうところなんですけれども、その道路が、車がやっと１台通れるところなんですね。この小山台小学校の件についてピックアップされていたかどうか、もし今の段階でわかるんであれば、無理ですかね、ちょっと教えていただければと思います。","respondent":"稲田道路課長","answer":"現段階で、小山台小学校の件については、ちょっとわからないんですけれども、これは学校とも話しまして現場を見まして、非常に狭い道路での通学路の設定というところがございましたら、加えるわけではないんですけれども。","voiceIndex":65,"id":"exchange-027"},{"speaker":"浅野委員","kind":"質問・要望","question":"本当に子どもの命は大切だということで、今回の点検を私どもぜひともやっていただくようにとお願いした手前、私どももしっかりと見ていきたいと思いますし、皆さんの目で、一人でも多くの方の目で見ていただいて、子どもの安全をこれからも守っていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私もこの１７２カ所というのが、ＰＴＡの方が抽出されたということなんですけれども、そういうふうにピンポイントでここというふうに、危ないだろうと思われる、ひやりとするような、はっとするようなところだけの点検ではなくて、子どもが通学するには多分、全て危険がつきまとうことになると思いますので、線で見るというか、子どもがこの道路を通って学校まで行くという線で見るという形での点検を。","respondent":"谷口交通安全担当課長、稲田道路課長","answer":"今、委員ご指摘の、車がスクールゾーンに入ってきてしまう、当然何カ所かあるとは思うんですけれども、平素から警察も指導取締りを実施しています。必ずしも点だけでやってきたというわけではございませんで、引き続き今後もそういう見方でやっていきたいと考えています。","voiceIndex":68,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"１７２カ所というと、１校当たり平均だと四、五カ所ということになるのかなと思うんですけれども、そういう点ではぜひ今後とも、危ないだろうと思われるところ以外にも気をつけなければならないところがあるんじゃないかなと思っていますので、そこのところをぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"このように４つの対策をやっていくんですけれども、要は道が広くても狭くても、結局はスピードを出すか出さないかということになると思うんですが、スピードを抑えるためには、何かほかに対策というのは、これ以外はないということですか。","respondent":"稲田道路課長","answer":"我々はそれにどう対応していくかというところで、標示、それから今回もやっていましたが、路面で注意喚起を図る。それから狭窄というんですけれども、視覚的にスピードが出せないような対策をとる。段差をつけるというのがあるんですね。","voiceIndex":72,"id":"exchange-031"},{"speaker":"木村委員","kind":"質問・要望","question":"だんだん狭くなっていくのは、最初はちょっとおっかなびっくりでしょうけれども、なれてくれば全然気にならないです。それは動物でも同じだと思いますが。強制的にそのような形で、特に子どもたちはそういう道路は危険なんだから、スピードを出さないためにそれをやっていくとか、ある程度強制的にやっていくことも大事だと思うので、警察と話をして、そういう処置をとっていただきたいなと思います。","respondent":"谷口交通安全担当課長","answer":"今の委員のご指摘は、段差舗装だとかいろいろあるんですけれども、警察サイドとしては、私も手段をいろいろ検討したことはあるんですが、それによって近隣住民から騒音の苦情になったりとか、あとオートバイの場合は気づかずに行って転倒する。","voiceIndex":74,"id":"exchange-032"}]},{"id":"topic-04","title":"勝島運河雨水貯留施設建設工事","agenda":"勝島運河雨水貯留施設建設工事","exchanges":[{"speaker":"浅野委員","kind":"確認","question":"工期の２つの部分があって、二次覆工ですか、こちらのほうは多分普通に行われている、樹脂を張りつけるというんでしょうか、そういうような工法だったかと思うんですけれども、今、下水道管なんかも積極的にこの工法でやられているのかなと思うので、かすかに記憶をしているんですけれども、通常行われている工法だと思いますけれども、ちょっと確認のためお願いします。","respondent":"武藤河川下水道課長","answer":"これは工程だとか、工事の関係上、別途施工する予定にしております。","voiceIndex":81,"id":"exchange-033"}]},{"id":"topic-05","title":"「水とみどりの基本計画・行動計画」に基づく水辺空間の利活用促進","agenda":"「水とみどりの基本計画・行動計画」に基づく水辺空間の利活用促進","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"五反田ふれあい水辺広場で、日本ケータリングカー協会が途中辞退ということで、どういった理由で途中辞退をされたんでしょうか。","respondent":"武藤河川下水道課長","answer":"応募がありました後、具体的に申請内容等のヒアリングをしていたんですが、相手方から一方的にメールが来まして、辞退しますと。その後、こちらからその内容等の問い合わせをして確認しているんですが、向こうから返事がないという状況なので、具体的に辞退した理由は不明です。","voiceIndex":87,"id":"exchange-034"},{"speaker":"沢田委員","kind":"質問","question":"天王洲内部護岸桟橋のことで、ここには以前、水辺広場のあたりに小さい桟橋があったかと思ったんですけれども、それとはまた別に、この離れたところに大きい桟橋をつくるということでよろしいでしょうか。","respondent":"武藤河川下水道課長","answer":"区として今回新たに地図で示した場所に、やや中規模の桟橋を整備する予定です。","voiceIndex":89,"id":"exchange-035"},{"speaker":"沢田委員","kind":"質問","question":"これからいろいろ船舶がそこに係留されるということですけれども、ここはふだん使える船舶というのは、どういった形でここを開放していく予定なのかということをお伺いしたい。","respondent":"武藤河川下水道課長","answer":"そのために、こういった桟橋を整備し、船を係留したものですが、今ご説明しましたように、具体的に平常時につきましても活用するということで、本桟橋を整備する区域は東京都の港湾局のほうになりますけれども、運河ルネッサンスという。","voiceIndex":91,"id":"exchange-036"},{"speaker":"浅野委員","kind":"質問","question":"基本的なところをお伺いしたいんですけれども、応募状況の中で２社あって、ビストロマルシェというグループなんですけれども、これは一体どういう会社なのか、グループなのか、ちょっと私は認識していないので教えていただければ。","respondent":"武藤河川下水道課長","answer":"応募がありましたビストロマルシェにつきましては、ほかの地区で実際にこういったケータリングカーの事業を行っている団体、こういったケータリングカーを行う事業者の集まりでございまして、例えば、東京国際フォーラム等で実際に具体的に実績があるということで。","voiceIndex":93,"id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"ネットで見ても出てこなかったのでお伺いしたんですけれども、そういう意味では日本ケータリングカー協会も同じような方たちの集まりだと認識していますので、実績もあるということで認められたというふうに認識をしております。これは３月末に寄附を受ける予定とあるんですけれども、これはどこから寄附を受けるかというのは具体的に書いていなかかったので、それを教えていただきたいなと思います。","respondent":"武藤河川下水道課長","answer":"具体的には特定非営利活動法人目黒川五反田協議会というところから寄附を受けて、区が所有する予定にしております。","voiceIndex":95,"id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"利用方法のお話がありましたけれども、やはり各種イベントなんかでにぎやかに、いろいろ考えて、これからも水辺の活用、運河ルネッサンスがあるかと思いますので、ぜひともにぎやかにやっていただきたいなと思う反面、水の事故には本当に十分に注意をしていただいて、決して事故が起こらないような、そのような対策もしっかりと進めていただきたいと思いますが、いかがでしょうか。","respondent":"武藤河川下水道課長","answer":"まさに委員ご指摘のとおり、こういった利用につきましては、事故といった面が我々も重要な課題だと認識しておりまして、この地域につきましては、既存のこういった船舶等を利用されている方々があります。","voiceIndex":97,"id":"exchange-039"}]},{"id":"topic-06","title":"治水対策関係事業の実施状況","agenda":"治水対策関係事業の実施状況","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"基本的なことで申しわけないんですけれども、雨水利用タンクとか防水板というのは、こういうものというイメージがあるんですが、雨水流出抑制施設はどういうものですか。","respondent":"武藤河川下水道課長","answer":"雨水流出抑制施設とは、簡単に言いますと、屋根等に降った雨が雨樋を伝わって、具体的には宅地内のますから地面の下を通って、公道の下水道管に流れますが、そのうち宅地内における雨水ますだとか管をいわゆる穴あきのものにしまして、周りを採石。","voiceIndex":103,"id":"exchange-040"},{"speaker":"沢田委員","kind":"質問","question":"先ほどアピールの効果があって２件ということでしたけれども、平成２０年以降の４年間というのはアピールというか、そういうのがあるということを周知はしていなかったのでなかったということですか。","respondent":"武藤河川下水道課長","answer":"１つはやはりＰＲを実施したこともありますが、もう一つは、昨年度の中盤に要綱を見直しまして、こういった施設を設置する場合の費用の割合をこれまで一定の割合だったんですけれども、基準はありますが。","voiceIndex":105,"id":"exchange-041"},{"speaker":"浅野委員","kind":"質問","question":"例えば雨水流出抑制推進事業にしても、やりたいけれども、浸透させるような場所がないとか考えられると思うんですね。この１から３について、それぞれ障害となるようなケースがあったかどうかということと、どのような障害があったのかというのを教えていただければと思います。","respondent":"武藤河川下水道課長","answer":"３番の雨水流出抑制推進事業につきましては、雨水浸透施設になりますけれども、これは先ほどの技術指針にもいろいろ示してあるんですけれども、例えば、一般の家屋の基礎の近く等に設置する場合は、やはりそういった基礎等を傷める可能性があったり、また。","voiceIndex":107,"id":"exchange-042"},{"speaker":"浅野委員","kind":"意見","question":"やはりなかなか条件が合わないと厳しいということだったと思うんですけれども、２番目の防水板の設置ですけれども、最近よくあるのは３階建てで玄関が下に下がっていてというところ、そこはよく私は土のうの準備をしておいて、何かあったときにはかさ上げしてくださいみたいな話はするんですけれども、ホームページを見て写真が出ていまして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-043"}]},{"id":"topic-07","title":"第２９回防災フェアの開催","agenda":"第２９回防災フェアの開催","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういう催しはすごく大事だと思うんですけれども、この間のあれで、初期消火の対策というのがすごく大事だということがみんなの認識になっていると思うんですけれども、そんな中で、こういうせっかくの場所で、例えば消火器の使い方とか、そういうほとんどの訓練の中ではやってはいるんですけれども、訓練に参加する方は大体わかっているとは思うんですけれども、こういう防災フェアとかというと。","respondent":"鈴木防災課長","answer":"参考までにスタンドパイプ自体は、今年度２月１日ですべてのミニ消火隊、ミニポンプ隊に配付しておりますので、そのスタンドパイプの取り扱いについての講習、訓練自体は、今、消防と調整しておりますので、今年度末には実施をする予定です。","voiceIndex":114,"id":"exchange-044"},{"speaker":"須藤委員","kind":"質問","question":"ここで保存会が纏をやってくれるんだけれども、共催とか、そういうところに入っていない、江戸消防記念会という名前で頑張ってやってくれているので、何か共催とか、そういうところには入れないんですか。","respondent":"鈴木防災課長","answer":"これは実は昔からの経緯で、ここでの木遣り等の披露ということで委託をしてまして、対価を払ってお願いするという形で、参加団体ということではなくて、区がお願いしてやる、区側の位置づけのイベントということでやらせていただいているので。","voiceIndex":116,"id":"exchange-045"}]},{"id":"topic-08","title":"品川区国民保護計画の一部修正","agenda":"品川区国民保護計画の一部修正","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"平成１９年に国民保護計画が策定されたということで、修正箇所の中で、Ｊ－ＡＬＥＲＴの検討を踏まえてということが二重線で消してありますけれども、Ｊ－ＡＬＥＲＴがちゃんと検討が終わって区に配備されたのはいつから。","respondent":"山口防災安全担当課長","answer":"配備、運用したのが平成２２年７月からになります。","voiceIndex":122,"id":"exchange-046"},{"speaker":"沢田委員","kind":"質問","question":"配備がされてからちょうど３年以上が経過しているということですけれども、その期間で、こういった武力攻撃事態等が起きた場合には、配備されていることをもとに運用されるということになっていたんでしょうか。今日修正になるまでの間について。","respondent":"山口防災安全担当課長","answer":"国民保護計画は計画ですので、やはりリアルタイムで常に修正というわけにもいかないと思います。ですので、もちろん記載は平成１９年のままでしたけれども、実際に導入した以降は、もしその直後に何かあれば、当然Ｊ－ＡＬＥＲＴを活用するということで準備をしておりました。","voiceIndex":124,"id":"exchange-047"},{"speaker":"沢田委員","kind":"質問","question":"先般の北朝鮮がミサイルを発射したときに、各地でＪ－ＡＬＥＲＴの不備とかがあったかと思うんですけれども、品川区の場合は、あのミサイル発射が起きる前にもいろいろと点検というか、それが起きた後の点検というのはどういうふうになっているんでしょうか。","respondent":"山口防災安全担当課長","answer":"実際、９月１５日だったと思いますけれども、これは全国的な訓練として、国のほうからＪ－ＡＬＥＲＴの試験をやるぞという訓練がございました。","voiceIndex":126,"id":"exchange-048"},{"speaker":"沢田委員","kind":"質問・要望","question":"今回の修正でそういった確認もできているということですけれども、これからも区民の命を守るのはやっぱり区の仕事でもあって、また国の仕事でもあると思うので、ぜひともこういったＪ－ＡＬＥＲＴ、計画ではありますけれども、しっかりとした計画を作成していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-049"},{"speaker":"浅野委員","kind":"質問・要望","question":"教えていただきたいんですけれども、修正手続きの中で、品川区国民保護協議会という名称があります。こちらの中にも、計画の中にも入っているんですけれども、毎年結成されるのか、それともずっと継続なのか、どのようなメンバーで構成されているのかちょっと教えてください。","respondent":"山口防災安全担当課長","answer":"それで、ちょっと言い方を変えますと、この国民保護協議会のメンバーは、地域防災計画だと防災会議というのがあります、その防災会議のメンバーと基本的に同一ということでご承知いただきたいと思います。協議会自体は常に常設ということになってあります。","voiceIndex":129,"id":"exchange-050"},{"speaker":"浅野委員","kind":"質問・要望","question":"常設ということで、いつ何が起きても集まっていただけるということだと思うんですけれども、先般、都の職員の方も次長クラスは定期的に変わったりとかあれがあるんですけれども、そのときには１回やめて、また新たに任命というんでしょうか、そういうような形を多分毎年のようにとるのかなと思うんですけれども、これは実際に行われていると思いますが、そこら辺の手続を教えていただきたい。","respondent":"山口防災安全担当課長","answer":"基本的に任命期間約２年ということになっておりますので、切れる前に委嘱の手続、更新の手続をとりますし、また、任期の途中でかわられましたら、新しい方に対して、また区長が委嘱をすると、そういう手続をとらしています。","voiceIndex":131,"id":"exchange-051"},{"speaker":"須藤委員","kind":"質問","question":"細かいことですみませんけれども、資料２の５ページと６ページに、品川総合区民会館が載っているんだけれども、スクエア荏原が、今度、平塚に４月１日にオープンするので、そこは載っていないんだけれども、私は荏原の人間としていつもそこを、いろいろなことが落っこちてきてしまうので言っているんだけれども、そこは載せる気はないのですか。","respondent":"山口防災安全担当課長","answer":"この計画自体も、もちろんそういう変更等が必要であれば、今後何回も細かく、何年に１回じゃなくてなるべく毎年見直していくようにしたいと思いますので、実態としてそういう、今回はもう決定してしまいましたのでこれでいきたいと思いますけれども、また。","voiceIndex":133,"id":"exchange-052"},{"speaker":"須藤委員","kind":"意見","question":"荏原のほうでああいう施設をつくれと何度も言って、やっとでき上がってきたので、これで品川地区と、１つのあれになってきたなと。今度、こういうところにやっぱり載る載らないという、別にあれじゃないけれども、やはりそういう評価をしてくれているよという文書でありたいなと思っていますので、ぜひお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-053"}]},{"id":"topic-09","title":"区内一斉防災訓練の実施結果","agenda":"区内一斉防災訓練の実施結果","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"私もこの訓練を見学させていただいたんですけれども、本当に区内一斉で初めてやられるということで、いろいろと大変なこともあったかと思うんですけれども、地区ごとに訓練の内容が大分違ったりしていまして、私が参加した大井第二地区とかは、消防団の方は来ていなかったんですけれども、人数も少なかったり、地区ごとにいろいろな訓練をされていますけれども、地区の訓練というのは。","respondent":"山口防災安全担当課長","answer":"プラスアルファでこういうことをやろう、ああいうことをやろうというのは、基本的には地区にお任せしまして地区の中の防災関係者のほうで、じゃ、我が地区はこれをやろうとか、そういうような形で進めていってもらったというのが実際の動きです。","voiceIndex":140,"id":"exchange-054"},{"speaker":"沢田委員","kind":"確認","question":"それとあと、この中で区の職員が、今回のこの訓練は統一、一斉にやるということで、区の職員にとってもこういった訓練というのは、特に全体を見ている区の職員が一斉にやることによって、初めて全体で震災が起きたときどうするかという対応が大切だということを確認されたかと思うんですけれども、区の職員の感想というか、意見というのもどこかに、ここには載っていないんですけれども。","respondent":"山口防災安全担当課長、松代防災まちづくり事業部長","answer":"それからまた、区の職員の反省を込めたものとしては、もうちょっとやはり事前説明をしてほしかったとか、目的をもうちょっとはっきり防災課のほうからしっかり教えてほしかったというような、そういう反省事項等もあった次第です。今現在、総合防災訓練は１３地区で地区防災協議会主催のもと実施されているんですが、そこの会長の方々に集まっていただいて、訓練内容、また今回の一斉訓練に当たって反省すること、いろいろとご意見を賜って。","voiceIndex":142,"id":"exchange-055"},{"speaker":"沢田委員","kind":"質問・要望","question":"今回いろいろ反省点とかがあったと思うんですけれども、今、防災まちづくり事業部長がおっしゃられたとおり、これからも毎年やっていかれるのか、毎年やっていく中では、やはり反省点を活かしてやっていっていただきたいのと、それからあと、やっぱり職員の方、今お話に出たことでもありましたけれども、職員の方のまた結果の報告というのもお伺いしたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-056"},{"speaker":"須藤委員","kind":"質問","question":"でも、だんだんここで１つ課題を見つけてきて、もう１年、２年やって、それから、今度は全町会が避難所にちゃんと避難できる、そういったことになれてくるようにしていってもらえればいいかなというふうに思っていますけれども、今後のやり方というのは、そういうものはどういうふうに考えていらっしゃるか、お聞かせ願いたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"そういった中で、反省点をきちっと踏まえた上で、３月に再度、地区防災協議会会長連絡会を開いて、今後の進め方をどうすればいいかということでお諮りをしたいなというふうに思って、今準備をしています。","voiceIndex":146,"id":"exchange-057"},{"speaker":"須藤委員","kind":"意見","question":"そうすると、いろいろなやり方ができるので、ただこれだけを見ているんじゃなくて、本当に震災になったときにどういうことなんだということをやると、学校関係者とたまたま土曜日で授業があるならこういう仕組みもできるんじゃないかとかというようなお話をして、本当に区民の皆さんが万が一のときに対応できる仕組みづくりをして、一遍にはできないんだけれども、もう一つ区民から言われたのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"とてもこういう訓練は大切だなと思うんですけれども、今後に向けてということでの要望なんですが、今回は避難所の開設ということで、実際に地震が起こったとき少し時間がたったところでの訓練ということなんですが、実際に地震が起こったとき、震度６強、震度７という地震が起こったとき、どうなるのかということの想定をしたところで、私はぜひ同時に、品川区の出火の想定は４０カ所となっていますけれども。","respondent":"山口防災安全担当課長","answer":"一斉訓練の内容というのは、いろいろ今後まだ検討していきます。種類も当然、１種類だけじゃなくて、幾つか必要になると思いますので、今、委員からご提案ありました事項も考慮させていただいて、可能な限りいい訓練になるように進めていきたいと考えています。","voiceIndex":149,"id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4066#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":63023,"voices":159}},{"id":"h25-20130226-9","meetingId":"h25-cm02","date":"2013年2月26日","dateIso":"2013-02-26","committee":"文教委員会","time":"午前１０時００分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の(1)平成２４年度品川区教育委員会事務事業の点検および評価報告書","agenda":"の(1)平成２４年度品川区教育委員会事務事業の点検および評価報告書","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"これだけの意見がついて、教育委員会としては、教育センター、今後どのようにここで指摘されている内容を実現していこうというお考え、今の段階であれば教えてください。","respondent":"太田指導課長","answer":"例えば、教育資料の展示、それから教育相談とか適応指導教室、そして研修等、そういったようなことを実施しているわけですけれども、今後よりさまざまな教育課題も考えたときに、相談機能をなるべく教育センターで充実。","voiceIndex":5,"id":"exchange-001"},{"speaker":"阿部委員","kind":"質問","question":"いろいろな教育委員会で、品川だけではなくて教育センターをどう拡充するかというのは、問題意識を持っているところは多いと思います。それからもう一つ、９９番の帰国児童・生徒等適応指導、これ、見直しというのは、念頭にあるのは縮小ということでしょうか。ほかの見直しというのにも共通すると思いますけれども、縮小を念頭に置いた見直しがＣであるのか、そうでないものもあるのかというようなこと。","respondent":"太田指導課長","answer":"内容的に、今非常に、例えば、一度帰宅してから外国語の適応指導教室に通うというような状況で、講師を用意しても直前の欠席というようなことで、学校と子どもと、その適応教室が連絡がとれないことで、非常にむだがあったりということが現実あるので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、項目ごとにいろいろな対応のされ方が違いますけれども、私たち委員会として求めるのは、こういう評価が出た後、どういうふうにそれを具体化していくかということについての確認をまずお願いします。","respondent":"齋藤庶務課長","answer":"教育委員会と区長部局という関係もございまして、この時点でどのようにこの評価が政策に反映されていくか、この時点でご説明するのはなかなか難しいところもありますけれども、予算で反映させるもの、箇所数を増やすもの、あるいはやり方の工夫をするもの。","voiceIndex":10,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、こういう平成２４年度の事務事業評価が出て、それに対してこういう流れをしました、結果こうなりましたというところまで議会に報告はいただけるのでしょうか。やはりそこまでしていかないと、この平成２４年度の事業の評価を最終的にこう変えましたというところまで報告したほうが私はフェアではないかと思いますが、いかがでしょうか。","respondent":"齋藤庶務課長","answer":"何かというと、去年は全教職員の方にメンタルヘルスの新しい仕組みを取り入れる、今年度はそれを定着させて、より充実させなさいということでのＢということですので、幾つかの根拠につきましては、今後。","voiceIndex":12,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただ、この報告までは求められていないのかもしれないけれども、議会としてはその評価がどうなったかということだって興味がありますから、それを少し工夫をしていただいて、これは後で答弁をお願いします。それからもう一つ、確認ですけれども、学校の持っている事務システム、これが品川区のシステムと別々だったというのも初めて知りましたけれども、それはそうしなければいけない理由があるのですか。","respondent":"和氣学務課長、田村教育次長","answer":"ただ一方で、校務システムとか、学校事務システムとか、給食の管理とか、就学援助だとか、あと、児童・生徒管理とか、これは別のシステムを持っておりますので、これはこれで教員、学校が独自で使うシステムになる。それで、伊藤委員のおっしゃっている予算とか決算の話は、区全体のものを、今日、総務委員会で報告している事務事業点検を予算編成時に予算特別委員会に合わせて提示していますので。","voiceIndex":14,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"意見","question":"ですけれども、それをなぜ別のシステムでやっているのかという疑問がずっとついて回る。品川区としては、基幹事務システムがあって、そこに区民である保護者の方々とか、そういうデータベースが当然あるわけであって、そことリンクしていけば、もしかしたらもっと安価に、もっとシステムの運用が効果的と思われますけれども、そういうことについの事務事業評価をしたことはありますか。","respondent":"和氣学務課長","answer":"成績処理とか、児童・生徒管理だとか、こういうものもやっていますので、セキュリティーをかなり厳しくしておかないと漏れてしまいますので、そこら辺はかなりクローズにして学校だけで使えるようにという形でつくっているものでございまして。","voiceIndex":17,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"それで、しかも経費がそれほどかからないような、そういう工夫をしていただいているところが大事なのではないかと思いますけれども、そういう視点でやってこられたというふうに理解してきたのですけれども、ここで２回あるところの１回を廃止してくるという、そこの評価、その評価の角度というのがちょっとよくこれだけだとわからないので、文化を本当に大事にして。","respondent":"中元品川図書館長","answer":"子ども読書活動推進計画をつくったときに、地域でもそういう子どもの読書推進ということで児童センターと連携して始めさせていただいた中で、やっている私たちといたしましても、この費用対効果やそれも含めて、また、実際これだけ人形劇をやって。","voiceIndex":19,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"訂正したいと思います。必ずしも品川区に育っている子どもたちが全てそういう児童センターが行っている事業にしても、こういうところにしても、全て遭遇して参加できているというふうにはなっていないわけですから、いろいろなところでいろいろな場面で提供していくという機会を多く持つというところは大事にしていただきたいと思います。そういうふうに思っておりますけれども、改めて何かご答弁があれば。","respondent":"中元品川図書館長","answer":"私どもとしても、こちらは教育委員のご判断ですので、そういうところを品川図書館側として、委員おっしゃるようなところを説明し切れなかったところでご配慮いただいたとご理解いただければと思います。","voiceIndex":21,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"だから、その辺について、精神的なストレスを抱えながら仕事をするということは、これは直接子どもたちに、かなりマイナスな影響が出てしまうということも大いにあり得ますので、そういうストレスを抱えながら仕事に当たるということは、できるだけ少なくしていただきたいというように思うので、このチェックそのものは、私は必要なことだろうとは思いますけれども、そのやり方とか。","respondent":"齋藤庶務課長","answer":"ほぼ１００％に近い数字で回収をいただいております。具体の質問項目についても、実際、岡山大学で開発された仕組みで、岡山県、石川県、幾つかの県の教育委員会で実施しております。区市町村レベルで実施しているのは、品川区と、あと幾つかあります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"そうすると、９９％の回収率は確かに高いと思います。みんな必要性が認識されているのだろうというふうに思いますけれども、未受診、回収した９９％の中で、どこかの医療機関でチェックをして、そして本人に返すわけですか。","respondent":"田村教育次長","answer":"ただし、ここのすごい難しいところは、ストレスは、ご存じのとおり、私たち、組織の中で仕事をしていますから、そうすると、組織の人間関係だとか、学校での業務の分担だとかが、本人が産業医にストレスの実は原因は人間関係だったりという話があれば。","voiceIndex":25,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"笹子トンネルを例に挙げてしまったら、全然レベルが違うので恐縮ですけれども、しかし、命と安全の問題ですから、そこは最優先にしていただきたいということを改めてお願いしておきたいというふうに思います。迅速な改善というのは、そのようなことも含めてというふうに思っておりますので、その辺、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"渡部副委員長","kind":"質問","question":"二つお伺いします。一つは、先ほど、伊藤委員のほうからありました話です。考え方です。要は、ヘルプデスクといいましょうか、問い合わせ先が二つあったのが一つになる、そのシステムが云々というよりも、パソコン等システム使用に関して問い合わせ先が一本化するよというような考え方でいいのでしょうか。","respondent":"和氣学務課長","answer":"特にコールセンターのほうの問い合わせを一本化できるだろうという、今、お話になっていまして、その後、こういう検討を、細かい部分等をするということです。","voiceIndex":28,"id":"exchange-012"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"それと、一つ、実は７ページのすまいるスクールのところですけれども、今回、教育委員会のほうの事務事業評価はこれで最後になってしまうのかという中で、この評価のところに書いてある３行というのが、ちょっと意味合いが、２行目から、「児童が安全で有意義に過ごせる場所を効果的・効率的に提供できるように検討する」というのは、今、学校の空き教室なり。","respondent":"齋藤庶務課長","answer":"ここの意味は、児童を学童に変えるということでは全くございません。学校で引き続きすまいるスクールを事業。ただ、区長部局に戻った以上、移った先でのメリットを生み出せるように要望してくださいと、こういうことです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"阿部委員","kind":"確認","question":"一応確認ですけれども、以前、インフルエンザが流行したときに、インフルエンザの子どもたちの数の情報が医師会のほうへの連絡が、保育園・幼稚園関係はいくけれども、学校は直ではこないというようなお話を以前聞いたことがあります。今は教育委員会関連でのインフルエンザ罹患数情報というのは、医師会のほうには行くようになっているのでしょうか。","respondent":"和氣学務課長","answer":"保健所を通じまして情報を全部提供していますので、そこをネットワークに医師会に通じるようになっております。","voiceIndex":39,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"これもちょっとうろ覚えなのですけれども、たしか今年度の頭、学校保健法の改正があって、感染症にかかるその後の出席停止日数の変更があったかと思いますけれども、そういうことはこの数として影響が出てくるものなのでしょうか。解釈でも構いません。","respondent":"和氣学務課長","answer":"５日間というのが、解熱の３日と２日という二つの新しい解釈ですが、特にそれで数が変わるということは考えてございません。","voiceIndex":41,"id":"exchange-015"},{"speaker":"阿部委員","kind":"確認","question":"確認ですけれども、学級閉鎖期間を見直すということも考えているのでしょうか。","respondent":"和氣学務課長","answer":"特には考えてございません。従来どおりの学級閉鎖の方法をとっておりまして、とにかく感染した人から隔離することが重要なので、何日間という休みの関係とか、授業の関係、そういうもので判断しております。","voiceIndex":43,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"だから、そういう点で、できるだけ感染させないような努力を園側でも当然とっているし、とらなければいけないとも思っておりますけれども、そのあたりの苦労というのか、すぐ親に連絡をして引き取りに来てもらうということも含めて、それから、感染をさせないための園側の措置というのですか、手洗い・うがいはもちろんですけれども、その辺はどういうふうにしているのですか。","respondent":"立川保育課長","answer":"ご案内のとおり、保育園は就労支援ということも一つの目的としておりますので、学級閉鎖はできず、登園の自粛をお願いするということになっております。","voiceIndex":45,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"全く個人の判断で、今は行かせないほうがうつらなくていいからと、健康でもうつらなくていいからということで休んでいるのか、そのあたりの違いというのはどういう感じですか。","respondent":"立川保育課長","answer":"これにつきましては、やはり保護者の方の判断ということで、いわゆる蔓延防止ということで登園自粛をお願いしておりますので、保護者それぞれの判断で自粛をしてもらう。いろいろ就労の状況等にもよると思います。","voiceIndex":47,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"大したことでないのかもしれないけれども、公式な資料ですから指摘だけしておきたいのは、２７番の鈴ヶ森小学校の学校名、正式な「ケ」は「ヶ」なのです。だから、同じように、２ページ目、１６番もそうですよね。話はそれだけですけれども。だから、こういう公的な資料について、しかも文教委員会に出す資料ですから、それはこれから気をつけていただければと思います。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-019"}]},{"id":"topic-02","title":"の(3)各校におけるいじめ防止への取組み","agenda":"の(3)各校におけるいじめ防止への取組み","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"確認したいのですが、２ページのところで、一番上の現段階で見られる成果で、「子どもたちの中で、いじめは悪いことという価値観がより強くなってきている」ということになっておりますけれども、この評価はだれがしたのですか。非常に子どもの心の中をここまで測定するというのは、非常に難しいと思いますけれども、それをあえて書かれているわけですから、どういうことなのか確認をまずお願いしたい。","respondent":"太田指導課長","answer":"各学校から報告いただいたということで、各学校の評価です。各学校では、例えばこういったものは児童会とか生徒会の活動の中で子どもたちから自主的にこういったような内容が出てきているというようなところも多分この評価につながっていると考えています。","voiceIndex":55,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"このことはもちろん正しいと思ってやってもらいたいけれども、だけれども、一番重要なところはここですよ。子どもの中にどういう意識を形成させて、行動なり、言葉を変えていくかというところまでやっていかないと、この目的は達成できないと私は思うのです。学校から挙がる評価だけではなくて、もっと別の形の評価方法とか、それから、考え方を私は開拓していくべきだと思いますが、いかがでしょうか。","respondent":"太田指導課長","answer":"そういったような評価ということにつながるとは思いますけれども、毎月生活アンケート等を各学校でも実施しており、その状況についても私どもも各学校の各学級ごとにつぶさにその各月の経緯も把握しております。","voiceIndex":57,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ましてやここに書かれていないわけですから。もちろん問題行動を起こす児童・生徒に対してはつぶさに把握されているかもしれないけれども、その前の段階でいじめの芽を摘むとか、こんなことをおっしゃっているわけだから、やはりそういう家庭環境については一定程度理解する、担任教師が直接行って、スキームをつくっていく必要があると思いますけれども、それだけでもいかがですか。","respondent":"太田指導課長","answer":"ということで、家庭訪問の実施ということについては、その方向性をしっかり捉えた上で、では、その実施について何が今課題なのかということも整理しながら、各学校にも働きかけていきたいというように思っております。","voiceIndex":59,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"ほかの具体な方法についての確認は時間がかかってしまいますので、一つだけ、地域健全育成運営協議会という表現がありますけれども、私も保護司として参加することがありますけれども、実態としては日中の例えば午後２時などの開会であるので、なかなかこちらが期待する方が集まらないような状況がありますので、だから、ここに書かれているように、期待できるとするならば。","respondent":"齋藤庶務課長","answer":"一部、延山小学校では、モデルとして実施されているところですが、学校によっては夜や夏休み前に開催するなど、さまざまな取組みがあります。","voiceIndex":61,"id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"この表の中では、いろいろな学校が取組みをされていて、いろいろと成果が出てきた、それはいいと思いますけれども、頑張っていれば、多分、課題、ここはこう頑張ってみたけれども、こういうところでうまくいかなかったからどうしたらいいだろうかとか、今やっていること、この目的を達成するためにもっといい方法はないだろうかと普通は思うものではないかと思うのですけれども、そういうものは。","respondent":"太田指導課長","answer":"先ほど申し上げましたように、今回の事案が発生してから４カ月半程度たった段階で、その間に各学校がいろいろ検討して取組みを始めています。ですので、今の段階で各学校からお聞きした項目を取組みと成果というような形で私どもお聞きしました。","voiceIndex":63,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"私はどちらかというと、一つ大きな、いじめ防止というのはすごく難しい取組みですから、成果が出てくる前に、まずはいろいろな悩みのほうが先に出てくるのかと思ったのですけれども、今回は聞いていらっしゃらないということなので、実際に共有して、課題が出てくるのは全然悪いことであるとは思いません。","respondent":"太田指導課長","answer":"今回の事案を受けまして、各学校の管理職には、調査対策報告書を自分のこととして捉えるようにということで、最低３回は全部読み直しをして、自分の学校ではどの対策が必要かというようなこともしっかり議論するようにというようなことで指導しております。","voiceIndex":65,"id":"exchange-025"},{"speaker":"阿部委員","kind":"意見","question":"抽象的な議論になってしまうのであまり突っ込みませんけれども、例えば、１枚目の「小・中学校が互いの授業や生活の様子を見合うことは習慣化」、そんなに簡単なことではないですね。この件は、次長、一言。","respondent":"田村教育次長","answer":"１１月、１２月、１月、３.５カ月なので、当然これをスタートするときには学校も課題を抱えているわけですから、それをまた別の機会に学校と教育委員会が十分共通する課題、あるいは学校で抱えている単独の課題、それは教育委員会と学校が相談して、浮き彫りにして。","voiceIndex":67,"id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"この辺を突っ込むと、私はここに成果と出てくるより前に、手法としてのやってみたけれどもうまくいかないというほうが先に出てくるのかと思っています。教育センターは、本来、学校運営に関わるさまざまな支援を行うという役割もあるはずで、機能していないというふうに言われていたのですけれども、ここで学校からも教育センターにというお声はなかったのですか。","respondent":"太田指導課長","answer":"当然、そういったような相談、もちろん個人情報は配慮した上でそういった情報の共有をして対応していくということですので、ここにはちょっと書かれていませんけれども、学校の意識としては、当然そこの連携というのはベースとしてあるというふうに捉えております。","voiceIndex":69,"id":"exchange-027"},{"speaker":"阿部委員","kind":"質問・要望","question":"いじめに関して大人がすべきことはたくさんあると思います。どうしても今の段階では児童・生徒への指導という形になってしまって、読む限りではどちらかというと一方通行のものになってしまっているように見えますけれども、それが双方向になり、むしろ子どもたちからの発信になるところまで、ぜひそこは教育委員会として向上していっていただきたいと思います。再度お考えをいただきたい。","respondent":"太田指導課長","answer":"子どもの中でそういったようなことを広げていくのは、本当に委員おっしゃるとおりですので、児童・生徒会活動を、役員だけではなくて全児童・生徒に広げていくというようなことも含めまして、こちらから学校のほうに指導いたしますし。","voiceIndex":71,"id":"exchange-028"},{"speaker":"鶴委員","kind":"質問","question":"その辺の状況の変化はいろいろとタイミングはあるとは思いますが、その辺でもし状況の変化が、増加傾向だとか、減少傾向だとか、横ばいであるとか、概略でいいのですけれども、その辺をわかれば教えてください。","respondent":"太田指導課長","answer":"いじめに関しては、各月、こちらも調査を行っておりまして、その件数とかということももちろん把握はしておりますけれども、今回のことを考えたときに、件数よりも、その一つ一つの内容であるとか、その状況にやはり着目しなければいけないということで。","voiceIndex":73,"id":"exchange-029"},{"speaker":"鶴委員","kind":"質問・要望","question":"二つ目が、前回ですか、委員会のときに、指導課長に私がお尋ねした件で、もしわかれば、課長の中で意義づけがあれば教えてくださいという質問をもう一回するのですけれども、この２ページ目の右上の「児童・生徒自身がいじめ根絶を発信すること」とある、まさにキャンペーンの運動もそうですけれども、いじめの根はなんですかと、私、質問させていただいたと思いますが、これはそれから数日たっているので。","respondent":"太田指導課長","answer":"いわゆる芽というのは本当にこれが芽だというものはもちろんないですけれども、子どもたちの日常の中にある、そういったものが差別意識であるとか、あとは、ちょっとした言葉の行き違いであるとか。","voiceIndex":75,"id":"exchange-030"},{"speaker":"鶴委員","kind":"提案","question":"ある一定の教師という、いわゆる師という立場としては教えるということがあると思うのですけれども、その中で児童も生徒も年代の差、世代の差こそあれ、同じ人間なんだという視点に一度立ち返る、そういう場が教育の現場にもあっていいのではないかというところで、そういういわゆる友達先生とか、そういうことではなくて、そういった垣根を取っ払った教師と児童・生徒との車座になるような、座談のような。","respondent":"太田指導課長","answer":"そうしたときに先ほどもおっしゃったように、友達先生みたいにならないということはもちろん大切なことですけれども、そういったこともしっかり、特に若手教員を指導しながら、そういったことの大切さということも指導していきたい、研修等を含めて指導していきたいと思います。","voiceIndex":77,"id":"exchange-031"},{"speaker":"鶴委員","kind":"提案","question":"この課題については、私自身も経験者というところで、かなり時間をかけて質疑していますけれども、やはり痛いほど、どういうふうに改善してほしいかという、現場の先生、また、それを管理監督する教育委員会の皆さんも大変だということも認識しながら、その現場監督、自分自身が、当時、また今現在。","respondent":"齋藤庶務課長","answer":"だから、電話番号は３回線しかありません。一斉にふさがってしまう場合、今、デジタル化しながら、少しでもつながる時間が多くなるようにということではいろいろ取り組んでおりますけれども、３回線しかないということが根本にあります。","voiceIndex":79,"id":"exchange-032"},{"speaker":"鶴委員","kind":"質問・要望","question":"わかりました。それからあともう一つは、地域というところにもつながってくるというか、関係機関という形になるのですかね、スクールカウンセラー等、増配されると思いますけれども、その辺も今、現状の体制と、それから新しい年度で協力、評価していくよという、その辺はどういうふうに評価されるか、具体的な部分、学校に何人とかありますよね、今、週に何回、その辺がどう変わるのか教えてください。","respondent":"太田指導課長","answer":"そのほかに、まだちょっと予算の関係で案の段階ですけれども、こちらのほうにもいじめ問題等対策チームにも３名のスクールカウンセラーを専属で採用する予定ですので、そちらの活用も含めてスクールカウンセラーの体制は強化できるのかと思っています。","voiceIndex":81,"id":"exchange-033"},{"speaker":"鶴委員","kind":"確認","question":"だから、そういう人数とか規模で人の配置の数とかがある程度決まっているのか、その辺のところを確認させてください。","respondent":"太田指導課長","answer":"ただ、人数が少ないからといって、２名配置できるところを１名にするということではなくて、プラスアルファとして、その課題によって配置しているということです。学校と相談してそういった形で配置しているという状況がありますので、そういったことには対応しているです。","voiceIndex":83,"id":"exchange-034"},{"speaker":"鶴委員","kind":"質問・要望","question":"わかりました。いずれにしても適正な配置というのですか、間違いなく児童・生徒がいつでも相談したりとか、また、先生もそうでしょうけれども、そういったときに対応できる、そういう強力な体制をつくってもらいたいという意味で、ちょっと確認をするのでお願いします。今後も心のアンテナを本当に高くしていただいて、しっかりと取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"ここに２枚の表に出ている言葉のところがちょっとわからないところもあったので、それも含めて質問したいと思います。１枚目に出ている実態把握のところの「生活ノート（日記）」と書いてありますけれども、これは児童・生徒一人一人と先生とのやりとりという、グループだとか、クラスだとかという、そういうあれではないということで理解していいのでしょうかというのが一つ。","respondent":"太田指導課長","answer":"小中一貫の日につきましては、これはいじめ根絶のために年３回ぐらい小中一貫の日というものを設定して、例えば小学校教員が中学校の授業参観をしたり、情報交換をしたり、そしてあとは、昨年も言いましたけれども、いじめ防止研修、そういったものとか、あと。","voiceIndex":89,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"言葉の理解はわかりました。これから予算との関係で、取り上げていけるかどうかも含めてこれからというふうに理解していいのでしょうか。それでなければ安心して入学させることができない、通学させられないですからね。だから、そういう基本的な考え方について、基本に沿った形で、全学校でそれは改めて徹底させるということが必要だと思うので、そういうことで聞いたつもりですけれども。","respondent":"太田指導課長","answer":"学校で子どもの命を第一に考えてそれに配慮するというのは、もちろん当然のことだと思っています。","voiceIndex":91,"id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"それと、いじめられていることについて問う場面がありましたよね。そういうことを研修として全ての教員がしっかり押さえなければいけないというふうに思うので、それで私、ここの部分は非常に大事だと思うし、この研修を受けるためには、その辺の問題意識がなかなか見えないところなので、区教委の認識を伺いたいと思ったのですけれども。その辺の認識をちょっと聞きたいと思って質問しているのですけれども。","respondent":"太田指導課長","answer":"その声かけも含めて、例えば教員研修のところでは、今回、いじめ防止に関する研修を全校で行っている中で、いじめの事例、いじめにつながる可能性のある事例を報告し合って、具体的な事例をもとに先生たちでその対応の仕方であるとか。","voiceIndex":93,"id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"もう絶対に繰り返さないという、その立場で強調して申し上げたいと思いますので、そこはぜひ酌んでいただきたいと思います。その辺についてはどういう、進捗状況と、その見解について伺いたいと思います。","respondent":"太田指導課長、田村教育次長","answer":"それに向けて準備もしております。ただ、構成メンバーは専門家のチームですので、だれでもいいというわけではないので、その人選についてもしっかり慎重にそういったことを勘案して進めていきたい、そういうように思っています。ですから、本来業務を動かしつつなので、今も今日報告の中の月１回のアンケートも含めて、もう対応していますので、それに加えて、例えばソーシャルワーカーだとか、学経だとか、あと警察ＯＢとか、弁護士とか。","voiceIndex":95,"id":"exchange-039"},{"speaker":"南委員","kind":"意見","question":"そういうことで準備を進めていただいているということがわかりましたので、ちょっと安心もするところですけれども、それより何よりいじめを起こさないということが大前提ですので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-040"},{"speaker":"大西委員","kind":"質問","question":"あそこで、もしお答えされると大変長いお話になってしまうので、あのときには強くお願いするという形で終えましたけれども、ぜひその部分を、あれだけの、先ほどおっしゃったような３回読むというようなやり方というのは、昨日いみじくもＮＨＫの教育テレビで「テストの花道」というのですか、ああいうのでやっていましたけれども、自分ができたところを次で見たときに。","respondent":"太田指導課長","answer":"委員がおっしゃることは本当にごもっともだと考えていますし、先ほども申し上げたように、家庭訪問の実施の方向でこちらとしてもいろいろ課題等も整理しながら進めていきたいというふうに、前回の答弁より少し前向きなつもりでお答えしたつもりですけれども。","voiceIndex":99,"id":"exchange-041"},{"speaker":"大西委員","kind":"意見","question":"私としては、大変望外の答弁をいただいたと思っています。その中でスクールカウンセラーが個人面談の時間を持ちながら、少し様子のほうを専門的に探っていくというような形につないでいただければ、これはいじめがあったときにどういう対処療法をするかというよりも、ぜひ根本的に発生させないということで、今の答弁は大変うれしく思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-042"},{"speaker":"高橋委員","kind":"質問","question":"幾つかお尋ねしたいのですが、一つは、今回もこのような形で報告というのでしょうか、お話をしていただいたのですが、今後、いじめ防止等に関して、これはおそらく平成２５年度の協議会や対策審議の報告と絡んでくるかちょっとわかりませんけれども、このような報告というか、現状こうですとかというのを、今後どのような形で発信というか、まとめて発表をされていくのでしょうか。それが一つ。","respondent":"田村教育次長、太田指導課長","answer":"議会の報告ですが、今回、武内議員の質問に答弁したように、全会派で区議会で決議いただいてということを重く受けとめていますので、今具体的に、まだこれから来年度のスタートになって、今日の参考にも載せてありますけれども、例えば。特に今出ましたいわゆる裏サイト、我々で言いますと学校非公式サイト等の監視については、先だっても本会議でご答弁申し上げたように。","voiceIndex":102,"id":"exchange-043"},{"speaker":"高橋委員","kind":"意見","question":"最後のスクールカウンセラーの方々のいろいろな専門的な立場の視点というのも大事ですが、逆にそれがあるがゆえに、現場の先生との認識のずれといいますか、指導のずれというのが出てくることが多々現場ではあると思いますけれども、そういう、もちろん専門的な視点と、あと、先生方の教員としての専門的な視点、そこのずれというか、両方のいいところを活かしていけばいいと思うのですけれども。","respondent":"太田指導課長","answer":"ですから、それを学校の組織の中で、副校長とか、校長が、そういった情報をもとにしっかり調整をして、何が正しいのかということの方針を出すということは、すごく有益なことだと考えております。","voiceIndex":105,"id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何点か確認をさせてください。平成２５年度の予算でこういうさまざまな事業が継続して具体化していくのでしょうか。そうでしょうけれども、その確認がなかったのでご答弁をいただきたいのが一点と、それから、校内体制の見直し、それから教職員への対策、児童・生徒への指導、保護者・地域・関係機関との連携とありますけれども、これもＰＤＣＡはするおつもりはあるでしょうか。","respondent":"太田指導課長","answer":"平成２５年度予算については、あくまでもこれはまだ案ですけれども、例の調査対策委員会の報告書にもこのような内容を示されているところがありますので、しっかりそれを受けとめて、これらの事業、もし予算が通れば、積極的にこれらの事業を進めて。","voiceIndex":107,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"質問・要望","question":"できればこれも例えば半年もしくは３カ月ぐらいの中で、できれば第三者、客観的に見られる立場の人が全ての仕組みを評価して、ここはこうしたらいいということについてのより高い精度で事業を見直していく必要があると思いますけれども、現時点では口頭でも結構ですから、こんなことを考えているということがあれば教えていただきたいのが１点と、それから、先ほど少し話があったように。","respondent":"太田指導課長","answer":"今、委員がおっしゃった内容については、例えば来年度でありますと、いじめ根絶協議会というものを実施する中で、こういったことについても評価も含めて議題にしていきたいと。","voiceIndex":109,"id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問・要望","question":"２点ほど。今日の冒頭、品川区教育委員会事務事業の点検および評価報告書をいただきましたけれども、あえてこの中に来年度以降、これを入れてみてはいかがでしょうか。そういうふうにして具体的にいじめ対策をさまざまな観点から構築していくべきだと思うのですが、いかがでしょうか。","respondent":"齋藤庶務課長、太田指導課長","answer":"１点目の事務事業評価の対象にですが、予算の科目の事務事業ごとに対象事業を決めますので、当然入ってくるものと考えております。今おっしゃった内容の２番目ですけれども、例えば警察の情報、それから地域の情報、そういったものをやはり身近に集められるのは、この資料の２枚目、保護者・地域・関係機関との連携の中の理解啓発の中の地域との連携で。","voiceIndex":111,"id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問","question":"今、確かにそのとおりです。要は、目的一つですから、その目的を達成するためにさまざまな施策をつくるのはいいけれども、現状の仕組みに合っていないものはやはり変えていく必要があると思うので、これはもう一言答弁をお願いします。","respondent":"田村教育次長","answer":"そうしたら、何人かの町会長から、地域健全育成運営協議会では中学校区のこういう課題を議論をする場が大事だと、自分の考え方がというふうに実際に意見をもらっていますので、ぜひその辺を参考にして、せっかくいい組織体があるので、それを活性化して。","voiceIndex":114,"id":"exchange-048"},{"speaker":"阿部委員","kind":"質問","question":"先ほど、区教委の監視事業というお話がありました。私、これについて、詳しくは知らないですけれども、これ、区立学校だけではなくて、小・中学校も含めて監視事業をしているということでしょうか。その結果というのは、どのような場面でフィードバックして対策に役立てているのか。","respondent":"太田指導課長","answer":"それを区教委のほうで、今後、学校の対応が必要な場合には学校にももちろん情報提供して指導をしていただくというような形で活用しています。","voiceIndex":116,"id":"exchange-049"},{"speaker":"阿部委員","kind":"質問・要望","question":"例えば、Ａ小学校ならＡ小学校、中学校でこういうサイトが立っていて、こういう書き込みがあってということは、かなり具体的に情報提供されて、具体的に対応が可能ということですか。親御さんの間では、例えばあそこのお子さんが、家に帰ったら実は自傷行為を毎日しているみたいなことも、学校の先生は全然知らなかったたりとか、そういったことはわりとあるようです。何かお考えがあれば。","respondent":"太田指導課長","answer":"教育委員会としても、なるべくいろいろな相談の窓口を提示することで、学校もそれを利用しながら保護者に働きかけるということもできると思いますので、そういったことも含めて取り組んでいきたいと思います。","voiceIndex":118,"id":"exchange-050"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"ある程度、保護者に、これが小学校へ上がったから、中学校へ上がったからではなくて、やはり幼稚園、保育園のときから、この際、品川区というのは、このいじめの問題に対して、今、全力で力を注いで取り組む、解決しなければならない問題ということで、できれば子ども未来事業部と連携をとって、一つ言えば、保育園の保護者会、幼稚園の保護者会でも、例えば上にいってこういう問題にならないように。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、私どもも小学校、中学校での取組みの中で、教育委員会と連携して、何かできることがあれば、有効なものが私どもとしてもとり得るものがあれば、連携を密にして取り組んでいきたいというふうな考えは持ってあります。","voiceIndex":120,"id":"exchange-051"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"ぜひいろいろな課と連携をして、このいじめという問題に対して真剣に取り組んでいるという姿勢を示していただきたい。ある意味、年齢の近い生の手本が近所にいるのですね。ぜひ連携を深めていただきたい。いじめはだめなのだという方向になっているときに、実はその一番肝心な青少年育成団体というものに対して、教育委員会でアプローチは何かされていましたでしょうか。","respondent":"太田指導課長","answer":"特に現在の段階ではしておりません。","voiceIndex":122,"id":"exchange-052"},{"speaker":"渡部副委員長","kind":"意見","question":"本当に子どもたち、例えば放課後でも、土曜日、日曜日でも、さまざまな活動を助けていただいている、これも運営しているのは地域の方々です。一言言わせていただきました。よろしくお願いします。","respondent":"太田指導課長","answer":"委員おっしゃるとおりですので、今後、前向きに検討してまいりたいと考えています。","voiceIndex":124,"id":"exchange-053"},{"speaker":"南委員","kind":"質問","question":"ここには、いじめる側といじめられる側のそれぞれのところについても触れられておりますけれども、さっきも言ったのですけれども、大津のものを読んでいると、ターゲットになった子どものしゃべり方が、非常にイライライライラしてしまって、それでかかわって「殴れ、殴れ」と言ったり、そういうことでいじめてというふうな状況ですけれども、品川の場合もＡ君に対して一定のそういう気になるところがあって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"ですから聞いているわけです。品川の今回の問題、その他の学校の問題というところで大きなテーマになるから取り上げているので、ぜひ誤解しないでいただきたいと思っていますので、ぜひその辺についての考え方、子どもへのアプローチ、こういう議論をさせるときの先生の思惑というのを、目的というのをきちんとそこにも置くべきではないかと考えていますけれども、いかがでしょうか。","respondent":"田村教育次長","answer":"ですから、それも全部、今、南委員のおっしゃった内容も含めて、固定化はしていないですけれども、このいじめの取組みだとか何かには当然加害者になる場合、あるいは被害者になる場合、あるいは傍観者になる場合も当然想定して、研修だとかをやっている。","voiceIndex":130,"id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、それら時間を置かずにきちんと対策をとるということを示していただきたいというふうに思っています。なぜ傍観者でいてしまったのか、あるいは、なぜ加害となってやってしまったのか、そういうところはしっかり解明しなければ、手立てなんて打てないではないですか。そこはきちんと日を置かずにやっていただきたいというふうに思いますけれども、そのあたりについての考え方はいかがでしょうか。","respondent":"田村教育次長","answer":"調査対策、これも議会で毎回答弁しているので、調査対策報告は、昨年の１１月５日で報告を終わって質疑も終わっています。","voiceIndex":132,"id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"今、先ほどちょっと質問をさせていただいたのは、対策委員会で去年１１月５日に報告を受けたあの報告書の中身の解明されていない部分については、日を置かずに解明するべきだと私は思っているので、その点について、そうではないと新たな対策、今いる子どもたちの状況に適切な教訓を活かした指導になっていかないというふうに思いますので、そこについて聞いているのです。","respondent":"田村教育次長","answer":"ご遺族が被害届を警察に出されたということなので、それを区のほうでも受けとめていますので、協力できる範囲で警察の調査にはご協力する、そういう考えです。","voiceIndex":134,"id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"被害届を出されて、一方の側の当事者というか、そういう現場になったのが品川の学校ですから当然だと思いますけれども、できるだけ警察のところに委ねて、そういうところにこの問題が移ってしまったということについては、私個人としては非常に残念だという気持ちはあるのですけれども、もっと学校の中でこういう作業を通してきちんと体制をとっていただきたかったというふうに思っているのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-058"}]},{"id":"topic-03","title":"の品川区立図書館の利用登録および更新手続き等の変更","agenda":"の品川区立図書館の利用登録および更新手続き等の変更","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"幾つか教えてください。返却が滞る場合がありますよね。その際に、更新などの際に何かペナルティーはあるのでしょうか。","respondent":"中元品川図書館長","answer":"今、未返却９０日で貸出停止となっております。一応、３カ月お待ちしております。その間はペナルティーなしです。","voiceIndex":143,"id":"exchange-059"},{"speaker":"阿部委員","kind":"意見","question":"いや、これを整えられるのだったら、返却されないでずっと持っていらっしゃる方は、ちょっと更新を待ってもらうというようなこともあわせてあってもいいのかと思ったのです。それはまたご検討いただけば。それとも親の身分証明書で子どものものもつくれたかと、どちらでしたか。","respondent":"中元品川図書館長","answer":"現在も健康保険証等で確認をさせていただいてあります。と申しますのは、ご兄弟とかで同性同士ですと、ちょっとそこが混乱することがありますので、きちんとお一人ずつの住所・氏名・生年月日の確認を今後はする。今も住所・氏名の確認はしています。","voiceIndex":147,"id":"exchange-060"},{"speaker":"南委員","kind":"確認","question":"変更の理由が連絡先不明の利用者が増加していることでという、これを防ぐためにこういうふうに変更したという説明だと思うのですけれども、そこに生年月日の確認というふうになって、有効期間もそれぞれ変更はしておりますけれども、その生年月日の確認ということで、連絡先不明の利用者が増加している歯どめになるのかと、ちょっと説明を聞いていて思ったのですけれども。","respondent":"中元品川図書館長","answer":"お友達同士でカードが混ざってしまっていたりとかで、お子様だとたまにそういうことがありますので、きちんとご本人というところを節目節目で確認をさせていただきたいです。","voiceIndex":149,"id":"exchange-061"},{"speaker":"南委員","kind":"確認","question":"そういう点で、何となくこういうふうに説明を受けて、ちょっと抵抗が私はあったので、今まで簡便に借りられたという、そういう現状の中で、すごく違和感というのかしら感じたので、きちんと名前と、だって、生年月日がなくても、名前と住所をきちんと確認すれば、ご本人かどうかは特定できるわけですから、あえて生年月日を入れる必要はないのではないかと非常にこだわっておりますけれども。","respondent":"中元品川図書館長","answer":"委員がおっしゃっていたもともと登録がある方については、こちらでも２年間はデータで画面のほうでわかりますので、委員おっしゃったように、窓口に来て、また紙を書いていただいてと、そのサービスはなくしませんので、次回来るときに証明書をお持ちくださいねということで。","voiceIndex":151,"id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"それで居場所がわからなくなってしまったら、その生年月日を聞いても、その先をどういうふうにするのかというのがちょっとわからないので、ごめんなさい、質問になるのですけれども。","respondent":"中元品川図書館長","answer":"〔「督促もやっているのでしょう」と呼ぶ者あり〕はい、督促も今しています。〔「家まで行くのでしょう」と呼ぶ者あり〕はい、自宅のほうまで伺ったりとかもしている状況です。","voiceIndex":153,"id":"exchange-063"},{"speaker":"阿部委員","kind":"確認","question":"確認しておきたいのですけれども、年間どのくらい逸失図書と言ったらいいのでしょうか、あるのでしょうか。","respondent":"中元品川図書館長","answer":"現在、平成２４年度の１１月末段階で３,４２０冊が不明で、金額にいたしまして６００万円ちょっといってあります。","voiceIndex":156,"id":"exchange-064"},{"speaker":"鶴委員","kind":"確認","question":"済みません、確認で、４番目の利用者の周知で、広報しながわは４月１日号ですけれども、それ以外の媒体はいつからですか。","respondent":"中元品川図書館長","answer":"媒体的には、広報しながわだけになる。はチラシとかポスター掲示という方法です。","voiceIndex":158,"id":"exchange-065"},{"speaker":"高橋委員","kind":"意見","question":"ちょっと、今、損失の話が出たので関連して。わからなかったら後でも結構ですけれども、要するに、貸出の手続きをしないで本を持ち出してしまうというか、そういうような状況がどれぐらいあるのか、もしわかれば、それに対してどういう対応をされているのか。","respondent":"中元品川図書館長","answer":"実はその辺になると、ちょっと数字はつかめないところがあります。今申し上げた３,４２０冊の中に入ってくると、蔵書点検をしたときに、勝手に持ち出されているものも含まれて出てきたりとか、また、いつの間にか戻ってきたりとかすることもあります。","voiceIndex":162,"id":"exchange-066"}]},{"id":"topic-04","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"済みません、まずちょっと事実関係だけ教えてください。スクール・ステイ事業、保育園・幼稚園１２園とありますけれども、これ、幼保の内訳を教えてください。それから、(5)番、指導要録、これ、幼稚園も保育園も指導要録をつくっているのでしたか。認証その他の幼児施設等々は、どんな感じになっていましたでしょうか。もしわかれば、区外の私立幼稚園に通っていらっしゃるお子さんの割合あるいは人数。","respondent":"立川保育課長","answer":"スクール・ステイ事業につきましては、今年度までは、まだ保育園・幼稚園１２園と小学校１２校。","voiceIndex":169,"id":"exchange-067"},{"speaker":"阿部委員","kind":"質問","question":"ありがとうございました。それが交流行事とかということになると人数の問題も出てくると思いますけれども、やはり保育の記録というのは、ほかの施設に通っているお子さんと同様のような内容のものが出てくるといいのではないかと思いますけれども、再度お考えを伺いたいと思います。改めてお考えを伺いたいと思うのですが、いかがでしょうか。","respondent":"立川保育課長","answer":"それで、今後、私立幼稚園に通う保護者の方のご意見等を品川区の保育あるいは幼稚園行政に対するご意見等をいただきました折りには、丁寧に対応させていただきたいとこのように思っております。","voiceIndex":175,"id":"exchange-068"},{"speaker":"南委員","kind":"確認","question":"私のほうで別紙１の乳幼児の発達の全体像というところの４歳、５歳のところでちょっと伺いたいと思ったのですけれども、品川区、ジョイント期、このカリキュラムができるころから、特に力を入れて５歳児の昼寝というのを意識的にしなくなっていますよね。それが今、どの程度、いつごろの時期からそういうふうに実施されているのかというのをまずちょっと伺いたいと思います。","respondent":"立川保育課長","answer":"実施したのは、いわゆる保幼小連携ということで、品川区の教育内容を見直す、平成１９年度以降に、ここのところ、ちょっと資料がないので、ちょっといつ開始したかというのは調べてお話をします。","voiceIndex":178,"id":"exchange-069"},{"speaker":"南委員","kind":"質問","question":"私が伺いたかったのは、その年度当初からと１０月以降という二つの時期に分かれているみたいですけれども、何園ぐらいそれぞれのところにあるのかということと、改めて午睡をしなくなったことの、なぜしなくなったかということをもう一回伺いたいのと、そのことが子どもの成長、心身の発達にとってどんなふうな、やって数年たつと思いますけれども、どんな効果、どのようになっているか。","respondent":"立川保育課長","answer":"なぜしなくなったのかということですけれども、やはり小学校に上がりますと、午睡の時間というのはありませんので、いわゆる生活のリズムを就学に向けて整えていくということで、いわゆる５歳児の昼寝というのはなくしていくほうが。","voiceIndex":180,"id":"exchange-070"},{"speaker":"南委員","kind":"質問","question":"午睡しない、いつの時期からしない園が何園というのは、それは後日、数字を知りたいので教えてください。そういうところの就学に向けての昼寝というのは、同じようにしていないのですか。それに対する健康上の心身の発達上の身体上の問題は、影響が出てくるのではないかと思うけれども、どう配慮しているのでしょうか。","respondent":"立川保育課長","answer":"幼稚園においても預かり保育で残っているお子さんもいますので、やはりその辺はそれぞれの子どもの健康状態をしっかり見ながら保育内容を通じて実施しています。","voiceIndex":182,"id":"exchange-071"},{"speaker":"南委員","kind":"質問","question":"保育園の場合、幼稚園も預かり保育はお迎えに来る時間がそれぞれ違うと思うのです。保育園は特に８時半とか１０時とか、そういう時間に年長児がいる場合も結構あるわけですよね、現実的に。経験上、絶対あると私は言えるのですけれども、そういうところは現実的にどういうふうにしているのですか。かなり厳しいと思いますけれども。","respondent":"立川保育課長","answer":"そういったことがあってはならないということで、引き継ぎについては十分綿密に行っているというのが現状です。","voiceIndex":184,"id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、次回でいいですから、そこはしっかりと具体的な体制について教えていただきたいと回答を求めたいと思います。委員長、ぜひよろしくお願いします。それで、最後に現実を一つ紹介しますが、保育園の現場の方から伺ったのですけれども、夕方５時前後だったと言っていましたけれども、年長の子どもが保育室のロッカーの隅のところで一人で寝ていたという、そういう状況があったということですね。","respondent":"立川保育課長","answer":"そういった報告については受けておりません。","voiceIndex":186,"id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"午睡、長時間保育、午睡をさせなかった年長児というふうに言っていましたので、私はこの話のところでぜひ聞かなくてはと思ったので質問しましたけれども、ぜひ実態を調べていただいて、一律に午睡、５歳だからしないとか、それが当たり前という、そういう対応はしないでいただきたいというのと、体制をしっかりとっていただいて、午睡をさせないのであれば。","respondent":"立川保育課長","answer":"各保育園で午睡の取り扱いですけれども、一律にやるやらないということではなくて、やはり子どもの健康状態を確認しまして、日々の保育の中で判断している部分もあります。","voiceIndex":188,"id":"exchange-074"},{"speaker":"南委員","kind":"質問・要望","question":"今の答弁を受けて最後にしたいと思います。一律にやらないというふうにおっしゃったのですから、やはりそこはしっかり子どもの健康状態、それから、保育される時間の関係も含めて、本当にそこは体制をとって個別に対応していただきたいということなしに、こういう計画はつくったからやれという上からの押しつけはやめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-075"},{"speaker":"阿部委員","kind":"意見","question":"今、午睡の話が出ましたので、意見といいますか、こういう意見もあるということで聞いていただければと思います。私自身も保護者として、ちょうど５歳児、午睡をするしないの過渡期の始まりぐらいのところを経験いたしましたけれども、やはり見ていて、お子さんはすごくこの時期の睡眠のリズムは個人差が大きくて、もう眠れないお子さんも大勢いらっしゃる。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":191,"id":"exchange-076"},{"speaker":"南委員","kind":"質問","question":"４歳、５歳の子どもが１０時、１１時まで起きているということは、昼間しっかり活動していれば普通はあり得ないですよ。小さい子どもは、発達上、体の動きがそういうふうにできているのですから。ですから、そこは親の側の子育てというか、そこのところが一つの問題があるのではないかと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4786#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":78016,"voices":201}},{"id":"h25-20130226-5","meetingId":"h25-cm02","date":"2013年2月26日","dateIso":"2013-02-26","committee":"総務委員会","time":"午前９時５９分～午後０時１０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２５年度都区財政調整","agenda":"の平成２５年度都区財政調整","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"資料の１ページ目から順番にお伺いします。よろしくお願いします。第一の基準財政収入額のところの標準徴収率というのが先ほど９８％というご説明を受けたんですが、どういうことなのかもうちょっと詳しく教えていただきたいのと、その下の三位一体の税源移譲のところで、特例加減算と書いてある、加えたり、減ったりということなんでしょうけれども、このところも、もうちょっと詳しく教えてください。","respondent":"本城企画財政課長","answer":"失礼しました。平成２４年度については全体額が若干増の見込みですが、全体の額の推移で見ますと、平成２０年度が一番のピークになっておりまして、全体として交付金の規模が９,９６０億円ぐらいがピークの時期でございました。","voiceIndex":7,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"順番にいろいろ教えてください。３ページのところの基準財政需要額のところの(2)の投資的経費のところが、２６.２％増となっているんですが、この増の内容というか、主なもの、どういうものがここに入っているのか教えていただきたいのと、あと、３の一番下のところの財源対策の大規模改修経費への臨時的起債充当という、これ、よくわからないので、これも教えてください。","respondent":"本城企画財政課長","answer":"そういう意味では、先ほど実質的な補てん措置ということでご説明させていただきましたが、大規模修繕にかかるものについて、このような取り扱いを今回しているということが一つです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２６.２％の投資的経費のところの増が、５１項目を積み上げてこれだけになったということの受けとめでよろしいんでしょうか。それが１点です。実際に第１回の都議会の定例会のところで決まっていくわけですけれども、品川区の部分において、具体的にまだ出ていないんですが、これはプラスになるのか、マイナスになるのか、その辺、わかる範囲で教えてください。","respondent":"本城企画財政課長","answer":"初めの再調整の額ですが、表の見方としましては、初めの当初算定残というのは全体に、今のフレームということで全体の額を決めて、その後に区別の算定をするんですが、区別の算定をする時期が４月に入ってからということになりますので、その間の人口の推移だとか。","voiceIndex":11,"id":"exchange-003"},{"speaker":"阿久津委員","kind":"質問","question":"１つだけ。今回、新規算定の項目の中に区営住宅維持管理費、これが盛り込まれているんですけれども、私は会計をあまり知らないので、これはやはり都区の間でいろいろ協議があって、今までの背景があって、やっと盛り込まれたのかなと思いますけれども、それは都が判断することなのかもしれませんけれども、その辺の状況を少し教えていただけますか。","respondent":"本城企画財政課長","answer":"区営住宅の維持管理についても、２３区全体として標準的な事務ということで今回新たに捉えて、それを交渉の中で盛り込んでいったというふうに聞いております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"阿久津委員","kind":"質問","question":"最後に、品川区においては、それは金額的にいうとどれぐらいなんですか。大雑把なものでいいんですけれども、どのぐらいのものですか。","respondent":"本城企画財政課長","answer":"ただ、この場合、区営住宅に関しては若干、区営住宅の維持管理に対して住宅の使用料も財源として入ってきますので、その分が使用料が入ることによって、逆に一般財源の負担が少なくなるという逆の関係にありますので。","voiceIndex":15,"id":"exchange-005"}]},{"id":"topic-02","title":"の平成２４年度事務事業評価","agenda":"の平成２４年度事務事業評価","exchanges":[{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ご説明ありがとうございました。何点か質問します。それで、平成２４年度の評価結果一覧でもまた「Ｃ」という事業があって、八十何ページですか、評価の結果の部分で幾つか出ています、でっかい一覧が出ていましたが、平成２２年度「Ｃ」で、平成２４年度もまた「Ｃ」というのは、継続的に見直しを行っていて、さらにもう少し工夫ができるんじゃないかという判断で、見直しが「Ｃ」になったのか。","respondent":"柏原行財政改革担当課長","answer":"平成２２年度の際に「Ｃ」評価で今回も「Ｃ」というのは、ほとんどが委員おっしゃるとおりでございまして、継続的に見直しを図っているです。","voiceIndex":22,"id":"exchange-006"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"そんな中で、一番この事務事業評価であってはならないのが、事務的な労力がものすごく負担になるから、どうしても煩雑になってしまうというのが一番もったいないなと思うので、その点は、今後もし、最後のページにも「より効果的な実施方法の検討も進めていきます」というように記されているんですが、ぜひ、継続的にこの事務事業評価をやっていただけるんであれば、やはりそこが一番。","respondent":"日下部企画部長","answer":"これをご覧いただきますと、「Ｃ」の見直しをする事業、その説明がありますが、「事業の必要性はあるが、その手法・執行体制等見直しが必要な事業」ということでございまして、そういう意味で、ニュアンスの問題なんですが、委員からご指摘がありましたように、ある意味で、一つ。","voiceIndex":24,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全事業の見直しをされたということでは、すごく膨大な量になって大変な作業であったと思いますけれども、議員のところは予算特別委員会で活用するわけですけれども、この冊子は、先ほど、今後、区民への公表、ホームページの掲載と図書館、区政資料コーナー等で閲覧ということになるというご説明だったんですが、この冊子はほかの部分で配る予定があるのかどうか、その辺を１つと、私たちはこれは本当に。","respondent":"柏原行財政改革担当課長","answer":"部数等、そんなに印刷をしませんので、ホームページ等々にも掲載する予定というところがありますので、広く配布するということは特に考えてはございません。","voiceIndex":26,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"冊子は広く配布をしないということだったので、ホームページももちろんダウンロードはできますけれども、区がこれだけ、全部の事業に対して評価を行っているということは広く伝えてほしいので、できたら町会・自治体のところぐらいは冊子をお配りしてもいいのではないかなと思うのと、ぜひご意見をお聞かせくださいと書いてあるので、そういった面では広く意見を聞いて。","respondent":"柏原行財政改革担当課長","answer":"外部評価のことにつきましては、大事な視点であるという認識はあります。ただ、先ほども申しましたとおり、手法につきましては整理すべき課題がありますので、その辺は整理をさせていただきながら検討していきたいと思ってあります。","voiceIndex":28,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面では区民の捉え方の反映がされていない部分もあるというところでは、私は、特に開発のところなんかはもっと丁寧にしていただきたいし、疑問が大きく残っているんですけれども、その点はいかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"改革の部分の評価ですけれども、こちらにつきましては所管での評価、それから事業部経営会議、区全体での評価ということで、必要である事業ということで評価をさせていただいた結果こうなっているといったところです。","voiceIndex":30,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺の評価の仕方というか、「Ａ」で拡充もありますけれどもね、今後に大きな部分を占めていくんですが、何て言うんでしょう、簡易な評価でさらっとやって、ものすごく税金が投入される部分の評価がこのような簡易なものでいいのかなという疑問を抱いておりますので、ぜひ丁寧にやっていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"それが１点と、それから、先ほども申しましたけれども、こちらの事業全部、事業部経営会議で全事業、確認をしておりますので、議論の中でこういう評価を下したです。","voiceIndex":33,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後に。区民の、やはり区民が主体者であるという捉え方においての区の行政なので、ぜひ区民の声をより広く聞いて、評価もしていただきたいなと思います。特に開発のところには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"いろいろ説明しなきゃいけない。その事業に携わっている皆さん、行政の皆さんと、我々、議員なんかはいろいろお聞きしているので中のことがわかるんですけれども、一般の区民からすると簡単なサービス、これが何で受けられないんだとか、これはどうなんだとかという、そういう、どこかでそういう評価をするものというのはあるんでしょうか。","respondent":"柏原行財政改革担当課長","answer":"特に我々企画サイドの部分で、そういった形の広報広聴課でのデータであるとか、そういったところを参考にしながら今回の評価を入れている部分もありますし、窓口全体というよりは、この事業に対してこういうことがあるから。","voiceIndex":37,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"意見だけですが、確かに一生懸命やられて、どんどん事業を前進させて、区民に直結したサービスというところはもちろんあると思うんですが、そういう視点もほんの０.何％、１％でもいいですから、何かありましたらこういうふうに改善していっていますよというのもすごく、区としては、事業部としては評価にもなるわけだし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-014"},{"speaker":"阿久津委員","kind":"質問・要望","question":"意見だけです。私も解決策はないんですけれども、そこのところをぜひ、またお伺いさせていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1940#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":24727,"voices":48}},{"id":"h25-20130227-14","meetingId":"h25-cm02","date":"2013年2月27日","dateIso":"2013-02-27","committee":"行財政改革特別委員会","time":"午前９時５９分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２４年請願第６号 豊葉の杜中学校跡の活用に関する請願","agenda":"平成２４年請願第６号 豊葉の杜中学校跡の活用に関する請願","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"審議に入る前にお願いしたいんですけれども、この請願を出したときと、この地域の状況がちょっと変わってきているというのは、過日も施政方針で区長が、ＪＴアパート跡地を購入するということが正式になされました。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"紹介議員になっている同じ会派のご説明ですから、そういうご事情があるのかなとは思いますけれども、現状では、継続審査ということで、議案にかかっているので、幾つか伺いたいと思うんですけれども、先ほどのご説明で、青稜高校と１年６カ月について契約に向けた大詰めという話がありましたけれども、現状では幾らというか、そういう値段の関係はどういうものに基づいているのか。","respondent":"柏原行財政改革担当課長","answer":"ただ、予算上、こちらは賃借料をいただくということで、歳入の部分で一定程度計上させていただいてございまして、現在予算で出ている金額で申しますと、大きな枠でいいますと、校舎、それから、土地の部分の賃借料につきましては。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"一方、校庭部分は地域で使われていくという見通しがいいのかなと思っているんですけれども、前回の説明では、避難所とこういう高齢者施設というのは、どちらがどちらというわけではない、対立する関係ではないというお話がありましたけれども、ここについては、現状、どんなふうにお考えなのか、改めて伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、避難所の場所ということで、こちらは今後有効に使える場所という考え方を持っているものです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"前回は結論を出して、採択すべきだと主張いたしましたが、今、同じ会派の方が、そういう事情のご説明がありましたので、これは慎重に審議したほうがいいと思いますので、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-004"}]},{"id":"topic-02","title":"の２、報告事項を行います。国家公務員住宅の削減計画","agenda":"の２、報告事項を行います。国家公務員住宅の削減計画","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"区としてすぐに手を挙げるのは、慎重にというお話でしたけれども、基本的には、もし、取得できれば、いろいろな活用方法が出てくるというか、政策的にいろいろな使い道はあると思いますので、積極的にといいますか、できる限り活用できるようにしていただきたいと思うんですけれども、１つ確認したいのは、わかればなんですけれども、基本的に売却に当たるものは、建物がもう使えないとか。","respondent":"柏原行財政改革担当課長","answer":"現在使われている部分、もう既に退去している住宅もあるようですけれども、その辺についても国に確認をとったところ、平成２３年の最初のときに削減すると決めた住宅については、耐震性も含めて何も調査をしていないということでございまして。","voiceIndex":23,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういうことでしたら、ますます二の足を踏むような形になってしまうのかもしれないんですけれども、いろいろな考え方があると思うんですけれども、できれば、もし住宅としてそのまま転用できるとなると、いろいろな活用方法が今後区内においても、道路の工事とかの中で、住宅が集中的に必要になってくるというところも予測されますので、そういうことも含めて、いろいろ検討していただければと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、わかったといっても、国が区にどういう状況で渡すかはまだわからないから、わかったからといってというところもあるんですけれども、少なくとも最近まで人が住んでいたところではあるかと思いますので、築年数などがわからないのかどうかを伺いたいのと、手を挙げるのは厳しいとは言うものの、区としてはどういう取り組みや検討の仕組みを考えているのか、現状を改めて伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、詳細にいつの段階で、どういう状態で来るのかというのは、情報がまだありませんので、そういったところを見きわめながら、基礎的なデータは一応調べてはありますので、その情報を見きわめつつ、検討するということになろうかと。","voiceIndex":26,"id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"時価でというのは、民間に売りたいという思いがあるから、そういう表現をするんだろうと思うんだけれども、地元の自治体とすれば、それを公の形で残してくれというのが、こういう話になると、地元が必ず出てくると思うので、そうした場合には、区長会とか、そういうところで、そのあたりも、国から言われたとおりではなくて、我々は購入するために、どういった計画ができるんだという考え方を。","respondent":"日下部企画部長","answer":"以前でしたら、地元の自治体で、例えば、福祉目的であれば、大体２分の１、半額で払い下げしますというのが当たり前でしたけれども、それがここにきて状況が急速に変わっているということです。","voiceIndex":28,"id":"exchange-008"},{"speaker":"須藤委員","kind":"意見","question":"これが発表になった時期と政権もかわってきているので、考え方もまた少し柔軟性ができると思うので、そのあたりも区としてはしっかり見ていきながら、購入できる、できるだけ我々とすれば、地域の人たちがこれだけの広さは有効に使ってほしいという話に必ずなってくる。民間になってしまえば、マンションにしたり何したりという市場原理の流れに入ってしまう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"区民のことですので、区民の動きによってということで、平成２５年、今年、動きがあるみたいだということでしょうけれども、考え方として、ここの場所にどういう施設、どういう考え方でというのが、全体を考えてからの位置づけになるかと思うんです。そうすると、これからこれに対してもっと広い意味での進め方というのが必要になるかと思うんですけれども、その辺はいかがですか。","respondent":"柏原行財政改革担当課長","answer":"ただ、それをここについてどこがどうしましょうというのは、今決められるものではないんですけれども、トータルの行政需要とかということを考えながら、どのタイミングでその土地が出てくるのか、そういったところも見ながら検討する必要があるとは考えております。","voiceIndex":31,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"話が広がってしまうと思うんですけれども、国がこういうふうになってきている、あとは民間の空き地が出てくるという中で、では、ただ単にここの場所があるから、防災広場をつくればいいということではなくて、全体のニーズとかこれから長期基本計画もあるわけで、その中にどういうふうに組み込んでいくのかとかという見直しをいろいろ図りながら、継続的な、臨機応変に。","respondent":"日下部企画部長","answer":"今もお話がありましたけれども、タイミング的にちょうど平成２５年度、今、内部的にいろいろな準備の検討は進めておりますけれども、平成２５年度がちょうど長期基本計画の中間見直しの時期でもありますので、詳細がなかなかわからないので。","voiceIndex":33,"id":"exchange-011"},{"speaker":"西本委員","kind":"確認","question":"合同宿舎はすごく広いですから、そこを今後どういうふうに売るという動きなのか、それとも、２万m2を買うという形で、何かそういう計画があるのか、たとえば大きい敷地なので、品川区としては予算の関係もいろいろあると、一応買うけれども、半分でいいよね、半分は、売却ではないですけれども、いろいろ考えられるということもできるんですか、その辺は。","respondent":"日下部企画部長","answer":"ですから、とにかく国から具体的なものが何も示されていないので、困ってはおりますけれども、それぞれの地域の置かれている状況とかも含めて、我々は我々なりに、それなりにどういう対応をしていったらいいのかという検討は進めていきたいと考えています。","voiceIndex":35,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"今、東京都の関係をというのがありましたけれども、これに関しては、東京都はどういう協議をしながらやっていこうとか、また別々に考えていこうとか、そのあたりは、何か話し合いは始まっているんですか。","respondent":"日下部企画部長","answer":"ただ、我々も東京都に関係するような内容については、しっかりとお互いに連携を図っていく必要がありますので、これからはそういうことも含めての検討だと思います。","voiceIndex":37,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、その実際の財源は全部一般財源ではなくて、防災広場のお金として、補助金でもらうというと、そういうことが許されるんだったら、今みたいなお金の使い方も許されるとなってしまう気がしてならないんだけれども、だけれども、そういうふうになったほうが、区としては活用の仕方が増えるから、考え方のものが増えるからいいと思うんだけれども、そこら辺というのは。","respondent":"柏原行財政改革担当課長、日下部企画部長","answer":"前段の現在の居住状況ですが、こちらの住宅でいいますと、上の２つ、品川寮と品川第二寮については、もう既に退去済みということで、だれも住んでいないという状況です。２点目の関係ですが、実は東京都との連携というお話をしましたけれども、補助金の話とか、本当に具体的なレベルで何をどうこうという前提には一切立っておりません。","voiceIndex":39,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、何か考えたほうがいいかなというと、変な話、今、日本ペイント、三共も含めて、あそこら辺はいろいろ動きが出てきているわけじゃないですか。そうすると、三共もよくいろいろ言っていて、交換しようとか、代替地とかという話も一時期あったと思うんです、道路の整備の問題だ、何だということで。","respondent":"日下部企画部長","answer":"今ご指摘にありましたような、確かに品川寮とか、あの周辺は、新しい形でのまちづくりの展開というのも、いろいろ可能性が出てきておりますので、今ご指摘のような点も含めて、いろいろな可能性についてしっかりと検討していくことが大事かなと考えております。","voiceIndex":42,"id":"exchange-015"},{"speaker":"鶴委員","kind":"質問","question":"ごく補足的というか、側面的なことを教えてもらいたいんですけれども、わかればという範疇で、小山台住宅は林試の森公園に隣接していて、南門から、まさにこの敷地を抜ける道、目黒との境の道があるんですけれども、南門から住宅街のほうに抜けていく道のあそこの部分も国有地ですね。あそこの通りに貸してもらっている考え方なのかどうかなんですけれども、その辺がわかれば、教えてください。","respondent":"柏原行財政改革担当課長","answer":"詳細があれなんですけれども、林試の森公園があって、その南に住宅があるんですが、引き続き小山台住宅の敷地ということでつながっていますので、道だけ抜けているという感じではない、我々の情報では、小山台住宅の図面を見ますと。","voiceIndex":44,"id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"もし、詳細がわかったら、もともとあそこが農林水産省のまさに林業試験場だったというのがあって、陸つなぎで、そこはもう普通に公共の用に供するということで、あそこが提供しているのかなと思ったんですけれども、あと都に公園が移管したときに、私もまだ詳細は全部見ていないんですけれども、民有地を拡大しようとなったとき、民有地のところで裁判がありまして、その辺の絡みで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"}]},{"id":"topic-03","title":"の３の特定事件調査","agenda":"の３の特定事件調査","exchanges":[{"speaker":"稲川委員","kind":"意見","question":"４番、文章のあれなんですが、４番の２項目めが、「品川区に隣接しており、リニア」というのはこれからの品川区であって、なおかつここの地域は「同時に」ということでなって、歴史的なものを感じるまちというのもあるので、もしあれでしたら、「運河に屋形船や神社等、昔の面影」のところに旧東海道みたいなものを入れていただくといいかなと思ったんですが、どうかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭のところで、「品川区公共施設有効活用プランについて、基本的な考えを確認する」とあるんですけれども、私はこのプランそのものには問題があると思っておりまして、確認だと容認してしまうことになるので、ただ、こういう計画が出ていることは事実ですから、後ろの文章との関係でいえば、「考え方を精査するとともに」であれば、議論したことは事実ですから、「精査する」にしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"ここの意味がよくわからないので、後で教えてください。だけれども、今の街並みをしっかり残しながら、どういう形で観光化を図っていこうなんていうことも含めて、アジアヘッドクオーターの話なんか、ごく一部の線を引いたところは、そんな話はあるけれども、違うところは違う形で、今本当に地域の住民の方が勉強会を始められて、今２つのグループで始まりました。４回と２回やったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校の敷地の減額のところを、区にちょっと伺いたいんですけれども、以前、大間窪小学校だったでしょうか。国有地を購入するときに、教育債を発行すると、結果として１割になるという、あの仕組みそのものは今残っていないのか、それとも、先ほどからの国有地の話だと、時価というか、学校のあの仕組みは今も残っているのか、そこだけちょっと教えていただきたいんです。","respondent":"日下部企画部長","answer":"そうすれば、財源の持ち出しというのは少なくて済むし、トータルでいけば、そっちのほうがお得ですよと。区はこの間一貫して、学校の校地の確保についてはそういう考え方で臨んでおります。","voiceIndex":56,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"それが住民たちに、そういうのがあれば、当然私たちはそれに対して真摯に取り組まなければいけないとは思うんですけれども、もう一つ違う意味での、行財政改革特別委員会ならではのコラボレーションというんですか、住民との、それから協議会という形になるのか、地域住民に問うている中で、どういう人たちを想定しているのか、ちょっとわからないところがありますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5940#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":21277,"voices":65}},{"id":"h25-20130228-17","meetingId":"h25-cm02","date":"2013年2月28日","dateIso":"2013-02-28","committee":"震災対策特別委員会","time":"午前１０時００分～午後２時０５分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"本件は、予定表２の報告事項(1)品川区地域防災計画（平成２４年度修正）","agenda":"本件は、予定表２の報告事項(1)品川区地域防災計画（平成２４年度修正）","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"きょう報告があった中で、最後のところで継続的な見直しという表現、これは当然国や都の上位計画の動きにもよると思うんですが、今後の大まかな目安というんですか、きょう現在では継続的な見直しの域を超えられないかもしれませんが、ペース的なものといいますかどこかで節目があると、あるいはこの委員会であったり、通常の議会の中でも、目安があると議論もしやすいのかなと思ったので。","respondent":"高山防災計画担当課長","answer":"都の担当者に確認したんですが、その後の動きといいますかスケジュール感のようなものは、現段階では全くもって区のほうにお話しできないというようなこともございまして、できるだけそういった情報も引き続き収集するとともに、上位計画の修正内容を。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"確認","question":"それはそれでおいおい、分野が多岐にわたりますから、おそらく分野ごとも踏まえてあると思います。こう見ていると、当然行政から行政の各部署に横断的にまたがる中で、各部署との連携のところだけ確認させてください。行政内での連絡体制、各職員の方、管理職も含めて、あるいは全職員、いろいろな形はあると思うんですが、その辺の防災計画の伝達の仕方というか、情報の共有だとか、その辺を教えてください。","respondent":"高山防災計画担当課長","answer":"委員がプラスアルファの部分というふうにおっしゃった部分ですが、この連携は庁内のみならず、例えば医師会あるいは協力をいただく関係機関、そういった方々との協力なしには、防災計画を実現していくことは不可能ですので、区が持ち合わせないそういった資源。","voiceIndex":7,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"今までの防災計画の本冊に比べると、かなり分厚くなったかなというイメージがあるんですけれど、前にももしかしたらご説明いただいていたら申しわけないんですけれども、もう一回お願いしたいんですが、この厚くなった部分というのは、全体的にそれぞれ詳細が書かれているので、厚くなっているのもあるかと思うんですけれど、今回特に、特徴的にこの部分が、例えば目次の中で章だとか編だとかで。","respondent":"高山防災計画担当課長","answer":"その関係もございまして、２００ページほど増えているというのが一つ。そしてもう一つ、風水害にかかわる部分を先ほどご説明させていただきました。","voiceIndex":9,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"わかりました。資料編に載っていたものを、可能なものについてはこの中に入れているというのが主な、プラスアルファがあるということで。資料編はいつごろいただけるかということと、本冊に載っているものは資料編には載せないというふうになるのか、両方に載せるのか、その辺を教えてください。","respondent":"高山防災計画担当課長","answer":"それで資料編の内容につきましては、基本的には本編と重複しないような形でというふうに考えておりますので、基本的には資料編のみに記載の内容というふうに、整理してまいりたいと考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回の委員会で、この素案に対して議論できる場をぜひ設けてほしいということでお願いをして、正副で取り組んでいただいてありがとうございました。それにもかかわらずここは２万９５棟ということになっているのは、どういうふうに考えたらいいのかというのを一点、まずお聞かせいただきたいと思います。","respondent":"高山防災計画担当課長","answer":"今回、私どもも、どの表現がいいかという考え方の中で、実は平成１９年度の被害想定の考え方も、ゆれ・液状化にかかわる重複部分は、ゆれ・液状化のほうに計上した上で、全体の全壊棟数が足し合わせた数字としてよりわかりやすくなるような形での表現をしていた関係で。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、２万１,５６９棟の中には、火災で焼失するということであるけれども、その前に揺れとかで倒壊をしているというものも１,５００棟近く含まれていると、そういう考え方ということで、それを除いたのがこの２万９５棟という考え方でいいのかということを、改めて確認させていただきたいと思います。","respondent":"高山防災計画担当課長","answer":"１点目は、委員ご指摘のとおりの考え方です。要は重複する部分を含めれば、委員がおっしゃった数字になるです。したがいまして、都の説明の中で、もちろん数字も間違いではないといいますか正しい数字で、ただ言い方を変えているということでよろしいかと思います。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここはスペースもありますし、火災による焼失棟数と倒壊が多いという、常に火災危険度が高いというのが品川区の大きな特徴だと思うんですけれど、そこのところの特徴という点での捉え方はいかがでしょうか。","respondent":"高山防災計画担当課長","answer":"そうした意味では、今回、想定手法を東京都としても大きく変えてきたということもありまして、前回との単純な比較ができない中で、特徴的な事象ということでこの５つ、元禄型関東地震も含めまして、５つ挙げさせていただいたところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと主な取り組みのところに、住宅の耐震化、不燃化、初期消火対策、これが書かれていないんですよね、これがなぜなのか。そういうところで言えば、品川区の特徴というところもあわせて来るわけですけれども、住宅の耐震化、不燃化、初期消火対策、これを主な取り組みの最も重要なところに位置づけていただきたいと思うんですけれど、その点についていかがでしょうか。","respondent":"高山防災計画担当課長","answer":"もちろん予防の重要性も当然、区としても認識しておりますので、その上でこの防災計画の中の第２部が予防ということで、かなりのページを割いて、震災を未然に防ぐということはなかなか困難かと思いますが、被害を最小化する取り組みということで書かせていただいております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところを視点の根本に据えるというのが、私は大事だと思いますし、そういうところでも住宅の耐震化、不燃化、初期消火対策、命を守る予防対策として最も第一に取り組むべきということで、ぜひとも、今後に向けてということになりますけれども、私はこの中にしっかりと位置づけていただきたいということを要望したいと思います。","respondent":"高山防災計画担当課長","answer":"これを今後位置づけていくかという点につきましては、当然この計画を継続的に見直す中で、よりそういった部分を特出しすることによって、この目標自体の進め方、対策の具体がわかりやすいということであれば、内容については考えていきたいと考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、この参考資料の３ページ目の一番下のところで、仮設住宅の建設というのが書かれているんですけれども、焼失棟数ですとか倒壊の棟数という被害の状況は出されているんですけれども、仮設住宅の必要数の見込みについてはどう考えられているのか、どこに書かれているのか、そこら辺のところも教えていただきたいと思います。","respondent":"高山防災計画担当課長","answer":"こちらに関しては、減災目標を説明する中で、２３ページの中ほどですね、上段の丸の３つ目ですが、「災害対策を推進する目的には、災害による人的・物的被害を軽減することのみにとどまらず、区民の生活や都市の活動を早期に復旧させることも含まれている」といったことで。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その１０ページの下、第２部第３編第４章というところなんですけれど、深井戸について整備するということが書かれているんですけれども、これは前に私も、深井戸については東京都も整備を進めていくということで出しているので、品川区も深井戸を整備するということについてはどうなのかとお聞きしたとき、深井戸というのは品川区としては消防水利としてはなかなか。","respondent":"高山防災計画担当課長","answer":"それから２点目の深井戸に関しましては、消防機関の執筆ということもありまして、区で責任を持ってそれをやっていくのかという部分についての最終的なお話はできないんですが、一つはいわゆる統一的な記載の中で。","voiceIndex":25,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"せっかくこういう形で示されたわけですので、ぜひ研究をして進めていただきたいと思います。そういう点で、ぜひ消防水利の充実というところにも取り組んでいただきたいと思います。そして２日目、３日目は東京都が責任を持つということになっているんですけれど、そこら辺の確保というあたりも、実際問題きちんとされるようになるのかということを改めて確認させていただきたいと思います。","respondent":"高山防災計画担当課長","answer":"したがいまして、区内に１２カ所整備されています防災備蓄倉庫からの移動ということで、この点については対応してまいりたいと考えております。そして都区の役割ですが、基本的には初日が区、２日目以降が都といった認識で、区は考えてあります。","voiceIndex":27,"id":"exchange-012"},{"speaker":"吉田委員","kind":"提案","question":"その考え方というんですか、それをどういうふうに進めていくのかをお伺いしたいと思います。","respondent":"高山防災計画担当課長","answer":"それぞれが防災関係機関として主体的に活動していただくといった中で、地域防災計画をつくるに当たっては、それぞれの主体が主体の中で取り組む防災にかかわる内容について、こういった形で取りまとめるといった形で、さまざまな主語が入り乱れるということは。","voiceIndex":29,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"意見をいただいても、品川区ではちょっと当てはまるか、当てはまらないかというところがあるのではないかと思う部分もあるんですけれど、その辺を突っ込んだところ、区ではこれからの方向はどういうふうにしていくんですか。","respondent":"高山防災計画担当課長","answer":"そういったこともありまして、各区の情勢にあわせて、計画に書かれていること全てがその区に当てはまるものではないということは、この計画の性質上ある意味やむを得ないのかなというところもありますが、それはとりもなおさず地域の消防機関、警察機関とお話を進めていく中で。","voiceIndex":31,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり品川区で矛盾のない計画にしていただいて、ぜひその辺は検討していただいて、詰めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問・要望","question":"それから２３ページのところに、同じように目標を達成するための主な対策として、ここには住宅があって、そして道路整備、主要な都市計画道路を整備していくという表記があるので、やはりここのところは、次の見直しのときには、建物を自分たちが建て替えて安全に減災をするんだということが確実にないと、道路整備だけを推進しますよというような根拠になってしまうので。","respondent":"高山防災計画担当課長","answer":"先ほども若干申し上げたかもしれませんが、そういう意味ではこの防災計画、継続的な見直しという部分で考えますと、この部分は総則ですので、総記の段階でありますので、基本的にはこの部分を長く、基本的な考え方に基づいて進めていくというものではありますが。","voiceIndex":34,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"それから８４ページなんですけれども、共同備蓄対策というところで、ここは高層住宅の防災対策の推進というところに関連するんですけれども、共同方式による防災物資の備蓄方策を検討する必要があるというような表記なんですが、やはりここはもう少し強く、この震災対策特別委員会の中でも昨年も今年も、港区などはそこを義務づけるというような形で。","respondent":"高山防災計画担当課長","answer":"そんな中で、新しくできるものについては、そういった共同備蓄庫の設置なども計画段階で盛り込むことが可能かと思うんですが、そういう意味では既存のもの、新しくできるものとさまざまある中で、共同備蓄に関する考え方というのはなかなか、まだまだ検討といいますか。","voiceIndex":36,"id":"exchange-017"},{"speaker":"武内委員","kind":"質問","question":"先ほど鈴木委員は３日分と言っていて、私も前はたしか区が１日で、都が２日で、合計３日分だと思っていたけれど、これを見ると２日分になっているんですけれど、そうすると今までの素案のほうでは都と区で２日分、３日目以降は炊き出しでと。今回、４日目以降になってしまったとすると、３日目の分の食料はどうなるのかと思うんですけれど、その辺あわせて教えてもらえますか。","respondent":"高山防災計画担当課長","answer":"いわゆる物流を確保するということで、東京都から４日目以降という形での指摘を受けたです。基本的な区の考え方としましては、初日が区、２日目、３日目が都というような認識に立っているところです。","voiceIndex":38,"id":"exchange-018"},{"speaker":"武内委員","kind":"確認","question":"その辺がどうしても、こう見ちゃうと炊き出しが４日目以降になってしまったので、３日目はどうなんだろうと単純に思ってしまうんだけど、その辺は大丈夫なんですか。一応確認で。","respondent":"高山防災計画担当課長","answer":"現段階では東京都の防災計画の表現にならうといいますか、東京都にも引き続きそういった要望をする中で、きちんと都と区の役割というものを、都の防災計画上にも書いてほしいということは、引き続き要請していきたいと考えています。","voiceIndex":40,"id":"exchange-019"},{"speaker":"向委員","kind":"質問・要望","question":"それとも例えば、個人情報保護の仕組みのシステムとか、何か体制のことを指しているのか、ちょっとここを確認させてください。それから次の５ページなんですが、ソフト面、ハード面というのが２回出てくるんですね。このソフト面、ハード面について、区民の方とか私も読んで、何となくはわかるものの具体的にどういうことを指しているのか、ちょっとこれも区のお考えを確認させていただきたいんですが。","respondent":"高山防災計画担当課長","answer":"このページで繰り返し出てきて大変恐縮ですが、まさに地域の防災性の向上という説明をする中で、こういったキーワードをどうしても用いる必要があったです。","voiceIndex":42,"id":"exchange-020"},{"speaker":"向委員","kind":"質問・要望","question":"パブリックコメントの回答なので、割とシンプルに書かないといけないかなという気がするんです。なので、そのあたりを配慮していただきたいということで、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-021"},{"speaker":"阿久津委員","kind":"質問・要望","question":"たしか数日前の新聞報道では、各自治体において放射能対策について、防災計画に盛り込むことに苦慮しているというような報道があったと思います。その苦慮がここにも出ているのかなということで。別に不安をあおるつもりはないんですけれども、実際に起きてしまっていることに対して、防災計画に若干記述が少ないのかなということが気になったので、お伺いしたいと思います。","respondent":"高山防災計画担当課長","answer":"都においてヨウ素の配布であるとかそういったことを検討などということもあるんですが、この点については正直申し上げて、なかなか区としても、今後、国などが原子力対策などを進めていく中で、各自治体においてより取り組むべき事項が明確になった段階で。","voiceIndex":45,"id":"exchange-022"},{"speaker":"阿久津委員","kind":"質問・要望","question":"防災計画においても、今後そういうことで具体的なことを載せていくということを、ぜひご検討いただきたいと。今お話もありましたけれども、上位計画の状況を見ながらということもあると思うんですけれども、区としてもそういう意識を持って、今後改訂に望んでいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"全体の組織図のことでちょっとお伺いしたいんですけれども、資料３の２９から３０ページにかけて、おのおの、区の事務または業務大綱というところで、各事業部の業務大綱が載っていますけれども、ここで危機管理室と防災まちづくり事業部の関係について伺いたいと思うんですが。逆に防災まちづくり事業部にとって、危機管理室というのはどのように意識された部署というか機関なのか、教えてください。","respondent":"高山防災計画担当課長","answer":"しかしながら危機管理の部門においては、まず第一報が危機管理室に入ることによって、その後の初動を早く、適切な対応をする部門に早期につなげていく、そのような役割が危機管理部門の主な役割だと考えております。","voiceIndex":48,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"何が言いたいかというと、やはり非常時には、各部署なりで混乱が生じて、そこらの仕切りというか線引きがしっかりしていないと、せっかく整えた役割分担が機能していかない部分があるのではなかろうかと思うんですけれど、そこのところはどういう、先ほどおっしゃっていたように、危機管理室は常時のもので線引きが非常に難しいんですから、その難しい線引きをどういうふうに引かれていくのか。","respondent":"高山防災計画担当課長","answer":"その上で防災部門と当然かぶる部分が出てくる、で、双方が能動的に動くことで、危機への対応が早くなるというふうに考えておりますので、そういう意味ではある程度双方の役割がかぶる部分というのは、当然あってしかるべきかと考えておりますので。","voiceIndex":50,"id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"そのかぶる部分の話で、この間も学校避難所の議論において、教育委員会と防災の部分とでお見合いしてしまった部分があって、どうなっているんだみたいなことがあったので、こういうときもそういうような状態が起こるのではないでしょうかということを伺っているんですけれど。そこはどういうふうに思われますか。","respondent":"鈴木防災課長","answer":"この総務部が、先ほどご指摘いただいたように危機管理部門ですので、災害対策本部に関しては危機管理室も、一部門を責任を持って動かす部隊ということで、日々の危機管理の動きであるとか、役割分担を認識した上で組み込まれているというふうに考えていただければ。","voiceIndex":52,"id":"exchange-026"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり総務部に危機管理室が内包されていて、上位に災害対策本部があるとはいえ、やはり内部組織のことなので、お互い見合ってしまって機動力が発揮できない場合もあろうかと思うので、そこらのところはしっかりと、情報の共有をしながらやっていただきたいと考えていますので、お願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-027"},{"speaker":"木村委員","kind":"意見","question":"このパブリックコメントのことなんですけれども、補助２９号線の問題に対しても大分批判的なことが書いてありますけれども、これはあくまでも東京都が主体としてやっていく事業ということで、行政側から、区からの答弁でも東京都に任せてあるような、説明会が開催されることになっているという説明がありますけれども、これは２０２０年ぐらいまでという話ですけれども。","respondent":"藤田都市計画課長","answer":"このため東京都が今、中心になって説明会等を行ってありますけれども、これについては区のほうとしてもしっかりサポート、支援、連携をしながら進めたいということで、今、一緒にどういうふうに説明会を進めるかとか。","voiceIndex":55,"id":"exchange-028"},{"speaker":"木村委員","kind":"質問・要望","question":"いざというとおかしいんですけれども、時期的にそういうときになれば、半強制的に何かをやっていくような形になる場合もありますが、何分にもこのようにして大変な反対をするような意見が出ている。そういう意味ではやはり行政側としては、東京都がやることでしょうけれども、品川区としてもしっかりと、そういうところで説明会なり何なりやっていただきたいと思います。これは要望としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要援護者の問題でお聞きしたいんですが、資料３の１９６ページに災害時要援護者の安全確保ということで書かれているんですけれども、前に障害者福祉課長とか高齢者福祉課長とか、関係課長も見えてこの問題をここで議論したことがあったと思うんですけれど、そのときには要援護者の支援マニュアルを区としてもつくっていくということで、確認されたと思うんですけれども、ここにその記載がないなと思いまして。","respondent":"高山防災計画担当課長","answer":"マニュアルを作成するというようなくだりは確かにございませんが、支援体制づくりの中で、マニュアルをもとにそういった対応を図ってまいりたいと書かせていただいております。","voiceIndex":58,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大もとのところの区の要援護者支援のマニュアルということで、区としてはつくられるということで確認させていただいてよろしいでしょうか。そこのところはぜひ当事者も含めての計画策定にしていただきたいと思うんですけれど、そこの点、個々の事業者ですとか訓練のマニュアルというのではなくて、区としての大もとの支援マニュアル、支援計画というところでの確認をお願いしたいと思います。","respondent":"高山防災計画担当課長","answer":"実は先だって、東京都福祉保健局がこのマニュアルのいわゆるガイドライン的なものを新たにつくりました。そういったものも踏まえて、福祉部門と連携しながら、品川区に合ったものをつくってまいりたいと考えています。","voiceIndex":60,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"当事者もぜひ含めていただきたいという点ではいかがでしょうか。","respondent":"高山防災計画担当課長","answer":"庁内の障害者部門、高齢者部門の職員といいますか、庁内で検討する中で、マニュアルなどは作成してまいりたいと考えております。","voiceIndex":62,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"続いてお聞きしたいのが、初期消火体制の強化ということが９１ページから書かれているんですけれども、いつも私は、初期消火体制をどう強化して、まちをどう守るかというのがすごく重要な課題だと思っているんですけれども、例えば９４ページのところで、スタンドパイプは平成２４年度中に配備するということで、今、各町会に１本ずつ配備されていると思うんですけれども。","respondent":"鈴木防災課長、山口防災安全担当課長","answer":"現在、これから消防もしくは消防団等とご相談して、各地区におきまして、スタンドパイプの操作の講習であるとか訓練を実施してまいります。消防機関の消防力については、東京消防庁のほうの管轄区域、ほぼ東京都全域でどういうふうに強化していくかというふうに考えてございまして、その中で当然震災対応を考えつつ、どういう資機材を充実、整備していくか。","voiceIndex":64,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この消防力強化、初期消火体制の強化というのは、本当に大事な問題だと思っているんですけれど、スタンドパイプはこれから訓練を各町会で行って、それに基づいてということなんですが、スタンドパイプが配備されたというのはとても画期的なことで、評価できることだと思っていますけれども、さらにこれを早急にしていただいて。","respondent":"鈴木防災課長、山口防災安全担当課長","answer":"地域で助け合うという中で、たまたま組織の構成単位が町会ということだけでありますので、例えば自分の町会の中の火事を町会のメンバーで消すときにも、最寄りの水利を使うとか。やはり消防水利の整備責任は東京消防庁のほうでありまして、東京消防庁のほうでそもそも平常時どのぐらい必要か、あるいは震災時にどういう基準で必要かそういう基準をちゃんとつくっていまして。","voiceIndex":67,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この初期消火対策というのは本当に大事なことだと思っていますので、ぜひ実際に一つ一つの町会でどうなっていくのかというところを見ていただいて、体制をつくっていただきたいと思ってます。そしてマンションのところでも、災害時にじゃあ、実際にどうやってどういうふうに使えるようになるのかというあたりも含めて、いざというときに対応できるような形での充実をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自分の地域は中延三丁目なんですけれど、不燃化特区に位置づけられていて、まちづくり協議会が行われているんですけれど、その中で出された消防水利マップというのを区のほうでつくってくださって、これは消火栓と消火器、防災倉庫、防災広場、そこに貯水槽が何トンぐらいあるか、またＣ級ポンプ、Ｄ級ポンプ、またＡＥＤの場所とかも含めて、こういう形で出していただいたんですけれど。","respondent":"品川防災整備担当課長","answer":"ほかの密集地域においても、まちづくり協議会においてそのようなマップはつくっておりますので、協議会がある地区については、そういうものをつくりながら、密集事業を進めていくという一環としてやっているものです。","voiceIndex":73,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"防火水槽のマップは防火水槽だけのマップということになってくるんでしょうか。じゃあ、網かけされていないところが、網かけされているところに比べて格段に安全かというと、そういうことではないと思いますし、ぜひこれは前向きにご検討いただけたらと思っていますが。","respondent":"鈴木防災課長","answer":"そういう中で、ご意見いただきました消防水利の情報についても、どのような形がよいのかというのは検討してまいりたいと思います。","voiceIndex":75,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、２５ページのところの減災目標の３番目で、ライフラインを６０日以内に９５％以上回復するということが書かれていて、電力、上下水道、通信、ガスということでそれぞれ復旧の目標が書かれているんですけれど、ここに先ほども上水道の耐震化目標はぜひ明記して、東京都にも求めていただきたいということで申し上げましたけれども、電力とか通信、ガスのあたりはちょっとよくわからないんですが。","respondent":"高山防災計画担当課長","answer":"東京都水道局におきましても、水道管路の耐震継手化緊急１０カ年事業ということで計画的に進めておりまして、これまでの耐震化の割合を２４％から、平成３１年度末には４８％まで高めていきたいといった目標を掲げているところです。","voiceIndex":77,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてそれに加えて今回、この安全なまちづくりの実現のトップに、延焼遮断帯ということで道路の整備ということが入っているんですけれども、そして６３ページのところに防災生活圏の形成ということが書かれているんですけれど、この防災生活圏というものの考え方というのは、東京都の防災都市づくり推進計画、これは２０１０年１月に出されたもので。","respondent":"品川防災整備担当課長","answer":"区のほうでは、例えば戸越公園一帯ですとか、林試の森周辺のまちづくり、こういったところで防災生活圏事業というものを行っております。こういう事業を進めながら、形成していく地区のことを、防災生活圏というふうに呼んでおります。","voiceIndex":79,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"改めてその道路が必要なのかどうか、是非を含めての説明会を開いて、そして住民に問うまちづくり、まちづくりとはどうあるべきなのかというところを、住民の中で話し合いながら決定していくというプロセスが必要なのではないかという意見もたくさん出されたのが、きのうの説明会ではなかったかと思うんですけれど、私も実際そう思いますけれども、その点についてはいかがでしょうか。","respondent":"藤田都市計画課長、品川防災整備担当課長","answer":"戦災復興による都市計画決定を経て、今回の補助２９号線、実際に計画道路になったですけれども、まず最初に戦災を復興して、将来のしっかりしたまちづくりを進めるために必要な道路だということで決めたものですので、その後。それで、逃げないで済むように１００ヘクタールができるかどうかということですけれども、これは基本的にやはり不燃化事業というものを徐々に進めていくことによって、燃えないまちをつくっていく。","voiceIndex":81,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、防災整備担当課長が言われたように、やはり一番は耐震化、不燃化、そういうことは道路にかかわりなくどこのまちでも進めていくというのが、一番に命を守る、そしてまちを守るということにつながっていくと思いますので、そういうところでの防災計画という位置づけをぜひしていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-041"},{"speaker":"本多副委員長","kind":"確認","question":"それで、ちょっと確認なんですけれども、防災計画の３１ページから３４ページのところで、２６の関係機関の業務大綱ですとか役割分担が示されております。区の防災計画ですから、関係機関と何度もいろいろな協議をされてきたと思うんです。この２６の関係機関を見ていて、本当に万全かという、その確認をしたい。弱点はないかという点、どう思われるのかお聞かせください。","respondent":"高山防災計画担当課長","answer":"行政体が全力で立ち向かうことはもちろんのことですが、区民一人一人の方々が災害というものを正しく認識して、平時から備えていただく、発災後もそれぞれにおいて対応を、まずは試みていただく、そういった体制も被害を最小化する上で欠かせない視点かと思いますので。","voiceIndex":85,"id":"exchange-042"},{"speaker":"本多副委員長","kind":"確認","question":"この２６ある機関が、万全だよというところを確認したかったんです。それともう一点なんですが、３３ページにその２６機関あるうちの中で鉄道事業者というのがあります。","respondent":"高山防災計画担当課長","answer":"もう一点の、区がどこまで命令権を行使し得るかですが、当然、避難勧告、避難指示といった強制力を伴うものを、区長が発動できるような法整備はされておりますので、そういった部分でリーダーシップを発揮するとともに、防災会議の委員の方も当然。","voiceIndex":87,"id":"exchange-043"},{"speaker":"本多副委員長","kind":"質問・要望","question":"よろしくお願いします。１８６ページにも同じことが書かれています。ターミナル駅周辺の混乱防止ということで、駅周辺混乱防止対策協議会、区や警察や鉄道事業所と情報交換と書かれているんですが、その辺をしっかりと、情報交換にとどまることなく、しっかりと責任の明確化をしていっていただきたいと思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-044"}]},{"id":"topic-02","title":"(2)を聴取いたします。 津波自主避難マップ作成マニュアル","agenda":"(2)を聴取いたします。 津波自主避難マップ作成マニュアル","exchanges":[{"speaker":"阿久津委員","kind":"質問","question":"最後にご報告がありました津波避難ビルの指定に関して、協定が結べそうだという話がありまして、町場を歩いていても本当によく言われまして、ただまだ一つも決まっていないんですというご説明はしていたんですけれども、具体的な名前というのは、今は出せる状況なんでしょうか。もしよろしければ教えていただければと思います。","respondent":"武藤河川下水道課長","answer":"当然、逃げる場所ですので、地域の方々にご説明するということは当然なんですけれども、例えば広くＰＲすること等につきましては、やはり相手方の意向等を確認した上で進めなければならないということで、ちょっと相手方にその辺の確認を現在とらせていただいているところなので。","voiceIndex":94,"id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問・要望","question":"わかりました。よく理解できるところですので、ぜひうまくいくように進めていっていただきたいと思います。これが広がればいいなと考えています。周知すればいいというものでもないという、それもよくわかりますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-046"},{"speaker":"武内委員","kind":"確認","question":"そうすると、今、民間で初めてという話なんですけれど、確認なんですけれど、区の施設は指定というか、ここはという位置づけになっているのはあるんでしたっけ。","respondent":"武藤河川下水道課長","answer":"ただし、やはり施設の閉庁時につきましては、いろいろなセキュリティーの問題だとか、対応の問題とかがございまして、現在避難所に指定されているところにつきましては地域の方々の協力もありますが、その他の区の施設につきましては、閉庁時間。","voiceIndex":97,"id":"exchange-047"},{"speaker":"武内委員","kind":"質問・要望","question":"やはり民間のほうにお願いしていく以上は、区のほうもしっかりその辺の体制を、私もわかりませんけれど、全部の区の施設が大丈夫なのかという疑問もちょっとあるんですね。あわせて伺いますけれど、これは自主避難マップなんですけれども、基本的にハザードマップみたいなものをつくる予定はないということでよろしいでしょうか。","respondent":"武藤河川下水道課長","answer":"区有施設につきましては、今ご説明しましたが、当然委員ご指摘のとおり、低いところにつきましては危険性等も考えられることから、お配りしましたＡ３の津波自主避難マップには、３階以上で耐震化している区有施設については、色づけをして明示しています。","voiceIndex":99,"id":"exchange-048"},{"speaker":"武内委員","kind":"質問・要望","question":"この地図で、３階以上は緑で区有施設と、そうするとここは普通に考えれば２.６１メートルが最大、万が一条件が全て悪い場合に２.６１メートルという中で、３階建てのここは、基本は津波避難ビル的な位置づけというふうに認識していいのかどうかという確認と、あとハザードマップは、私もハザードマップをつくれというつもりはないんです。勘違いして。","respondent":"武藤河川下水道課長","answer":"第２点目の区有施設への対応につきましては、委員ご指摘のとおりでございまして、当然区民の方々からすれば、区有施設というものはやはり、一定の逃げる場所として期待をしているところでもありますので、そういった部分への対応は今後も進めてまいりたいと考えています。","voiceIndex":101,"id":"exchange-049"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員長","kind":"質問・要望","question":"そのように報告します。２点目です。当初の日程によれば、４月、５月にも改めて今期のまとめを作成するという方向で記載させていただきましたけれども、正副委員長としては今期のまとめを作成するに当たって、委員会の総意で、出すか、出さないかも含めて決めていきたいと考えておりますので、皆様のそのあたりのご意見を伺いたいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-050"},{"speaker":"渡辺委員","kind":"提案","question":"今の今の意見というよりは、ちょっと何日か日をおいていただいて、委員長宛てに出す、出さないも含めて、中身のご提案もさせていただければと思うんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-051"},{"speaker":"大沢委員","kind":"質問","question":"今、渡辺委員が発言しましたように、この内容についてはしばし時間をいただきながらということで、基本的にはやはりこの１年間委員会を進めてきたわけですから、成果物としてしっかりと出すべきだと、自民党は考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-052"},{"speaker":"渡辺委員","kind":"意見","question":"今のとおりで、というのは中間まとめが、ペーパーをさっきから見ていて、きれいにまとまっていて、ここに、意味合いとしたら一部その後の議論を修正で追加、という形のイメージを持っていました。その点の手直しを含めて、どの程度のボリュームだとかに対して、締め切りを設けられたらと、そういう意味です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-053"},{"speaker":"武内委員","kind":"質問・要望","question":"やはり特別委員会ですのでしっかりと、中間まとめは中間まとめとして、それとは別にこの１年の１つの委員会の中での考え方、また充実してもらいたいもの等々を１つのまとめとして、議長、また議長から区長にという流れが今できていますので、その辺も含めて、まとめはやっていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-054"},{"speaker":"高橋委員","kind":"質問・要望","question":"まとめをつくっていただければと思います。この中間まとめでお話、いろいろ要望したことが地域防災計画に反映しているものもあれば、まだ皆さんいろいろ意見もあったりしますけれども、そういうことも含めてまとめていったほうがいいのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-055"},{"speaker":"井上委員","kind":"提案","question":"まとめは出すということで。まとめの形として、今まではこういう形で計画に反映するようにという提案でいったんですけれども、これが計画ができたので、それに対して今後どう委員会として伝えていくのかということのまとめのほうが、いいのではないかと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この計画はできていますけれど、これからも継続して見直していくということですので、計画で見直してほしいというところはこういう形でまとめられて出していったわけですから、その後の部分で審議をされた中身をぜひまとめて、またきちんと出していくという方向でしていただきたいと思いますし、そのためにはあと４月と５月になるわけですよね、委員会が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-057"},{"speaker":"大沢委員","kind":"意見","question":"両者言っていることは同じで、しっかりとまとめを出すべきだというふうに考えております。皆さんと同じです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6426#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":54031,"voices":129}}]);
